window.__QUIZ_DATA__ = {"title":"Ngân hàng trắc nghiệm An toàn mạng máy tính","count":414,"sourceCounts":{"default":414},"questions":[{"id":"gen_003","chapter":"1","question":"Tính bí mật (Confidentiality) trong mô hình CIA nghĩa là gì?","options":{"A":"Thông tin không bị sửa đổi trái phép","B":"Hệ thống luôn sẵn sàng khi người dùng cần","C":"Xác minh đúng danh tính người gửi","D":"Chỉ người được phép mới đọc được thông tin"},"answer":"D","family":"g01c1","style":"distinction","section":"1.2-1.4","source":"Đề cương mục 1.2-1.4; slide Bài 1","explanation":"Bí mật (Confidentiality) là chỉ người được cấp quyền mới đọc được thông tin; người khác không xem được nội dung.","optionNotes":{"A":"Không bị sửa đổi trái phép là tính toàn vẹn (Integrity), không phải bí mật.","B":"Luôn sẵn sàng khi cần là tính sẵn sàng (Availability).","C":"Xác minh danh tính là xác thực (Authentication), không thuộc ba chữ của CIA."}},{"id":"gen_006","chapter":"1","question":"Biện pháp nào chủ yếu bảo vệ tính toàn vẹn của dữ liệu?","options":{"A":"Mã hóa dữ liệu để người ngoài không đọc được nội dung","B":"Sao lưu dự phòng để khôi phục khi hỏng","C":"Dùng giá trị băm để phát hiện dữ liệu bị sửa","D":"Tăng băng thông để giảm nghẽn mạng"},"answer":"C","family":"g01c2","style":"distinction","section":"1.2-1.4","source":"Đề cương mục 1.2-1.4; slide Bài 1","explanation":"Giá trị băm thay đổi khi dữ liệu bị sửa dù chỉ một bit, nên so sánh băm phát hiện được dữ liệu mất toàn vẹn.","optionNotes":{"A":"Mã hóa che nội dung, tức bảo vệ tính bí mật; nó không tự báo khi dữ liệu bị sửa.","B":"Sao lưu giúp khôi phục sau sự cố, chủ yếu phục vụ tính sẵn sàng, không phát hiện sửa đổi.","D":"Băng thông chỉ ảnh hưởng tốc độ và tính sẵn sàng, không liên quan việc dữ liệu bị sửa."}},{"id":"gen_009","chapter":"1","question":"Tấn công DoS/DDoS vi phạm trực tiếp thuộc tính nào?","options":{"A":"Tính sẵn sàng","B":"Tính bí mật","C":"Tính toàn vẹn","D":"Tính chống chối bỏ"},"answer":"A","family":"g01c3","style":"distinction","section":"1.2-1.4","source":"Đề cương mục 1.2-1.4; slide Bài 1","explanation":"DoS/DDoS làm dịch vụ quá tải để người dùng hợp lệ không truy cập được, tức tấn công vào tính sẵn sàng.","optionNotes":{"B":"DoS không đọc trộm dữ liệu, nên không vi phạm trực tiếp tính bí mật.","C":"DoS không sửa dữ liệu, nên không vi phạm trực tiếp tính toàn vẹn.","D":"Chống chối bỏ liên quan việc chứng minh ai đã gửi/thực hiện; DoS không đụng tới điều này."}},{"id":"gen_011","chapter":"1","question":"Máy chủ yêu cầu chứng minh người đăng nhập là chủ tài khoản. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"Tính sẵn sàng","B":"Xác thực","C":"Tính bí mật","D":"Tính toàn vẹn"},"answer":"B","family":"g01c4","style":"scenario","section":"1.2-1.4","source":"Đề cương mục 1.2-1.4; slide Bài 1","explanation":"Chứng minh người đăng nhập đúng là chủ tài khoản chính là xác thực (authentication).","optionNotes":{"A":"Sẵn sàng là dịch vụ hoạt động khi cần, không phải kiểm tra danh tính.","C":"Bí mật là giữ nội dung không bị đọc trộm, không phải xác minh người dùng.","D":"Toàn vẹn là dữ liệu không bị sửa trái phép, không phải xác minh người dùng."}},{"id":"gen_012","chapter":"1","question":"Xác thực (authentication) là quá trình gì?","options":{"A":"Cấp quyền truy cập tài nguyên cho người dùng sau khi đã đăng nhập","B":"Xác minh chủ thể đúng là người hoặc thiết bị nó tự nhận","C":"Mã hóa dữ liệu trước khi gửi đi","D":"Ghi nhật ký hoạt động của người dùng"},"answer":"B","family":"g01c4","style":"distinction","section":"1.2-1.4","source":"Đề cương mục 1.2-1.4; slide Bài 1","explanation":"Xác thực trả lời câu hỏi \"anh có đúng là người/thiết bị anh nhận không\", ví dụ qua mật khẩu, mã OTP, chứng thư.","optionNotes":{"A":"Cấp quyền sau khi đăng nhập là phân quyền (authorization), diễn ra sau xác thực.","C":"Mã hóa dữ liệu bảo vệ tính bí mật, không xác minh danh tính.","D":"Ghi nhật ký là kiểm toán (accounting/audit), không phải xác thực."}},{"id":"gen_014","chapter":"1","question":"Nếu kẻ lạ bắt gói trên wi-fi mở để đọc thông tin, hiện tượng nào đang xảy ra?","options":{"A":"Người đứng giữa","B":"Nghe lén","C":"Mạo danh","D":"Phát lại"},"answer":"B","family":"g02c1","style":"scenario","section":"1.3-1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"Chỉ bắt gói để đọc mà không sửa hay chen vào là nghe lén (eavesdropping/sniffing).","optionNotes":{"A":"Người đứng giữa chen vào giữa hai bên và có thể sửa thông điệp; ở đây kẻ lạ chỉ đọc.","C":"Mạo danh là giả làm nguồn hợp lệ; tình huống không có việc giả danh.","D":"Phát lại là gửi lại gói cũ; tình huống chỉ có đọc gói."}},{"id":"gen_015","chapter":"1","question":"Biện pháp nào giảm rủi ro bị nghe lén trên đường truyền?","options":{"A":"Tăng dung lượng ổ cứng và bộ nhớ RAM cho máy chủ","B":"Đổi tên máy tính trong mạng","C":"Tắt tường lửa để giảm độ trễ","D":"Mã hóa kênh truyền, ví dụ TLS hoặc VPN"},"answer":"D","family":"g02c1","style":"distinction","section":"1.3-1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"Mã hóa kênh truyền (TLS, VPN) làm gói bắt được chỉ là dữ liệu mã hóa, kẻ nghe lén không đọc được.","optionNotes":{"A":"Ổ cứng và RAM chỉ tăng hiệu năng máy chủ, không che dữ liệu trên đường truyền.","B":"Đổi tên máy không làm thay đổi việc gói tin truyền ở dạng rõ.","C":"Tắt tường lửa làm hệ thống kém an toàn hơn, không giảm nghe lén."}},{"id":"gen_017","chapter":"1","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Gói tin mang địa chỉ nguồn không thuộc máy gửi?","options":{"A":"Người đứng giữa","B":"Mạo danh","C":"Phát lại","D":"Nghe lén"},"answer":"B","family":"g02c2","style":"scenario","section":"1.3-1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"Gói tin ghi địa chỉ nguồn của máy khác là giả mạo nguồn, tức mạo danh (spoofing).","optionNotes":{"A":"Người đứng giữa chen vào chuyển tiếp/sửa thông điệp; ở đây chỉ là sửa địa chỉ nguồn.","C":"Phát lại là gửi lại gói hợp lệ cũ, không phải ghi sai địa chỉ nguồn.","D":"Nghe lén chỉ đọc gói tin, không tạo gói giả."}},{"id":"gen_018","chapter":"1","question":"Mạo danh (spoofing) là kiểu tấn công nào?","options":{"A":"Làm quá tải dịch vụ bằng rất nhiều yêu cầu gửi cùng lúc từ nhiều máy","B":"Đọc trộm gói tin mà không sửa đổi","C":"Dò mật khẩu bằng cách thử lần lượt","D":"Giả làm một nguồn hợp lệ, như IP hoặc MAC của máy khác"},"answer":"D","family":"g02c2","style":"distinction","section":"1.3-1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"Spoofing là giả làm một nguồn hợp lệ, ví dụ dùng IP hoặc MAC của máy khác để được tin cậy.","optionNotes":{"A":"Làm quá tải bằng nhiều máy là DDoS.","B":"Đọc trộm gói mà không sửa là nghe lén.","C":"Thử lần lượt mật khẩu là tấn công vét cạn (brute force)."}},{"id":"gen_020","chapter":"1","question":"Kẻ tấn công lặp một yêu cầu xác thực cũ. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"Mạo danh","B":"Phát lại","C":"Nghe lén","D":"Người đứng giữa"},"answer":"B","family":"g02c3","style":"scenario","section":"1.3-1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"Ghi lại một yêu cầu xác thực hợp lệ rồi gửi lại là tấn công phát lại (replay).","optionNotes":{"A":"Mạo danh là giả địa chỉ/danh tính nguồn, không nhất thiết dùng lại gói cũ.","C":"Nghe lén chỉ đọc gói, không gửi lại.","D":"Người đứng giữa chuyển tiếp và có thể sửa thông điệp theo thời gian thực, không phải lặp gói cũ."}},{"id":"gen_023","chapter":"1","question":"Xét tình huống: Kẻ tấn công chuyển tiếp rồi sửa thông điệp giữa khách và máy chủ. Cách gọi đúng là gì?","options":{"A":"Mạo danh","B":"Phát lại","C":"Người đứng giữa","D":"Nghe lén"},"answer":"C","family":"g02c4","style":"scenario","section":"1.3-1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"Đứng giữa khách và máy chủ, chuyển tiếp rồi sửa thông điệp là tấn công người đứng giữa (MITM).","optionNotes":{"A":"Mạo danh chỉ giả danh tính nguồn; ở đây kẻ tấn công còn chen vào giữa và sửa nội dung.","B":"Phát lại gửi lại gói cũ nguyên vẹn, không sửa nội dung trên đường đi.","D":"Nghe lén chỉ đọc, không chuyển tiếp hay sửa thông điệp."}},{"id":"gen_026","chapter":"1","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Một máy liên tục gửi yêu cầu khiến cổng web quá tải?","options":{"A":"DoS","B":"Lừa đảo phishing","C":"Tràn bộ đệm","D":"DDoS"},"answer":"A","family":"g03c1","style":"scenario","section":"1.3-1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"Chỉ một máy gửi dồn dập yêu cầu làm dịch vụ quá tải là DoS (một nguồn).","optionNotes":{"B":"Phishing lừa người dùng bằng email/trang giả, không làm quá tải máy chủ.","C":"Tràn bộ đệm là ghi dữ liệu vượt vùng nhớ trong chương trình, không phải gửi dồn yêu cầu.","D":"DDoS cần nhiều nguồn phối hợp; ở đây chỉ có một máy."}},{"id":"gen_035","chapter":"1","question":"Nếu email giả ngân hàng dẫn đến trang đăng nhập nhái, hiện tượng nào đang xảy ra?","options":{"A":"DDoS","B":"Lừa đảo phishing","C":"DoS","D":"Tràn bộ đệm"},"answer":"B","family":"g03c4","style":"scenario","section":"1.3-1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"Email giả ngân hàng dẫn tới trang đăng nhập nhái để lấy tài khoản là lừa đảo phishing.","optionNotes":{"A":"DDoS làm quá tải dịch vụ từ nhiều nguồn, không dùng email giả.","C":"DoS làm quá tải dịch vụ, không lừa người dùng nhập thông tin.","D":"Tràn bộ đệm là lỗi bộ nhớ chương trình, không phải lừa đảo qua email."}},{"id":"gen_044","chapter":"1","question":"Nếu đăng nhập cần mật khẩu và mã từ thiết bị sở hữu, hiện tượng nào đang xảy ra?","options":{"A":"Xác thực đa yếu tố","B":"Đặc quyền tối thiểu","C":"Phòng thủ nhiều lớp","D":"Quản lý bản vá"},"answer":"A","family":"g04c3","style":"scenario","section":"1.2-1.5","source":"Đề cương mục 1.2-1.5; slide Bài 1","explanation":"Mật khẩu (thứ biết) cộng mã từ thiết bị (thứ có) là hai yếu tố khác loại, tức xác thực đa yếu tố (MFA).","optionNotes":{"B":"Đặc quyền tối thiểu là chỉ cấp quyền vừa đủ cho công việc, không nói về cách đăng nhập.","C":"Phòng thủ nhiều lớp là xếp nhiều lớp bảo vệ khác nhau (firewall, IDS, vá lỗi...) cho cả hệ thống, không phải hai yếu tố trong một lần đăng nhập.","D":"Quản lý bản vá là cập nhật bản sửa lỗi phần mềm."}},{"id":"gen_047","chapter":"1","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Máy chủ cài bản sửa lỗi sau khi đánh giá tương thích?","options":{"A":"Đặc quyền tối thiểu","B":"Xác thực đa yếu tố","C":"Phòng thủ nhiều lớp","D":"Quản lý bản vá"},"answer":"D","family":"g04c4","style":"scenario","section":"1.2-1.5","source":"Đề cương mục 1.2-1.5; slide Bài 1","explanation":"Đánh giá tương thích rồi cài bản sửa lỗi là quy trình quản lý bản vá.","optionNotes":{"A":"Đặc quyền tối thiểu là giới hạn quyền của tài khoản, không phải cài bản sửa lỗi.","B":"Xác thực đa yếu tố là đăng nhập bằng nhiều yếu tố.","C":"Phòng thủ nhiều lớp là kết hợp nhiều biện pháp; việc cài bản vá chỉ là một biện pháp cụ thể."}},{"id":"case_01","chapter":"1","question":"Một người lạ chỉ xem được hồ sơ sinh viên, không sửa hay xóa dữ liệu. Thuộc tính nào bị xâm phạm trực tiếp?","options":{"A":"Tính sẵn sàng","B":"Tính bí mật","C":"Tính toàn vẹn","D":"Tính không chối bỏ"},"answer":"B","family":"g01c1","style":"application","section":"1.2-1.4","source":"Đề cương mục 1.2-1.4; slide Bài 1","explanation":"Người lạ xem được hồ sơ nhưng không sửa, không xóa: dữ liệu bị lộ, tức tính bí mật bị xâm phạm.","optionNotes":{"A":"Hệ thống vẫn hoạt động, nên tính sẵn sàng không bị ảnh hưởng.","C":"Dữ liệu không bị sửa, nên tính toàn vẹn còn nguyên.","D":"Không chối bỏ liên quan chứng minh hành động của một bên, không phải việc lộ dữ liệu."}},{"id":"case_02","chapter":"1","question":"Kẻ tấn công đổi số tiền trong giao dịch nhưng dịch vụ vẫn hoạt động bình thường. Mục tiêu bảo vệ nào bị phá vỡ?","options":{"A":"Tính toàn vẹn","B":"Tính sẵn sàng","C":"Tính bí mật","D":"Tính xác thực người dùng"},"answer":"A","family":"g01c2","style":"application","section":"1.2-1.4","source":"Đề cương mục 1.2-1.4; slide Bài 1","explanation":"Số tiền giao dịch bị đổi là dữ liệu bị sửa trái phép, tức tính toàn vẹn bị phá vỡ.","optionNotes":{"B":"Dịch vụ vẫn hoạt động bình thường, nên tính sẵn sàng không bị ảnh hưởng.","C":"Vấn đề là dữ liệu bị sửa chứ không phải bị đọc trộm.","D":"Tình huống không nói về việc giả danh người dùng mà về nội dung bị thay đổi."}},{"id":"case_03","chapter":"1","question":"Cổng đăng ký học phần không truy cập được vì bị làm quá tải; dữ liệu chưa có dấu hiệu bị đọc hoặc sửa. Thuộc tính bị ảnh hưởng trước tiên là gì?","options":{"A":"Tính toàn vẹn","B":"Tính không chối bỏ","C":"Tính bí mật","D":"Tính sẵn sàng"},"answer":"D","family":"g01c3","style":"application","section":"1.2-1.4","source":"Đề cương mục 1.2-1.4; slide Bài 1","explanation":"Cổng không truy cập được do quá tải là mất tính sẵn sàng; dữ liệu chưa bị đọc hay sửa.","optionNotes":{"A":"Dữ liệu chưa bị sửa, nên toàn vẹn chưa bị ảnh hưởng.","B":"Không chối bỏ không liên quan việc dịch vụ ngừng phục vụ.","C":"Dữ liệu chưa bị đọc trộm, nên bí mật chưa bị ảnh hưởng."}},{"id":"case_04","chapter":"1","question":"Hàng nghìn máy ở nhiều mạng cùng gửi lưu lượng làm máy chủ ngừng phục vụ. Dấu hiệu nào phân biệt rõ nhất DDoS với DoS một nguồn?","options":{"A":"Mục tiêu phải là máy chủ web","B":"Kẻ tấn công bắt buộc biết mật khẩu quản trị","C":"Dữ liệu trên máy chủ bắt buộc bị sửa","D":"Lưu lượng tấn công phát từ nhiều nguồn phối hợp"},"answer":"D","family":"case_04","style":"application","section":"1.3-1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"Điểm khác cốt lõi của DDoS là lưu lượng đến từ nhiều nguồn phối hợp (thường là botnet), còn DoS chỉ từ một nguồn.","optionNotes":{"A":"Cả DoS và DDoS đều có thể nhắm vào bất kỳ dịch vụ nào, không riêng máy chủ web.","B":"Cả hai đều không cần mật khẩu quản trị; chúng chỉ làm quá tải dịch vụ.","C":"Cả hai tấn công tính sẵn sàng và thường không sửa dữ liệu."}},{"id":"case_05","chapter":"1","question":"Một yêu cầu chuyển tiền hợp lệ bị ghi lại rồi gửi lại nguyên vẹn lần thứ hai. Cơ chế nào giúp máy chủ nhận ra yêu cầu cũ?","options":{"A":"Chỉ mã hóa nội dung yêu cầu","B":"Nonce hoặc mã giao dịch dùng một lần","C":"Chỉ tăng băng thông mạng","D":"Chỉ đổi cổng dịch vụ"},"answer":"B","family":"case_05","style":"application","section":"1.3-1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"Nonce hoặc mã giao dịch dùng một lần giúp máy chủ nhận ra yêu cầu đã dùng rồi và từ chối bản gửi lại.","optionNotes":{"A":"Mã hóa không ngăn phát lại: kẻ tấn công gửi lại nguyên gói mã hóa vẫn hợp lệ.","C":"Băng thông không giúp phân biệt yêu cầu mới với yêu cầu cũ.","D":"Đổi cổng không làm yêu cầu cũ mất hiệu lực."}},{"id":"case_06","chapter":"1","question":"Kẻ tấn công đứng giữa ứng dụng và máy chủ, đọc rồi sửa phản hồi trên đường truyền. Biện pháp nào trực tiếp giảm rủi ro này?","options":{"A":"Chỉ chặn tải tệp đính kèm","B":"Xác thực chứng thư máy chủ và dùng kênh mã hóa hợp lệ","C":"Chỉ sao lưu cơ sở dữ liệu hằng ngày","D":"Chỉ đặt mật khẩu dài hơn cho tài khoản"},"answer":"B","family":"case_06","style":"application","section":"1.3-1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"Kiểm tra chứng thư máy chủ và dùng kênh mã hóa hợp lệ (TLS) làm kẻ đứng giữa không đọc và không sửa được dữ liệu mà không bị phát hiện.","optionNotes":{"A":"Chặn tệp đính kèm không ngăn việc đọc/sửa phản hồi trên đường truyền.","C":"Sao lưu chỉ giúp khôi phục, không bảo vệ dữ liệu đang truyền.","D":"Mật khẩu dài chống đoán mật khẩu, không chống chen vào kênh truyền."}},{"id":"case_07","chapter":"1","question":"Tài khoản chỉ cần xem báo cáo nhưng lại có quyền xóa dữ liệu gốc. Cần áp dụng nguyên tắc nào?","options":{"A":"Chia sẻ tài khoản chung","B":"Bỏ ghi nhật ký truy cập","C":"Mặc định cho phép","D":"Đặc quyền tối thiểu"},"answer":"D","family":"g04c2","style":"application","section":"1.2-1.5","source":"Đề cương mục 1.2-1.5; slide Bài 1","explanation":"Tài khoản chỉ cần xem thì chỉ nên có quyền xem: đó là nguyên tắc đặc quyền tối thiểu.","optionNotes":{"A":"Chia sẻ tài khoản chung làm mất trách nhiệm từng người, ngược với yêu cầu bảo mật.","B":"Bỏ ghi nhật ký làm khó điều tra sự cố, không giải quyết việc thừa quyền.","C":"Mặc định cho phép mở rộng quyền thay vì thu hẹp."}},{"id":"case_08","chapter":"1","question":"Một website đã có firewall nhưng vẫn cần giám sát xâm nhập và quản lý bản vá. Cách tiếp cận này minh họa điều gì?","options":{"A":"Phòng thủ nhiều lớp","B":"Tắt toàn bộ dịch vụ để loại rủi ro","C":"Chỉ cần bảo vệ ở tầng vật lý","D":"Một lớp bảo vệ là đủ"},"answer":"A","family":"g04c1","style":"application","section":"1.2-1.5","source":"Đề cương mục 1.2-1.5; slide Bài 1","explanation":"Kết hợp firewall, giám sát xâm nhập và vá lỗi là nhiều lớp bảo vệ chồng lên nhau, tức phòng thủ nhiều lớp (defense in depth).","optionNotes":{"B":"Tắt toàn bộ dịch vụ làm mất tính sẵn sàng, không phải cách bảo vệ.","C":"Tình huống dùng nhiều lớp kỹ thuật, không chỉ tầng vật lý.","D":"Tình huống cho thấy một lớp (firewall) là chưa đủ."}},{"id":"case_09","chapter":"1","question":"Hệ thống yêu cầu mật khẩu rồi gửi mã đến điện thoại của người dùng. Vì sao đây là xác thực đa yếu tố?","options":{"A":"Mã điện thoại luôn là sinh trắc học","B":"Kết hợp yếu tố biết và yếu tố sở hữu","C":"Không cần xác minh danh tính nữa","D":"Sử dụng hai mật khẩu khác nhau"},"answer":"B","family":"case_09","style":"application","section":"1.2-1.5","source":"Đề cương mục 1.2-1.5; slide Bài 1","explanation":"Mật khẩu là yếu tố \"biết\", điện thoại nhận mã là yếu tố \"sở hữu\"; hai loại khác nhau nên là đa yếu tố.","optionNotes":{"A":"Mã gửi qua điện thoại là yếu tố sở hữu, không phải sinh trắc học.","C":"MFA vẫn là xác minh danh tính, chỉ chặt hơn.","D":"Hai mật khẩu đều là yếu tố \"biết\", nên chỉ là một loại yếu tố."}},{"id":"case_10","chapter":"1","question":"Ứng dụng chép dữ liệu đầu vào dài vào vùng nhớ cố định mà không kiểm tra biên. Nguy cơ kỹ thuật trực tiếp là gì?","options":{"A":"Giả mạo SSID","B":"Tràn bộ đệm","C":"Tấn công từ chối dịch vụ phân tán","D":"Tấn công phát lại"},"answer":"B","family":"g03c3","style":"application","section":"1.3-1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"Chép dữ liệu dài vào vùng nhớ cố định mà không kiểm tra độ dài sẽ ghi đè vùng nhớ kế bên, tức tràn bộ đệm.","optionNotes":{"A":"Giả mạo SSID là tấn công mạng không dây, không liên quan lỗi xử lý đầu vào.","C":"DDoS là làm quá tải từ nhiều nguồn, không phải lỗi chép dữ liệu.","D":"Phát lại là gửi lại gói cũ, không phải lỗi bộ nhớ."}},{"id":"reviewed_atm_9","chapter":"1","question":"Một website bị hàng nghìn máy nhiễm cùng gửi yêu cầu làm cạn tài nguyên. Kiểu tấn công nào phù hợp nhất?","options":{"A":"MITM","B":"DoS một nguồn","C":"DDoS","D":"Phishing"},"answer":"C","family":"source_9","style":"review","section":"1.6","source":"https://pttp-huitquiz.site/","explanation":"Hàng nghìn máy nhiễm (botnet) cùng gửi yêu cầu là tấn công từ nhiều nguồn, tức DDoS.","optionNotes":{"A":"MITM chen vào giữa để đọc/sửa thông điệp, không làm cạn tài nguyên.","B":"DoS một nguồn chỉ có một máy tấn công; ở đây có hàng nghìn máy.","D":"Phishing lừa người dùng qua email/trang giả."}},{"id":"reviewed_atm_28","chapter":"1","question":"Điểm sinh viên bị sửa trái phép nhưng hệ thống vẫn truy cập bình thường. Thuộc tính CIA bị vi phạm trực tiếp là gì?","options":{"A":"Sẵn sàng","B":"Toàn vẹn","C":"Bí mật","D":"Xác thực"},"answer":"B","family":"source_28","style":"review","section":"1.4","source":"https://pttp-huitquiz.site/","explanation":"Điểm bị sửa trái phép là dữ liệu mất toàn vẹn; hệ thống vẫn chạy nên không phải mất sẵn sàng.","optionNotes":{"A":"Hệ thống vẫn truy cập bình thường, nên tính sẵn sàng còn nguyên.","C":"Vấn đề là dữ liệu bị sửa, không phải bị đọc trộm.","D":"Xác thực không phải một chữ trong CIA, và câu hỏi nói về dữ liệu bị sửa."}},{"id":"abbr_c1_001","chapter":"1","question":"CIA trong an ninh thông tin là viết tắt của:","options":{"A":"Confidentiality, Integrity, Availability","B":"Cryptography, Integrity, Authorization","C":"Confidentiality, Identity, Accountability","D":"Control, Identity, Authentication"},"answer":"A","family":"abbr_c1_001","style":"acronym","section":"1.2","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"CIA là ba mục tiêu cốt lõi: Confidentiality (bí mật), Integrity (toàn vẹn), Availability (sẵn sàng).","optionNotes":{"B":"C không phải Cryptography và A không phải Authorization.","C":"I là Integrity chứ không phải Identity, A là Availability chứ không phải Accountability.","D":"Cả ba chữ đều sai: đúng là Confidentiality, Integrity, Availability."}},{"id":"abbr_c1_002","chapter":"1","question":"DoS là viết tắt của:","options":{"A":"Disk Operating System","B":"Denial of Service","C":"Domain of Security","D":"Data over Socket"},"answer":"B","family":"ab_dos","style":"acronym","section":"1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"DoS là Denial of Service, tấn công từ chối dịch vụ.","optionNotes":{"A":"Disk Operating System là hệ điều hành MS-DOS, không phải tấn công.","C":"Không có thuật ngữ Domain of Security cho DoS.","D":"Data over Socket không phải nghĩa của DoS."}},{"id":"abbr_c1_003","chapter":"1","question":"Chữ D đầu tiên trong DDoS có nghĩa là:","options":{"A":"Duplicate – lặp lại một gói tin","B":"Dynamic – liên tục đổi địa chỉ đích","C":"Distributed – tấn công từ nhiều nguồn","D":"Direct – tấn công thẳng vào một cổng"},"answer":"C","family":"ab_dos","style":"acronym","section":"1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"DDoS là Distributed Denial of Service; Distributed nghĩa là tấn công phân tán từ nhiều nguồn.","optionNotes":{"A":"D không phải Duplicate; DDoS không phải lặp một gói tin.","B":"D không phải Dynamic; DDoS không định nghĩa bằng việc đổi địa chỉ đích.","D":"D không phải Direct; điểm chính là nhiều nguồn, không phải đánh thẳng một cổng."}},{"id":"abbr_c1_004","chapter":"1","question":"ARP trong kỹ thuật ARP spoofing là giao thức:","options":{"A":"Cấp phát địa chỉ IP động cho máy trạm","B":"Định tuyến gói tin giữa các mạng con","C":"Phân giải tên miền sang địa chỉ IP","D":"Phân giải địa chỉ IP sang địa chỉ MAC"},"answer":"D","family":"abbr_c1_004","style":"acronym","section":"1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"ARP (Address Resolution Protocol) tìm địa chỉ MAC ứng với một địa chỉ IP trong mạng LAN; ARP spoofing gửi trả lời ARP giả để chiếm vị trí máy khác.","optionNotes":{"A":"Cấp phát IP động là DHCP.","B":"Định tuyến giữa các mạng con là việc của router và giao thức định tuyến.","C":"Phân giải tên miền sang IP là DNS."}},{"id":"abbr_c1_005","chapter":"1","question":"Trong SYN flooding, gói SYN là:","options":{"A":"Gói UDP dùng để truy vấn tên miền","B":"Gói ICMP dùng để kiểm tra kết nối","C":"Gói mở đầu bắt tay ba bước của TCP","D":"Gói xác nhận kết thúc phiên TCP"},"answer":"C","family":"abbr_c1_005","style":"acronym","section":"1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"SYN là gói đầu tiên của bắt tay ba bước TCP (SYN, SYN-ACK, ACK); SYN flood gửi rất nhiều SYN để làm đầy hàng đợi kết nối.","optionNotes":{"A":"Truy vấn tên miền qua UDP là DNS, không phải SYN.","B":"Kiểm tra kết nối bằng ICMP là ping (Echo Request).","D":"Kết thúc phiên TCP dùng FIN, không phải SYN."}},{"id":"abbr_c1_006","chapter":"1","question":"ICMP là viết tắt của:","options":{"A":"Internet Control Message Protocol","B":"Internal Control Mapping Protocol","C":"Internet Cache Message Protocol","D":"Internet Connection Management Protocol"},"answer":"A","family":"abbr_c1_006","style":"acronym","section":"1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"ICMP là Internet Control Message Protocol, giao thức gửi thông báo điều khiển/lỗi, ví dụ ping.","optionNotes":{"B":"Không phải Internal Control Mapping Protocol.","C":"Chữ C là Control, không phải Cache.","D":"Chữ M là Message, không phải Management; cũng không có chữ Connection."}},{"id":"abbr_c1_007","chapter":"1","question":"MAC trong cụm \"địa chỉ MAC\" bị thay đổi khi ARP spoofing là:","options":{"A":"Machine Address Code","B":"Main Access Channel","C":"Message Authentication Code","D":"Media Access Control"},"answer":"D","family":"abbr_c1_007","style":"acronym","section":"1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"MAC trong địa chỉ MAC là Media Access Control, địa chỉ phần cứng của card mạng.","optionNotes":{"A":"Không phải Machine Address Code.","B":"Không phải Main Access Channel.","C":"Message Authentication Code cũng viết tắt MAC nhưng là mã xác thực thông điệp trong mật mã, không phải địa chỉ card mạng."}},{"id":"abbr_c1_008","chapter":"1","question":"MITM là viết tắt của kiểu tấn công:","options":{"A":"Malware-in-the-Memory","B":"Man-in-the-Middle","C":"Multi-Interface Traffic Monitor","D":"Man-in-the-Mail"},"answer":"B","family":"abbr_c1_008","style":"acronym","section":"1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"MITM là Man-in-the-Middle, kẻ tấn công đứng giữa hai bên để đọc hoặc sửa thông điệp.","optionNotes":{"A":"Chữ M thứ hai là Middle, không phải Memory.","C":"MITM không phải tên một công cụ giám sát lưu lượng.","D":"Middle chứ không phải Mail."}},{"id":"rev_c1_133","chapter":"1","question":"Theo bài tập Bài 1, muốn bắt gói tin email (SMTP) thì lọc TCP ở cổng nào?","options":{"A":"25","B":"21","C":"443","D":"80"},"answer":"A","family":"port_smtp","style":"review","section":"1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"SMTP gửi email dùng cổng TCP 25, nên lọc tcp.port == 25 để bắt gói email.","optionNotes":{"B":"Cổng 21 là FTP (truyền tệp).","C":"Cổng 443 là HTTPS.","D":"Cổng 80 là HTTP."}},{"id":"rev_c1_134","chapter":"1","question":"Theo bài tập Bài 1, duyệt web thông thường (HTTP) dùng cổng TCP nào?","options":{"A":"21","B":"25","C":"443","D":"80"},"answer":"D","family":"port_http","style":"review","section":"1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"HTTP mặc định dùng cổng TCP 80.","optionNotes":{"A":"Cổng 21 là FTP.","B":"Cổng 25 là SMTP.","C":"Cổng 443 là HTTPS (HTTP có mã hóa TLS)."}},{"id":"rev_c1_135","chapter":"1","question":"HTTPS dùng cổng TCP mặc định nào?","options":{"A":"80","B":"443","C":"25","D":"8080"},"answer":"B","family":"port_https","style":"review","section":"1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"HTTPS (HTTP qua TLS) mặc định dùng cổng TCP 443.","optionNotes":{"A":"Cổng 80 là HTTP không mã hóa.","C":"Cổng 25 là SMTP.","D":"8080 là cổng HTTP thay thế hay dùng cho proxy/web thử nghiệm, không phải cổng mặc định của HTTPS."}},{"id":"rev_c1_136","chapter":"1","question":"Theo slide Bài 1, công cụ Port scan dùng để làm gì?","options":{"A":"Mã hóa dữ liệu đi qua từng cổng mạng","B":"Đổi số hiệu cổng của dịch vụ web","C":"Tìm các cổng TCP/UDP đang mở trên máy","D":"Chặn mọi cổng không cần thiết trên tường lửa"},"answer":"C","family":"rev_c1_136","style":"review","section":"1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"Port scan gửi gói thử tới các cổng để biết cổng TCP/UDP nào đang mở, tức dịch vụ nào đang chạy.","optionNotes":{"A":"Port scan không mã hóa dữ liệu.","B":"Port scan chỉ dò, không đổi cấu hình dịch vụ.","D":"Chặn cổng là việc của tường lửa; port scan chỉ phát hiện."}},{"id":"rev_c1_137","chapter":"1","question":"Theo bài tập Bài 1, lệnh Windows nào liệt kê kết nối và cổng đang mở kèm PID tiến trình?","options":{"A":"ipconfig /all","B":"tracert","C":"netstat -ano","D":"ping -t"},"answer":"C","family":"rev_c1_137","style":"review","section":"1.6","source":"Đề cương mục 1.3-1.6; slide Bài 1","explanation":"netstat -ano liệt kê mọi kết nối và cổng đang nghe (-a), dạng số (-n), kèm PID tiến trình (-o).","optionNotes":{"A":"ipconfig /all hiện cấu hình card mạng (IP, MAC, DNS), không liệt kê cổng.","B":"tracert dò đường đi qua các router tới đích.","D":"ping -t gửi ping liên tục để kiểm tra kết nối."}},{"id":"gen_050","chapter":"2","question":"Xét tình huống: Tệp thực thi bị sửa để mang thêm mã lây nhiễm. Cách gọi đúng là gì?","options":{"A":"Virus","B":"Trojan","C":"Worm","D":"Rootkit"},"answer":"A","family":"g05c1","style":"scenario","section":"2.1-2.3","source":"Đề cương mục 2.1-2.3; slide Bài 2","explanation":"Virus gắn mã của nó vào một tệp chủ (ở đây là tệp thực thi) và lây khi tệp đó chạy.","optionNotes":{"B":"Trojan giả làm phần mềm hợp lệ và không sửa tệp khác để lây.","C":"Worm tự lây qua mạng, không cần gắn vào tệp chủ.","D":"Rootkit dùng để che giấu sự hiện diện của mã độc, không phải gắn mã lây vào tệp."}},{"id":"gen_051","chapter":"2","question":"Theo slide, virus máy tính lây nhiễm như thế nào?","options":{"A":"Tự lây qua mạng sang máy khác mà không cần gắn vào tệp chủ nào","B":"Chỉ ghi lại phím gõ để gửi cho hacker","C":"Không bao giờ thay đổi tệp bị nhiễm","D":"Gắn vào đối tượng chủ và lây khi chương trình chủ chạy"},"answer":"D","family":"g05c1","style":"distinction","section":"2.1-2.3","source":"Đề cương mục 2.1-2.3; slide Bài 2","explanation":"Theo slide, virus gắn vào một đối tượng chủ (tệp, cung boot, tài liệu) và lây khi chương trình chủ được chạy.","optionNotes":{"A":"Tự lây qua mạng mà không cần tệp chủ là đặc điểm của worm.","B":"Ghi lại phím gõ là keylogger.","C":"Virus phải sửa đối tượng chủ để gắn mã vào, nên tệp bị nhiễm có thay đổi."}},{"id":"gen_054","chapter":"2","question":"Điểm khác biệt chính của worm so với virus là gì?","options":{"A":"Worm tự nhân bản qua mạng, không cần tệp chủ","B":"Worm phải gắn vào tệp chủ và chỉ lây khi người dùng mở tệp đó","C":"Worm chỉ lây qua đĩa mềm và USB","D":"Worm không bao giờ tiêu tốn băng thông"},"answer":"A","family":"g05c2","style":"distinction","section":"2.1-2.3","source":"Đề cương mục 2.1-2.3; slide Bài 2","explanation":"Worm tự nhân bản và lây qua mạng mà không cần gắn vào tệp chủ; virus thì cần tệp chủ.","optionNotes":{"B":"Gắn vào tệp chủ và chờ người dùng mở là virus, ngược với worm.","C":"Worm lây chủ yếu qua mạng, không chỉ qua đĩa mềm/USB.","D":"Worm lây ồ ạt nên thường tiêu tốn nhiều băng thông."}},{"id":"gen_057","chapter":"2","question":"Theo slide, điểm nào đúng với Trojan?","options":{"A":"Tự nhân bản và lây sang mọi máy trong mạng LAN ngay khi được chạy","B":"Không tự nhân bản như virus, chỉ chạy ngầm trong máy bị nhiễm","C":"Luôn hiện cảnh báo để người dùng biết","D":"Chỉ lây nhiễm trên cung boot của đĩa"},"answer":"B","family":"g05c3","style":"distinction","section":"2.1-2.3","source":"Đề cương mục 2.1-2.3; slide Bài 2","explanation":"Theo slide, Trojan không tự nhân bản như virus; nó nằm và chạy ngầm trong máy bị nhiễm để làm việc cho kẻ tấn công.","optionNotes":{"A":"Tự nhân bản và lây khắp LAN là đặc điểm của worm, không phải Trojan.","C":"Trojan cố ẩn mình, không báo cho người dùng.","D":"Lây trên cung boot là boot virus."}},{"id":"gen_063","chapter":"2","question":"Theo slide, Trojan RAT biến máy nạn nhân thành gì?","options":{"A":"Một server để máy client của hacker điều khiển từ xa","B":"Một máy chủ DNS phân giải tên miền cho toàn bộ mạng nội bộ","C":"Một tường lửa chặn kết nối vào","D":"Một máy chỉ dùng để ghi lại phím gõ"},"answer":"A","family":"g06c1","style":"distinction","section":"2.2","source":"Đề cương mục 2.2; slide Bài 2","explanation":"RAT cài phần server trên máy nạn nhân; hacker dùng phần client để kết nối và điều khiển từ xa.","optionNotes":{"B":"RAT không biến máy thành máy chủ DNS.","C":"RAT mở đường vào cho hacker, ngược với tường lửa chặn kết nối.","D":"Chỉ ghi phím là keylogger; RAT cho điều khiển toàn bộ máy."}},{"id":"gen_066","chapter":"2","question":"Theo slide, keylogger gồm những loại nào?","options":{"A":"Keylogger phần cứng và keylogger phần mềm","B":"Keylogger boot và keylogger macro","C":"Keylogger mạng và keylogger không dây","D":"Chỉ có keylogger phần mềm"},"answer":"A","family":"g06c2","style":"distinction","section":"2.2","source":"Đề cương mục 2.2; slide Bài 2","explanation":"Slide chia keylogger làm hai loại: phần cứng (thiết bị gắn giữa bàn phím và máy) và phần mềm (chương trình chạy ngầm).","optionNotes":{"B":"Boot và macro là các loại virus, không phải loại keylogger.","C":"Slide không chia keylogger theo mạng và không dây.","D":"Còn có keylogger phần cứng."}},{"id":"gen_068","chapter":"2","question":"Tệp cấu hình trình duyệt chứa mật khẩu bị gửi ra ngoài. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"RAT","B":"Backdoor","C":"Keylogger","D":"Trojan đánh cắp mật khẩu"},"answer":"D","family":"g06c3","style":"scenario","section":"2.2","source":"Đề cương mục 2.2; slide Bài 2","explanation":"Lấy tệp cấu hình chứa mật khẩu đã lưu rồi gửi ra ngoài là việc của Trojan đánh cắp mật khẩu.","optionNotes":{"A":"RAT cho điều khiển từ xa toàn bộ máy; tình huống chỉ nói lấy mật khẩu đã lưu.","B":"Backdoor là đường vào bí mật, không phải chương trình gom mật khẩu gửi đi.","C":"Keylogger ghi phím gõ; ở đây mật khẩu lấy từ tệp cấu hình, không từ bàn phím."}},{"id":"gen_069","chapter":"2","question":"Mục tiêu chính của Trojan ăn trộm password là gì?","options":{"A":"Mã hóa ổ cứng của nạn nhân rồi đòi tiền chuộc để mở khóa","B":"Làm quá tải băng thông mạng","C":"Thu thập tài khoản, mật khẩu rồi gửi cho kẻ tấn công","D":"Phá hủy dữ liệu trên ổ cứng"},"answer":"C","family":"g06c3","style":"distinction","section":"2.2","source":"Đề cương mục 2.2; slide Bài 2","explanation":"Trojan ăn trộm password tìm tài khoản, mật khẩu trên máy (trình duyệt, IRC, ICQ...) rồi gửi cho kẻ tấn công.","optionNotes":{"A":"Mã hóa ổ cứng rồi đòi tiền chuộc là ransomware.","B":"Làm quá tải băng thông là DoS/DDoS hoặc worm.","D":"Mục tiêu là lấy thông tin, không phải phá hủy dữ liệu."}},{"id":"gen_072","chapter":"2","question":"Backdoor là gì?","options":{"A":"Phần mềm diệt virus chạy nền để bảo vệ máy khỏi mã độc mới","B":"Bản vá lỗi do nhà sản xuất phát hành","C":"Cổng mạng dự phòng của router","D":"Đường vào bí mật giúp kẻ tấn công quay lại hệ thống"},"answer":"D","family":"g06c4","style":"distinction","section":"2.2","source":"Đề cương mục 2.2; slide Bài 2","explanation":"Backdoor (cửa hậu) là lối vào bí mật, bỏ qua xác thực thông thường, để kẻ tấn công quay lại hệ thống.","optionNotes":{"A":"Phần mềm diệt virus là công cụ bảo vệ, ngược với backdoor.","B":"Bản vá lỗi dùng để sửa lỗ hổng, không phải lối vào bí mật.","C":"Backdoor không phải cổng vật lý hay cổng dự phòng của router."}},{"id":"gen_075","chapter":"2","question":"Spyware chủ yếu làm gì?","options":{"A":"Tự nhân bản qua mạng để lây lan sang càng nhiều máy càng tốt","B":"Lén thu thập thông tin người dùng mà không xin phép","C":"Phá hủy cung boot của ổ cứng","D":"Chặn kết nối Internet của máy"},"answer":"B","family":"g07c1","style":"distinction","section":"2.1-2.3","source":"Đề cương mục 2.1-2.3; slide Bài 2","explanation":"Spyware lén thu thập thông tin người dùng (thói quen duyệt web, tài khoản...) mà không xin phép.","optionNotes":{"A":"Tự nhân bản qua mạng là worm.","C":"Phá cung boot là boot virus.","D":"Spyware muốn máy vẫn kết nối để gửi dữ liệu đi, không chặn Internet."}},{"id":"gen_087","chapter":"2","question":"Theo slide, con đường nào thường được Trojan dùng để xâm nhập hệ thống?","options":{"A":"Bản cập nhật firmware chính hãng","B":"File đính kèm email","C":"Cáp nguồn điện của máy tính","D":"Đèn báo trạng thái của router"},"answer":"B","family":"g08c1","style":"distinction","section":"2.3-2.5","source":"Đề cương mục 2.3-2.5; slide Bài 2","explanation":"Slide nêu Trojan thường xâm nhập qua file đính kèm email, phần mềm tải về, chat... người dùng tự mở.","optionNotes":{"A":"Bản cập nhật firmware chính hãng là nguồn tin cậy, không phải đường lây thường gặp.","C":"Cáp nguồn chỉ cấp điện, không truyền dữ liệu.","D":"Đèn báo trạng thái chỉ hiển thị, không truyền mã."}},{"id":"gen_090","chapter":"2","question":"Theo slide, macro virus lây nhiễm trên đối tượng nào?","options":{"A":"Cung boot của đĩa cứng","B":"Tập tin Word, Excel, Access","C":"Tập tin thực thi .exe","D":"Registry của Windows"},"answer":"B","family":"g08c2","style":"distinction","section":"2.3-2.5","source":"Đề cương mục 2.3-2.5; slide Bài 2","explanation":"Macro virus viết bằng ngôn ngữ macro nên lây trên tài liệu Word, Excel, Access.","optionNotes":{"A":"Lây trên cung boot là boot virus.","C":"Lây trên tệp .exe là file virus.","D":"Registry không phải nơi macro virus lây nhiễm."}},{"id":"gen_092","chapter":"2","question":"Nếu máy làm việc phát hiện file lạ sau khi cắm usb ngoài, hiện tượng nào đang xảy ra?","options":{"A":"Macro độc hại","B":"Khai thác dịch vụ mạng","C":"USB nhiễm mã độc","D":"Tệp đính kèm độc hại"},"answer":"C","family":"g08c3","style":"scenario","section":"2.3-2.5","source":"Đề cương mục 2.3-2.5; slide Bài 2","explanation":"File lạ xuất hiện ngay sau khi cắm USB ngoài cho thấy mã độc đến từ USB.","optionNotes":{"A":"Macro độc hại đi kèm tài liệu Office được mở, không gắn với việc cắm USB.","B":"Khai thác dịch vụ mạng lây qua cổng mạng, không qua USB.","D":"Tệp đính kèm độc hại đến qua email."}},{"id":"gen_093","chapter":"2","question":"Biện pháp nào giảm nguy cơ USB nhiễm mã độc mang mã vào mạng nội bộ?","options":{"A":"Nâng cấp mọi cổng USB lên chuẩn 3.0 để chép tệp nhanh hơn","B":"Cho nhiều người dùng chung một USB","C":"Kiểm soát thiết bị ngoại vi và quét USB trước khi dùng","D":"Tắt phần mềm diệt virus khi cắm USB"},"answer":"C","family":"g08c3","style":"distinction","section":"2.3-2.5","source":"Đề cương mục 2.3-2.5; slide Bài 2","explanation":"Kiểm soát thiết bị ngoại vi và quét USB trước khi dùng chặn mã độc ngay từ cửa vào.","optionNotes":{"A":"USB 3.0 chỉ chép nhanh hơn, mã độc cũng chép nhanh hơn.","B":"Dùng chung USB làm mã độc lây giữa nhiều máy hơn.","D":"Tắt diệt virus khi cắm USB là bỏ lớp bảo vệ đúng lúc rủi ro nhất."}},{"id":"gen_095","chapter":"2","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Worm lan qua các máy cùng mở một cổng có lỗi?","options":{"A":"Macro độc hại","B":"Khai thác dịch vụ mạng","C":"Tệp đính kèm độc hại","D":"USB nhiễm mã độc"},"answer":"B","family":"g08c4","style":"scenario","section":"2.3-2.5","source":"Đề cương mục 2.3-2.5; slide Bài 2","explanation":"Worm dò các máy mở cùng một cổng có lỗi rồi khai thác lỗi đó để lây, tức khai thác dịch vụ mạng.","optionNotes":{"A":"Macro độc hại cần người dùng mở tài liệu Office.","C":"Tệp đính kèm cần người dùng mở email; ở đây worm tự lây qua cổng.","D":"USB lây qua thiết bị cắm vào, không qua cổng mạng."}},{"id":"gen_096","chapter":"2","question":"Theo slide, Network Virus phát tán bằng cách nào?","options":{"A":"Lây trên cung boot của đĩa và kích hoạt mỗi khi máy khởi động","B":"Lây trên tập tin Word, Excel","C":"Tự phát tán qua email bằng lệnh và giao thức mạng","D":"Ghi đè mã Trojan vào mã nguồn tập tin chủ"},"answer":"C","family":"g08c4","style":"distinction","section":"2.3-2.5","source":"Đề cương mục 2.3-2.5; slide Bài 2","explanation":"Theo slide, Network Virus tự phát tán theo email bằng lệnh và các giao thức của mạng máy tính.","optionNotes":{"A":"Lây trên cung boot là boot virus.","B":"Lây trên tập tin Word, Excel là macro virus.","D":"Ghi đè mã vào tập tin chủ là cách của file virus, không phải network virus."}},{"id":"gen_098","chapter":"2","question":"Xét tình huống: Máy quét báo trùng mẫu mã độc đã lưu trong cơ sở dữ liệu. Cách gọi đúng là gì?","options":{"A":"Phát hiện hành vi","B":"Phân tích sandbox","C":"Phát hiện chữ ký","D":"Phát hiện heuristic"},"answer":"C","family":"g09c1","style":"scenario","section":"2.4-2.5","source":"Đề cương mục 2.4-2.5; slide Bài 2","explanation":"So khớp với mẫu mã độc đã lưu trong cơ sở dữ liệu là phát hiện theo chữ ký (signature).","optionNotes":{"A":"Phát hiện hành vi theo dõi việc chương trình làm khi chạy, không so mẫu đã lưu.","B":"Sandbox chạy thử tệp trong môi trường cô lập.","D":"Heuristic tìm đoạn mã đáng ngờ, kể cả mã độc chưa có mẫu."}},{"id":"gen_099","chapter":"2","question":"Theo slide, Basic scanning phát hiện virus bằng cách nào?","options":{"A":"Tìm chữ ký của virus đã biết trong tập tin","B":"Quét đoạn mã đáng ngờ bằng heuristic","C":"So giá trị ICV với giá trị nguyên thủy","D":"Chạy tệp trong máy ảo để quan sát"},"answer":"A","family":"g09c1","style":"distinction","section":"2.4-2.5","source":"Đề cương mục 2.4-2.5; slide Bài 2","explanation":"Basic scanning tìm chữ ký (chuỗi byte đặc trưng) của virus đã biết trong tập tin.","optionNotes":{"B":"Quét đoạn mã đáng ngờ là heuristic scanning.","C":"So giá trị ICV là ICV scanning.","D":"Chạy trong máy ảo là phân tích sandbox."}},{"id":"gen_101","chapter":"2","question":"Nếu bộ quét gắn cờ mã có cấu trúc tự giải mã bất thường, hiện tượng nào đang xảy ra?","options":{"A":"Phát hiện hành vi","B":"Phân tích sandbox","C":"Phát hiện chữ ký","D":"Phát hiện heuristic"},"answer":"D","family":"g09c2","style":"scenario","section":"2.4-2.5","source":"Đề cương mục 2.4-2.5; slide Bài 2","explanation":"Cờ cảnh báo vì cấu trúc mã bất thường (như tự giải mã) chứ không vì trùng mẫu đã biết là phát hiện heuristic.","optionNotes":{"A":"Phát hiện hành vi dựa vào việc chương trình làm khi chạy; ở đây bộ quét xét cấu trúc mã.","B":"Sandbox phải chạy mẫu trong môi trường cô lập.","C":"Chữ ký cần trùng mẫu đã biết; cấu trúc tự giải mã không phải một mẫu cụ thể."}},{"id":"gen_102","chapter":"2","question":"Theo slide, heuristic scanning phát hiện virus dựa vào gì?","options":{"A":"Chữ ký virus đã biết trong cơ sở dữ liệu","B":"Đoạn mã đáng ngờ và hành vi của chương trình","C":"Giá trị ICV nối vào cuối tệp thực thi","D":"Tên tệp và phần mở rộng .exe"},"answer":"B","family":"g09c2","style":"distinction","section":"2.4-2.5","source":"Đề cương mục 2.4-2.5; slide Bài 2","explanation":"Theo slide, heuristic scanning quét các đoạn mã đáng ngờ và hành vi của chương trình, nên bắt được cả virus chưa có chữ ký.","optionNotes":{"A":"Dựa vào chữ ký đã biết là basic scanning.","C":"Giá trị ICV dùng cho ICV scanning.","D":"Tên tệp và phần mở rộng rất dễ đổi, không phải cơ sở của heuristic."}},{"id":"gen_104","chapter":"2","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Ứng dụng vừa sửa hàng trăm tệp vừa liên hệ máy lạ?","options":{"A":"Phát hiện hành vi","B":"Phát hiện chữ ký","C":"Phát hiện heuristic","D":"Phân tích sandbox"},"answer":"A","family":"g09c3","style":"scenario","section":"2.4-2.5","source":"Đề cương mục 2.4-2.5; slide Bài 2","explanation":"Sửa hàng loạt tệp và liên lạc với máy lạ là những việc chương trình đang làm khi chạy, nên là phát hiện hành vi.","optionNotes":{"B":"Chữ ký so mẫu byte đã biết, không xét việc chương trình làm.","C":"Heuristic xét đoạn mã đáng ngờ trong tệp; ở đây là hoạt động thực tế của ứng dụng.","D":"Sandbox là chạy thử có chủ đích trong môi trường cô lập; ở đây ứng dụng chạy thật trên máy."}},{"id":"gen_113","chapter":"2","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Chuyên viên ghi lại tiến trình, tệp và kết nối mẫu tạo ra?","options":{"A":"Phân tích động","B":"Giá trị băm mẫu","C":"Chỉ dấu xâm nhập","D":"Phân tích tĩnh"},"answer":"A","family":"g10c2","style":"scenario","section":"2.4-2.5","source":"Đề cương mục 2.4-2.5; slide Bài 2","explanation":"Ghi lại tiến trình, tệp và kết nối mà mẫu tạo ra khi chạy là phân tích động.","optionNotes":{"B":"Giá trị băm chỉ nhận dạng tệp, không cho biết mẫu làm gì.","C":"Chỉ dấu xâm nhập (IoC) là kết quả dùng để phát hiện, không phải phương pháp quan sát mẫu.","D":"Phân tích tĩnh xem mẫu mà không chạy nó."}},{"id":"gen_116","chapter":"2","question":"Tên miền điều khiển xuất hiện trong log của nhiều máy. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"Giá trị băm mẫu","B":"Chỉ dấu xâm nhập","C":"Phân tích tĩnh","D":"Phân tích động"},"answer":"B","family":"g10c3","style":"scenario","section":"2.4-2.5","source":"Đề cương mục 2.4-2.5; slide Bài 2","explanation":"Một tên miền điều khiển (C2) xuất hiện trên nhiều máy là dấu vết dùng để phát hiện xâm nhập, tức chỉ dấu xâm nhập (IoC).","optionNotes":{"A":"Giá trị băm mẫu nhận dạng tệp, không phải tên miền trong log.","C":"Phân tích tĩnh là cách xem mẫu, không phải dấu vết trong log.","D":"Phân tích động là chạy mẫu để quan sát."}},{"id":"gen_128","chapter":"2","question":"Xét tình huống: Sau mã độc tống tiền, quản trị viên dựng lại tệp từ bản offline. Cách gọi đúng là gì?","options":{"A":"Cách ly máy nhiễm","B":"Quarantine tệp","C":"Phân tích nguyên nhân gốc","D":"Khôi phục từ sao lưu"},"answer":"D","family":"g11c3","style":"scenario","section":"2.1-2.5","source":"Đề cương mục 2.1-2.5; slide Bài 2","explanation":"Dựng lại tệp từ bản sao lưu offline sau khi bị mã hóa là khôi phục từ sao lưu.","optionNotes":{"A":"Cách ly máy nhiễm là ngắt khỏi mạng, không dựng lại dữ liệu.","B":"Quarantine là cô lập tệp nghi nhiễm.","C":"Phân tích nguyên nhân gốc là tìm đường xâm nhập."}},{"id":"gen_131","chapter":"2","question":"Nếu sau khi dọn mã độc, nhóm kiểm tra lỗ hổng đã bị khai thác, hiện tượng nào đang xảy ra?","options":{"A":"Cách ly máy nhiễm","B":"Quarantine tệp","C":"Phân tích nguyên nhân gốc","D":"Khôi phục từ sao lưu"},"answer":"C","family":"g11c4","style":"scenario","section":"2.1-2.5","source":"Đề cương mục 2.1-2.5; slide Bài 2","explanation":"Tìm lỗ hổng đã bị khai thác sau khi dọn mã độc là phân tích nguyên nhân gốc, để không bị nhiễm lại.","optionNotes":{"A":"Cách ly máy là bước khoanh vùng, làm trước khi dọn.","B":"Quarantine chỉ cô lập tệp nghi nhiễm.","D":"Khôi phục sao lưu là dựng lại dữ liệu, không tìm lỗ hổng."}},{"id":"case_11","chapter":"2","question":"Một mã độc tự dò máy khác qua dịch vụ có lỗ hổng và lây mà không cần người dùng mở tệp chủ. Loại phù hợp nhất?","options":{"A":"Worm","B":"Virus gắn tệp","C":"Logic bomb theo thời gian","D":"Trojan giả phần mềm"},"answer":"A","family":"g05c2","style":"application","section":"2.1-2.3","source":"Đề cương mục 2.1-2.3; slide Bài 2","explanation":"Tự dò máy khác và lây qua dịch vụ có lỗ hổng, không cần tệp chủ hay người dùng mở tệp, là worm.","optionNotes":{"B":"Virus gắn tệp cần tệp chủ và người dùng chạy tệp đó.","C":"Logic bomb chỉ kích hoạt theo điều kiện, không tự lây.","D":"Trojan cần người dùng tự cài và không tự nhân bản."}},{"id":"case_12","chapter":"2","question":"Người dùng cài một ứng dụng giả làm công cụ học tập; ứng dụng mở đường điều khiển từ xa nhưng không tự nhân bản. Phân loại phù hợp?","options":{"A":"Trojan","B":"Virus macro","C":"Worm","D":"Mã độc chỉ kích hoạt theo ngày"},"answer":"A","family":"g05c3","style":"application","section":"2.1-2.3","source":"Đề cương mục 2.1-2.3; slide Bài 2","explanation":"Giả làm phần mềm có ích để được cài, mở đường điều khiển từ xa, không tự nhân bản: đúng đặc điểm Trojan.","optionNotes":{"B":"Virus macro lây trên tài liệu Office và tự nhân bản.","C":"Worm tự nhân bản qua mạng.","D":"Mã độc kích hoạt theo ngày là logic/time bomb, không nói đến việc giả phần mềm."}},{"id":"case_13","chapter":"2","question":"Sau khi đổi mật khẩu quản trị, kẻ tấn công vẫn vào hệ thống qua một lối ẩn cài trước. Thành phần cần tìm là gì?","options":{"A":"Backdoor","B":"Bản vá lỗi","C":"Bản sao lưu ngoại tuyến","D":"Chữ ký số"},"answer":"A","family":"g06c4","style":"application","section":"2.2","source":"Đề cương mục 2.2; slide Bài 2","explanation":"Vẫn vào được dù đã đổi mật khẩu nghĩa là có lối vào bỏ qua xác thực, tức backdoor.","optionNotes":{"B":"Bản vá lỗi dùng để bịt lỗ hổng, không phải lối vào của kẻ tấn công.","C":"Bản sao lưu dùng để khôi phục dữ liệu.","D":"Chữ ký số xác minh nguồn gốc, không phải lối vào hệ thống."}},{"id":"case_14","chapter":"2","question":"Một tài liệu Word chỉ chạy mã lạ sau khi người dùng chọn bật nội dung tự động. Đường lây đáng ngờ nhất là gì?","options":{"A":"WEP IV trùng lặp","B":"Mã hóa AES-CCMP","C":"ACL sai thứ tự","D":"Macro độc hại"},"answer":"D","family":"g08c2","style":"application","section":"2.3-2.5","source":"Đề cương mục 2.3-2.5; slide Bài 2","explanation":"Tài liệu Word chỉ chạy mã sau khi bật nội dung tự động (macro) là dấu hiệu macro độc hại.","optionNotes":{"A":"WEP IV là lỗi của bảo mật Wi-Fi cũ, không liên quan tài liệu Word.","B":"AES-CCMP là mã hóa của WPA2, không phải đường lây.","C":"ACL sai thứ tự là lỗi cấu hình tường lửa."}},{"id":"case_15","chapter":"2","question":"Bộ quét chỉ so mẫu byte đã biết và bỏ sót một biến thể mới. Hạn chế này thuộc phương pháp nào?","options":{"A":"Phát hiện theo chữ ký","B":"Phân tích hành vi khi chạy","C":"Giám sát bất thường theo baseline","D":"Phân tích thủ công trong sandbox"},"answer":"A","family":"case_15","style":"application","section":"2.4-2.5","source":"Đề cương mục 2.4-2.5; slide Bài 2","explanation":"Chỉ so mẫu byte đã biết nên bỏ sót biến thể mới: đó là hạn chế của phát hiện theo chữ ký.","optionNotes":{"B":"Phân tích hành vi xét việc chương trình làm, nên có thể bắt biến thể mới.","C":"Giám sát bất thường so với baseline cũng phát hiện được cái mới.","D":"Sandbox quan sát mẫu khi chạy, không so mẫu byte."}},{"id":"case_16","chapter":"2","question":"Tệp nghi vấn được chạy trong máy ảo cô lập để ghi lại tiến trình và kết nối nó tạo ra. Đây là cách nào?","options":{"A":"Phân tích động trong sandbox","B":"Phân tích tĩnh không thực thi","C":"Chỉ kiểm tra phần mở rộng tệp","D":"So khớp giá trị băm duy nhất"},"answer":"A","family":"case_16","style":"application","section":"2.4-2.5","source":"Đề cương mục 2.4-2.5; slide Bài 2","explanation":"Chạy tệp trong máy ảo cô lập để ghi lại những gì nó làm là phân tích động trong sandbox.","optionNotes":{"B":"Phân tích tĩnh không chạy tệp.","C":"Phần mở rộng tệp dễ giả mạo và không cho biết tệp làm gì.","D":"Giá trị băm chỉ nhận dạng tệp."}},{"id":"case_17","chapter":"2","question":"Chuyên viên đọc header, chuỗi ký tự và danh sách hàm nhập của một mẫu mà không chạy nó. Đây là phương pháp nào?","options":{"A":"Cách ly máy trạm","B":"Phân tích tĩnh","C":"Khôi phục từ bản sao lưu","D":"Phân tích động"},"answer":"B","family":"g10c1","style":"application","section":"2.4-2.5","source":"Đề cương mục 2.4-2.5; slide Bài 2","explanation":"Đọc header, chuỗi và hàm nhập mà không chạy mẫu là phân tích tĩnh.","optionNotes":{"A":"Cách ly máy trạm là khoanh vùng sự cố, không phải phân tích mẫu.","C":"Khôi phục sao lưu là dựng lại dữ liệu.","D":"Phân tích động phải chạy mẫu."}},{"id":"case_18","chapter":"2","question":"Một máy bắt đầu tự gửi lưu lượng đến nhiều máy nội bộ sau khi nhiễm worm. Hành động đầu tiên nào giảm nguy cơ lây ngang?","options":{"A":"Tạm ngừng cập nhật chữ ký phát hiện","B":"Xóa ngay toàn bộ nhật ký","C":"Cách ly máy nghi nhiễm khỏi mạng","D":"Chỉ đổi hình nền máy tính"},"answer":"C","family":"case_18","style":"application","section":"2.1-2.5","source":"Đề cương mục 2.1-2.5; slide Bài 2","explanation":"Worm lây qua mạng nên cách ly máy nghi nhiễm khỏi mạng là cách nhanh nhất để chặn lây ngang.","optionNotes":{"A":"Ngừng cập nhật chữ ký làm khả năng phát hiện kém đi.","B":"Xóa nhật ký làm mất bằng chứng để điều tra.","D":"Đổi hình nền không ảnh hưởng gì tới worm."}},{"id":"case_19","chapter":"2","question":"Hai tệp có tên giống nhau nhưng SHA-256 khác nhau. Kết luận nào hợp lý nhất?","options":{"A":"SHA-256 là thuật toán mã hóa giải ngược được","B":"Chắc chắn hai tệp có nội dung giống hệt","C":"Không thể coi chúng là cùng một mẫu tệp chỉ dựa vào tên","D":"Một trong hai tệp chắc chắn là ransomware"},"answer":"C","family":"case_19","style":"application","section":"2.4-2.5","source":"Đề cương mục 2.4-2.5; slide Bài 2","explanation":"SHA-256 khác nhau nghĩa là nội dung khác nhau; tên tệp giống nhau không chứng minh chúng là cùng một mẫu.","optionNotes":{"A":"SHA-256 là hàm băm một chiều, không giải ngược được.","B":"Băm khác nhau thì nội dung chắc chắn khác nhau.","D":"Băm khác chỉ cho biết nội dung khác, không cho biết tệp nào là ransomware."}},{"id":"case_20","chapter":"2","question":"Đội xử lý đã xóa mã độc nhưng không tìm đường xâm nhập ban đầu; vài ngày sau máy bị nhiễm lại. Việc còn thiếu là gì?","options":{"A":"Phân tích nguyên nhân gốc và khắc phục đường vào","B":"Chỉ cài thêm trình phát media","C":"Đổi tên tệp nhật ký","D":"Tăng độ sáng màn hình"},"answer":"A","family":"case_20","style":"application","section":"2.1-2.5","source":"Đề cương mục 2.1-2.5; slide Bài 2","explanation":"Không tìm và đóng đường xâm nhập thì mã độc quay lại; việc còn thiếu là phân tích nguyên nhân gốc và khắc phục đường vào.","optionNotes":{"B":"Trình phát media không liên quan việc chặn tái nhiễm.","C":"Đổi tên nhật ký không khắc phục lỗ hổng.","D":"Độ sáng màn hình không liên quan bảo mật."}},{"id":"reviewed_atm_91","chapter":"2","question":"Mã độc cho phép kẻ ngoài điều khiển máy nạn nhân từ xa sau khi cài đặt là gì?","options":{"A":"Keylogger","B":"Logic bomb","C":"Rootkit","D":"RAT"},"answer":"D","family":"source_91","style":"review","section":"2.2","source":"https://pttp-huitquiz.site/","explanation":"RAT (Remote Access Trojan) cho kẻ ngoài điều khiển máy nạn nhân từ xa.","optionNotes":{"A":"Keylogger chỉ ghi phím gõ, không điều khiển máy.","B":"Logic bomb kích hoạt theo điều kiện để gây hại, không cho điều khiển từ xa.","C":"Rootkit dùng để che giấu mã độc, không phải công cụ điều khiển từ xa."}},{"id":"reviewed_atm_99","chapter":"2","question":"Chương trình âm thầm thu thập thói quen duyệt web rồi gửi đi là gì?","options":{"A":"Boot virus","B":"Ransomware","C":"Worm","D":"Spyware"},"answer":"D","family":"source_99","style":"review","section":"2.1","source":"https://pttp-huitquiz.site/","explanation":"Âm thầm thu thập thói quen duyệt web rồi gửi đi là spyware (phần mềm gián điệp).","optionNotes":{"A":"Boot virus lây trên cung khởi động.","B":"Ransomware mã hóa dữ liệu đòi tiền chuộc.","C":"Worm tự lây qua mạng."}},{"id":"reviewed_atm_101","chapter":"2","question":"Từ tài khoản thường, mã độc giành được quyền quản trị. Hành vi này gọi là gì?","options":{"A":"Phát lại gói","B":"Leo thang đặc quyền","C":"Đánh cắp phiên","D":"Lọc gói mạng"},"answer":"B","family":"source_101","style":"review","section":"2.2","source":"https://pttp-huitquiz.site/","explanation":"Từ quyền thường giành được quyền quản trị là leo thang đặc quyền.","optionNotes":{"A":"Phát lại gói là gửi lại gói tin cũ.","C":"Đánh cắp phiên là chiếm phiên đăng nhập của người khác, không phải tăng quyền.","D":"Lọc gói là chức năng của tường lửa."}},{"id":"reviewed_atm_107","chapter":"2","question":"Mã độc làm dịch vụ dừng hoạt động và lấy cắp tệp. Nhận định nào đúng nhất?","options":{"A":"Không ảnh hưởng dữ liệu","B":"Có thể hại cả sẵn sàng lẫn bí mật","C":"Chỉ ảnh hưởng tốc độ mạng","D":"Chỉ ảnh hưởng tên tệp"},"answer":"B","family":"source_107","style":"review","section":"2.1","source":"https://pttp-huitquiz.site/","explanation":"Dịch vụ dừng là mất tính sẵn sàng, tệp bị lấy là mất tính bí mật; một mã độc có thể gây cả hai.","optionNotes":{"A":"Tệp bị lấy cắp nghĩa là dữ liệu đã bị ảnh hưởng.","C":"Dịch vụ dừng và mất dữ liệu nghiêm trọng hơn nhiều so với chậm mạng.","D":"Mất tệp và dừng dịch vụ không chỉ là chuyện tên tệp."}},{"id":"reviewed_atm_119","chapter":"2","question":"Công cụ nào chủ yếu quét, cách ly và loại bỏ mẫu mã độc trên máy trạm?","options":{"A":"Proxy web","B":"Antivirus","C":"DNS resolver","D":"Load balancer"},"answer":"B","family":"source_119","style":"review","section":"2.5","source":"https://pttp-huitquiz.site/","explanation":"Antivirus quét, cách ly và loại bỏ mã độc trên máy trạm.","optionNotes":{"A":"Proxy web trung chuyển truy cập web, không dọn mã độc trên máy.","C":"DNS resolver phân giải tên miền.","D":"Load balancer chia tải giữa các máy chủ."}},{"id":"reviewed_atm_128","chapter":"2","question":"Người dùng mở tệp lạ từ email rồi bị nhiễm mã độc. Đường lây trực tiếp là gì?","options":{"A":"Cập nhật hệ thống","B":"Sao lưu ngoại tuyến","C":"Tệp đính kèm độc hại","D":"Phân tách mạng"},"answer":"C","family":"source_128","style":"review","section":"2.3","source":"https://pttp-huitquiz.site/","explanation":"Nhiễm ngay sau khi mở tệp lạ từ email: đường lây là tệp đính kèm độc hại.","optionNotes":{"A":"Cập nhật hệ thống là biện pháp phòng thủ.","B":"Sao lưu ngoại tuyến là biện pháp khôi phục.","D":"Phân tách mạng là biện pháp hạn chế lây lan."}},{"id":"reviewed_atm_147","chapter":"2","question":"Mã độc ghi lại chuỗi phím người dùng bấm để lấy mật khẩu là gì?","options":{"A":"Keylogger","B":"Worm","C":"Ransomware","D":"Adware"},"answer":"A","family":"source_147","style":"review","section":"2.2","source":"https://pttp-huitquiz.site/","explanation":"Ghi lại phím người dùng bấm để lấy mật khẩu là keylogger.","optionNotes":{"B":"Worm tự lây qua mạng.","C":"Ransomware mã hóa dữ liệu đòi tiền chuộc.","D":"Adware hiện quảng cáo."}},{"id":"abbr_c2_009","chapter":"2","question":"RAT trong nhóm Trojan là viết tắt của:","options":{"A":"Remote Access Trojan","B":"Root Access Toolkit","C":"Random Attack Tool","D":"Remote Antivirus Tool"},"answer":"A","family":"abbr_c2_009","style":"acronym","section":"2.2","source":"Đề cương mục 2.1-2.5; slide Bài 2 (a, b)","explanation":"RAT là Remote Access Trojan, Trojan truy cập (điều khiển) từ xa.","optionNotes":{"B":"Không phải Root Access Toolkit.","C":"Không phải Random Attack Tool.","D":"RAT là mã độc, không phải công cụ diệt virus."}},{"id":"rev_c2_010","chapter":"2","question":"Theo slide, Trojan RAT biến máy bị nhiễm thành:","options":{"A":"Client tự gửi thư rác theo lịch hẹn","B":"Server để máy client của hacker điều khiển","C":"Proxy chỉ chuyển tiếp lưu lượng web cho người khác","D":"Bản sao chỉ phá hủy dữ liệu cục bộ"},"answer":"B","family":"rev_c2_010","style":"review","section":"2.2","source":"Đề cương mục 2.1-2.5; slide Bài 2 (a, b)","explanation":"Theo slide, RAT biến máy bị nhiễm thành server; máy hacker là client kết nối vào để điều khiển.","optionNotes":{"A":"Máy nhiễm RAT là server bị điều khiển, không phải client tự gửi thư rác.","C":"RAT cho điều khiển toàn bộ máy, không chỉ chuyển tiếp web.","D":"RAT không chỉ phá dữ liệu; mục đích là điều khiển từ xa."}},{"id":"abbr_c2_011","chapter":"2","question":"ICV trong kỹ thuật ICV scanning là:","options":{"A":"Infection Control Vector – vector lây nhiễm","B":"Internal Code Verifier – bộ kiểm mã nội bộ","C":"Instant Capture of Virus – bắt virus tức thì","D":"Integrity Check Value – giá trị kiểm tra toàn vẹn"},"answer":"D","family":"ab_icv","style":"acronym","section":"2.5","source":"Đề cương mục 2.1-2.5; slide Bài 2 (a, b)","explanation":"ICV là Integrity Check Value, giá trị kiểm tra toàn vẹn nối vào cuối tệp sạch; tệp bị nhiễm sẽ làm ICV thay đổi.","optionNotes":{"A":"Không phải Infection Control Vector.","B":"Không phải Internal Code Verifier.","C":"Không phải Instant Capture of Virus."}},{"id":"abbr_c2_012","chapter":"2","question":"HMAC dùng trong ICV scanning là viết tắt của:","options":{"A":"Hybrid Memory Access Control","B":"Hash-based Malware Alert Center","C":"Hash-based Message Authentication Code","D":"Host-based Malware Analysis and Control"},"answer":"C","family":"ab_icv","style":"acronym","section":"2.5","source":"Đề cương mục 2.1-2.5; slide Bài 2 (a, b)","explanation":"HMAC là Hash-based Message Authentication Code, mã xác thực thông điệp dùng hàm băm kèm khóa bí mật.","optionNotes":{"A":"Không phải Hybrid Memory Access Control.","B":"HMAC không phải trung tâm cảnh báo mã độc.","D":"HMAC không phải công cụ phân tích mã độc trên máy."}},{"id":"abbr_c2_013","chapter":"2","question":"FTP Trojan mở dịch vụ có tên đầy đủ là:","options":{"A":"Fast Transmission Port","B":"Forward Transfer Proxy","C":"File Tracking Program","D":"File Transfer Protocol"},"answer":"D","family":"abbr_c2_013","style":"acronym","section":"2.2","source":"Đề cương mục 2.1-2.5; slide Bài 2 (a, b)","explanation":"FTP là File Transfer Protocol, giao thức truyền tệp; FTP Trojan mở dịch vụ này để người khác tải dữ liệu từ máy nạn nhân.","optionNotes":{"A":"Không phải Fast Transmission Port.","B":"Không phải Forward Transfer Proxy.","C":"Không phải File Tracking Program."}},{"id":"abbr_c2_014","chapter":"2","question":"IRC, dịch vụ bị Trojan đánh cắp mật khẩu theo slide, là:","options":{"A":"Intrusion Response Center – trung tâm ứng cứu","B":"Internet Routing Control – điều khiển định tuyến","C":"Internet Relay Chat – trò chuyện trực tuyến","D":"Internal Resource Cache – bộ đệm tài nguyên"},"answer":"C","family":"abbr_c2_014","style":"acronym","section":"2.2","source":"Đề cương mục 2.1-2.5; slide Bài 2 (a, b)","explanation":"IRC là Internet Relay Chat, dịch vụ trò chuyện trực tuyến; Trojan ăn trộm mật khẩu tài khoản IRC.","optionNotes":{"A":"Không phải trung tâm ứng cứu sự cố.","B":"Không phải điều khiển định tuyến.","D":"Không phải bộ đệm tài nguyên."}},{"id":"abbr_c2_015","chapter":"2","question":"API trong kỹ thuật \"chặn các hàm API hỗ trợ mạng\" khi phân tích mã độc là:","options":{"A":"Application Process Isolation Interface","B":"Application Programming Interface","C":"Automated Process Inspector","D":"Access Permission Index"},"answer":"B","family":"abbr_c2_015","style":"acronym","section":"2.4","source":"Đề cương mục 2.1-2.5; slide Bài 2 (a, b)","explanation":"API là Application Programming Interface, giao diện lập trình ứng dụng; chặn các hàm API mạng để mã độc không kết nối ra ngoài khi phân tích.","optionNotes":{"A":"Không phải Application Process Isolation Interface.","C":"Không phải Automated Process Inspector.","D":"Không phải Access Permission Index."}},{"id":"rev_c2_138","chapter":"2","question":"Theo slide, Back Orifice, Trojan đầu tiên trên máy tính, dùng cổng xâm nhập nào?","options":{"A":"443","B":"21","C":"12345","D":"31337"},"answer":"D","family":"port_bo","style":"review","section":"2.2","source":"Đề cương mục 2.1-2.5; slide Bài 2 (a, b)","explanation":"Slide ghi Back Orifice dùng cổng 31337.","optionNotes":{"A":"443 là cổng HTTPS.","B":"21 là cổng FTP, slide gắn với FTP Trojan.","C":"12345 không phải cổng slide ghi cho Back Orifice."}},{"id":"rev_c2_139","chapter":"2","question":"Theo slide, FTP Trojan mở cổng nào trên máy bị nhiễm để người khác tải dữ liệu?","options":{"A":"23","B":"21","C":"25","D":"80"},"answer":"B","family":"port_ftp","style":"review","section":"2.2","source":"Đề cương mục 2.1-2.5; slide Bài 2 (a, b)","explanation":"FTP Trojan mở dịch vụ FTP, cổng mặc định 21, để người khác tải dữ liệu từ máy nạn nhân.","optionNotes":{"A":"23 là Telnet.","C":"25 là SMTP.","D":"80 là HTTP."}},{"id":"rev_c2_140","chapter":"2","question":"Theo slide phòng chống Trojan, công cụ nào giúp xem chương trình nào đang mở cổng nào?","options":{"A":"TCPView, CurrPorts","B":"Barri, Kuang","C":"Back Orifice, NetBus","D":"KGB Spy, DJI RAT"},"answer":"A","family":"rev_c2_140","style":"review","section":"2.2","source":"Đề cương mục 2.1-2.5; slide Bài 2 (a, b)","explanation":"Slide giới thiệu TCPView và CurrPorts để xem chương trình nào đang mở cổng nào, từ đó phát hiện Trojan.","optionNotes":{"B":"Barri, Kuang là tên các Trojan trong slide, không phải công cụ xem cổng.","C":"Back Orifice, NetBus là các Trojan.","D":"KGB Spy, DJI RAT là các Trojan trong mục \"Một số Trojan phổ biến\"."}},{"id":"gen_135","chapter":"3","question":"Theo slide, tường lửa lọc gói (packet filtering) hoạt động ở tầng nào của mô hình OSI?","options":{"A":"Tầng mạng","B":"Tầng ứng dụng","C":"Tầng giao vận","D":"Tầng vật lý"},"answer":"A","family":"g12c1","style":"distinction","section":"3.1-3.2","source":"Đề cương mục 3.1-3.2; slide Bài 3","explanation":"Lọc gói xét IP nguồn/đích (thông tin tầng mạng) nên slide xếp nó ở tầng mạng.","optionNotes":{"B":"Tầng ứng dụng là của application proxy.","C":"Slide gắn tầng giao vận (phiên TCP) với circuit-level gateway.","D":"Tầng vật lý là tín hiệu, cáp; tường lửa không lọc ở đó."}},{"id":"gen_138","chapter":"3","question":"Stateful inspection firewall (SIF) khác packet filtering ở điểm nào?","options":{"A":"Chỉ xét địa chỉ IP nguồn và đích, hoàn toàn không xét số hiệu cổng","B":"Theo dõi trạng thái phiên để biết gói có thuộc kết nối hợp lệ","C":"Chỉ hoạt động ở tầng vật lý","D":"Không thể chặn gói đến từ Internet"},"answer":"B","family":"g12c2","style":"distinction","section":"3.1-3.2","source":"Đề cương mục 3.1-3.2; slide Bài 3","explanation":"Stateful inspection lưu bảng trạng thái phiên, nên biết gói đến có thuộc một kết nối hợp lệ đã thiết lập hay không.","optionNotes":{"A":"SIF vẫn xét cả cổng; không xét cổng là sai với mọi loại lọc gói.","C":"SIF hoạt động ở tầng mạng/giao vận, không ở tầng vật lý.","D":"SIF chặn được gói từ Internet không thuộc phiên nào."}},{"id":"gen_141","chapter":"3","question":"Theo slide, tường lửa cổng vòng (circuit-level gateway) giám sát gì?","options":{"A":"Nội dung lệnh HTTP trong yêu cầu","B":"Quá trình bắt tay TCP giữa các gói","C":"Tín hiệu vô tuyến của AP","D":"Chữ ký virus trong tệp đính kèm"},"answer":"B","family":"g12c3","style":"distinction","section":"3.1-3.2","source":"Đề cương mục 3.1-3.2; slide Bài 3","explanation":"Circuit-level gateway giám sát quá trình bắt tay TCP giữa các gói để quyết định phiên có hợp lệ.","optionNotes":{"A":"Nội dung lệnh HTTP là việc của tường lửa tầng ứng dụng.","C":"Tín hiệu vô tuyến của AP thuộc bảo mật WLAN.","D":"Chữ ký virus là việc của antivirus."}},{"id":"gen_144","chapter":"3","question":"Tường lửa tầng ứng dụng (application-level) có ưu điểm gì?","options":{"A":"Nhanh nhất vì chỉ xét địa chỉ IP nguồn","B":"Kiểm tra được nội dung và lệnh của ứng dụng","C":"Không cần cấu hình bất kỳ luật nào","D":"Chỉ cần hoạt động ở tầng vật lý"},"answer":"B","family":"g12c4","style":"distinction","section":"3.1-3.2","source":"Đề cương mục 3.1-3.2; slide Bài 3","explanation":"Tường lửa tầng ứng dụng hiểu giao thức ứng dụng nên kiểm tra được nội dung và lệnh (ví dụ lệnh HTTP, FTP).","optionNotes":{"A":"Chỉ xét IP là lọc gói; tầng ứng dụng thường chậm hơn vì kiểm tra sâu.","C":"Mọi tường lửa đều cần cấu hình luật.","D":"Nó hoạt động ở tầng ứng dụng, không phải tầng vật lý."}},{"id":"gen_147","chapter":"3","question":"Tường lửa phần cứng khác tường lửa phần mềm cài trên máy ở điểm nào?","options":{"A":"Chỉ bảo vệ đúng một máy đã cài nó","B":"Không thể lọc gói tin theo cổng","C":"Bắt buộc chạy trên máy trạm người dùng","D":"Là thiết bị riêng, bảo vệ cả mạng phía sau"},"answer":"D","family":"g13c1","style":"distinction","section":"3.1-3.2","source":"Đề cương mục 3.1-3.2; slide Bài 3","explanation":"Tường lửa phần cứng là thiết bị riêng đặt trên đường truyền, bảo vệ cả mạng phía sau nó.","optionNotes":{"A":"Chỉ bảo vệ máy đã cài là tường lửa phần mềm trên máy.","B":"Tường lửa phần cứng lọc được theo cổng.","C":"Chạy trên máy trạm là tường lửa phần mềm."}},{"id":"gen_150","chapter":"3","question":"Tường lửa trên máy (host-based firewall) bảo vệ phạm vi nào?","options":{"A":"Toàn bộ mạng LAN phía sau router","B":"Mọi thiết bị kết nối Wi-Fi","C":"Chính máy được cài tường lửa đó","D":"Chỉ các máy trong vùng DMZ"},"answer":"C","family":"g13c2","style":"distinction","section":"3.1-3.2","source":"Đề cương mục 3.1-3.2; slide Bài 3","explanation":"Host-based firewall chạy trên một máy và chỉ bảo vệ chính máy đó.","optionNotes":{"A":"Bảo vệ cả LAN là tường lửa biên/phần cứng.","B":"Nó không bảo vệ các thiết bị Wi-Fi khác.","D":"Nó không giới hạn ở DMZ; máy nào cài thì bảo vệ máy đó."}},{"id":"gen_153","chapter":"3","question":"Tường lửa biên (perimeter firewall) thường đặt ở đâu?","options":{"A":"Bên trong từng máy trạm","B":"Giữa CPU và bộ nhớ của máy chủ","C":"Giữa mạng nội bộ và Internet","D":"Trong tủ điện của tòa nhà"},"answer":"C","family":"g13c3","style":"distinction","section":"3.1-3.2","source":"Đề cương mục 3.1-3.2; slide Bài 3","explanation":"Tường lửa biên đặt giữa mạng nội bộ và Internet để kiểm soát lưu lượng ra vào.","optionNotes":{"A":"Đặt trong từng máy là tường lửa máy chủ.","B":"Tường lửa không đặt giữa CPU và bộ nhớ.","D":"Tủ điện không phải vị trí mạng."}},{"id":"gen_156","chapter":"3","question":"Đặt tường lửa giữa các vùng trong mạng nội bộ chủ yếu nhằm gì?","options":{"A":"Tăng tốc độ truy cập Internet cho các phòng ban trong cùng tòa nhà","B":"Thay thế hoàn toàn tường lửa biên","C":"Giảm số địa chỉ IP cần cấp phát","D":"Hạn chế kẻ tấn công di chuyển ngang khi đã vào LAN"},"answer":"D","family":"g13c4","style":"distinction","section":"3.1-3.2","source":"Đề cương mục 3.1-3.2; slide Bài 3","explanation":"Tường lửa giữa các vùng nội bộ chặn kẻ đã vào LAN đi tiếp sang vùng khác (di chuyển ngang).","optionNotes":{"A":"Thêm lớp kiểm tra không làm Internet nhanh hơn.","B":"Nó bổ sung chứ không thay tường lửa biên.","C":"Tường lửa không quyết định số IP cần cấp."}},{"id":"gen_159","chapter":"3","question":"Kiến trúc chỉ dùng một router lọc gói (screening router) có nhược điểm gì?","options":{"A":"Quá phức tạp vì cần nhiều máy chủ và nhiều vùng mạng riêng biệt","B":"Không thể lọc gói theo địa chỉ IP","C":"Chỉ có một lớp bảo vệ, vượt qua router là vào mạng","D":"Bắt buộc phải có vùng DMZ riêng"},"answer":"C","family":"g14c1","style":"distinction","section":"3.3","source":"Đề cương mục 3.3; slide Bài 3","explanation":"Screening router chỉ có một lớp lọc; vượt qua nó là vào thẳng mạng nội bộ.","optionNotes":{"A":"Đây là kiến trúc đơn giản nhất, không cần nhiều máy chủ hay vùng.","B":"Router lọc gói lọc được theo IP.","D":"Kiến trúc này không có DMZ."}},{"id":"gen_162","chapter":"3","question":"Dual-homed host trong kiến trúc tường lửa là gì?","options":{"A":"Máy cài song song hai hệ điều hành để chạy hai dịch vụ khác nhau","B":"Hai router đặt nối tiếp nhau","C":"Máy có hai card mạng, một nối ngoài, một nối trong","D":"Máy chủ web đặt trong vùng DMZ"},"answer":"C","family":"g14c2","style":"distinction","section":"3.3","source":"Đề cương mục 3.3; slide Bài 3","explanation":"Dual-homed host là máy có hai card mạng, một nối mạng ngoài, một nối mạng trong, và không định tuyến thẳng giữa hai bên.","optionNotes":{"A":"\"Dual\" là hai card mạng, không phải hai hệ điều hành.","B":"Hai router nối tiếp gần với screened subnet.","D":"Máy chủ web trong DMZ là chuyện vị trí, không phải dual-homed."}},{"id":"gen_165","chapter":"3","question":"Kiến trúc screened host gồm những thành phần nào?","options":{"A":"Hai router kẹp một vùng DMZ ở giữa","B":"Chỉ một router lọc gói duy nhất","C":"Một máy có nhiều card mạng nối nhiều vùng","D":"Router lọc gói và một bastion host bên trong"},"answer":"D","family":"g14c3","style":"distinction","section":"3.3","source":"Đề cương mục 3.3; slide Bài 3","explanation":"Screened host gồm router lọc gói ở ngoài và một bastion host bên trong làm điểm nhận kết nối.","optionNotes":{"A":"Hai router kẹp DMZ là screened subnet.","B":"Một router duy nhất là screening router.","C":"Một máy nhiều card nối nhiều vùng là multi-homed."}},{"id":"gen_168","chapter":"3","question":"Kiến trúc screened subnet tạo ra vùng nào giữa hai lớp lọc?","options":{"A":"Vùng DMZ","B":"Vùng VLAN quản trị","C":"Vùng mạng không dây","D":"Vùng sao lưu dữ liệu"},"answer":"A","family":"g14c4","style":"distinction","section":"3.3","source":"Đề cương mục 3.3; slide Bài 3","explanation":"Hai lớp lọc của screened subnet tạo ra vùng DMZ ở giữa để đặt máy chủ công khai.","optionNotes":{"B":"VLAN quản trị không phải vùng mà kiến trúc này tạo ra.","C":"Mạng không dây không liên quan kiến trúc này.","D":"Vùng sao lưu không phải mục đích của kiến trúc này."}},{"id":"gen_171","chapter":"3","question":"Máy chủ nào thường đặt trong vùng DMZ?","options":{"A":"Máy chủ cơ sở dữ liệu nhân sự và bảng lương nội bộ","B":"Máy trạm của phòng kế toán","C":"Máy chủ web, mail công khai ra Internet","D":"Máy chủ quản lý tài khoản nội bộ"},"answer":"C","family":"g15c1","style":"distinction","section":"3.3","source":"Đề cương mục 3.3; slide Bài 3","explanation":"DMZ dành cho máy chủ phải phục vụ Internet như web, mail công khai.","optionNotes":{"A":"Cơ sở dữ liệu nhân sự là dữ liệu nhạy cảm, phải ở sâu trong mạng nội bộ.","B":"Máy trạm kế toán thuộc mạng nội bộ.","D":"Máy chủ quản lý tài khoản nội bộ không được mở ra Internet."}},{"id":"gen_174","chapter":"3","question":"Bastion host là gì?","options":{"A":"Router lọc gói đặt ở biên mạng, chỉ xét địa chỉ IP và cổng của gói","B":"Máy trạm của người quản trị","C":"Máy được gia cố, chỉ chạy ít dịch vụ, chịu tấn công trực tiếp","D":"Máy chủ lưu các bản sao lưu"},"answer":"C","family":"g15c2","style":"distinction","section":"3.3","source":"Đề cương mục 3.3; slide Bài 3","explanation":"Bastion host là máy được gia cố kỹ, chạy rất ít dịch vụ, vì nó đối mặt trực tiếp với tấn công từ ngoài.","optionNotes":{"A":"Router chỉ xét IP và cổng là screening router.","B":"Máy trạm của quản trị viên không phải bastion host.","D":"Máy lưu sao lưu không phải bastion host."}},{"id":"gen_177","chapter":"3","question":"Vì sao không mở trực tiếp các máy trong mạng nội bộ ra Internet?","options":{"A":"Để giảm bề mặt tấn công, chỉ đưa dịch vụ công khai vào DMZ","B":"Vì Internet không hỗ trợ giao thức TCP cho các máy trong mạng nội bộ","C":"Vì máy nội bộ không có địa chỉ MAC","D":"Để tăng tốc độ duyệt web"},"answer":"A","family":"g15c3","style":"distinction","section":"3.3","source":"Đề cương mục 3.3; slide Bài 3","explanation":"Không mở máy nội bộ ra Internet để giảm bề mặt tấn công; chỉ dịch vụ công khai mới đặt ở DMZ.","optionNotes":{"B":"Internet vẫn dùng TCP bình thường.","C":"Máy nội bộ vẫn có địa chỉ MAC.","D":"Lý do là bảo mật, không phải tốc độ."}},{"id":"gen_180","chapter":"3","question":"Lưu lượng từ mạng ngoài (Internet) nên được tường lửa xử lý thế nào?","options":{"A":"Mặc định tin cậy vì lưu lượng đã được nhà mạng kiểm tra trước đó","B":"Mặc định không tin cậy, chỉ cho qua luồng được phép","C":"Cho qua hết rồi ghi log để xem sau","D":"Chỉ chặn khi người dùng báo sự cố"},"answer":"B","family":"g15c4","style":"distinction","section":"3.3","source":"Đề cương mục 3.3; slide Bài 3","explanation":"Lưu lượng từ Internet mặc định không tin cậy; tường lửa chỉ cho qua các luồng được phép rõ ràng.","optionNotes":{"A":"Nhà mạng không kiểm tra an ninh thay cho doanh nghiệp.","C":"Cho qua hết thì ghi log cũng không ngăn được tấn công.","D":"Chờ người dùng báo sự cố là đã quá muộn."}},{"id":"gen_183","chapter":"3","question":"Nguyên tắc từ chối mặc định (default deny) nghĩa là gì?","options":{"A":"Chặn mọi luồng không khớp luật cho phép nào","B":"Cho qua mọi luồng không khớp luật chặn nào","C":"Chặn hết, kể cả luồng đã được cho phép","D":"Chỉ áp dụng cho lưu lượng đi ra"},"answer":"A","family":"g16c1","style":"distinction","section":"3.4","source":"Đề cương mục 3.4; slide Bài 3","explanation":"Default deny chặn mọi luồng không khớp một luật cho phép nào.","optionNotes":{"B":"Cho qua mọi luồng không khớp luật chặn là default allow, ngược lại.","C":"Luồng đã được cho phép thì vẫn đi qua.","D":"Nguyên tắc áp dụng cho cả chiều vào và chiều ra."}},{"id":"gen_186","chapter":"3","question":"Theo slide, nguyên tắc tối thiểu hóa quyền truy cập khi viết luật tường lửa là gì?","options":{"A":"Chỉ mở đúng dịch vụ, cổng và địa chỉ IP cần thiết","B":"Mở mọi cổng dịch vụ để tránh lỗi ứng dụng khi người dùng truy cập","C":"Cấp quyền quản trị cho mọi người dùng","D":"Cho phép Any-Any rồi chặn dần khi có sự cố"},"answer":"A","family":"g16c2","style":"distinction","section":"3.4","source":"Đề cương mục 3.4; slide Bài 3","explanation":"Tối thiểu hóa quyền truy cập: chỉ mở đúng dịch vụ, cổng, địa chỉ IP thật sự cần.","optionNotes":{"B":"Mở mọi cổng làm tăng bề mặt tấn công.","C":"Cấp quyền quản trị cho mọi người ngược với tối thiểu hóa.","D":"Any-Any rồi chặn dần là mặc định cho phép."}},{"id":"gen_189","chapter":"3","question":"Tường lửa xét luật từ trên xuống. Luật cho phép rộng đặt trên luật chặn hẹp thì sao?","options":{"A":"Luật chặn bên dưới được ưu tiên vì nó cụ thể hơn luật phía trên","B":"Tường lửa báo lỗi và dừng hoạt động","C":"Hai luật tự gộp thành một luật","D":"Luật chặn bên dưới không bao giờ được áp dụng"},"answer":"D","family":"g16c3","style":"distinction","section":"3.4","source":"Đề cương mục 3.4; slide Bài 3","explanation":"Tường lửa áp dụng luật khớp đầu tiên; luật cho phép rộng ở trên đã bắt hết, nên luật chặn hẹp bên dưới không bao giờ được dùng.","optionNotes":{"A":"Tường lửa không xét độ cụ thể mà xét thứ tự trên xuống.","B":"Đây là lỗi cấu hình, tường lửa không báo lỗi hay dừng.","C":"Tường lửa không tự gộp luật."}},{"id":"gen_192","chapter":"3","question":"Theo slide, việc vận hành nào giúp phát hiện luật tường lửa thừa hoặc sai?","options":{"A":"Tắt ghi log để giảm tải","B":"Đổi tên thiết bị tường lửa","C":"Tăng thời gian hết hạn phiên","D":"Rà soát luật định kỳ"},"answer":"D","family":"g16c4","style":"distinction","section":"3.4","source":"Đề cương mục 3.4; slide Bài 3","explanation":"Rà soát luật định kỳ giúp tìm luật thừa, trùng hoặc sai thứ tự.","optionNotes":{"A":"Tắt log làm mất dữ liệu để rà soát.","B":"Đổi tên thiết bị không ảnh hưởng luật.","C":"Thời gian hết hạn phiên không giúp tìm luật sai."}},{"id":"gen_195","chapter":"3","question":"Lọc chiều vào (inbound filtering) kiểm soát luồng nào?","options":{"A":"Luồng từ mạng nội bộ đi ra Internet","B":"Luồng giữa hai tiến trình trên một máy","C":"Luồng từ mạng ngoài đi vào mạng nội bộ","D":"Luồng dữ liệu giữa CPU và ổ cứng"},"answer":"C","family":"g17c1","style":"distinction","section":"3.1-3.4","source":"Đề cương mục 3.1-3.4; slide Bài 3","explanation":"Inbound filtering kiểm soát luồng từ mạng ngoài đi vào mạng nội bộ.","optionNotes":{"A":"Từ nội bộ ra Internet là outbound.","B":"Giữa hai tiến trình trên một máy không qua tường lửa mạng.","D":"Luồng CPU – ổ cứng không phải lưu lượng mạng."}},{"id":"gen_198","chapter":"3","question":"Lọc chiều ra (outbound filtering) giúp ngăn điều gì?","options":{"A":"Kẻ tấn công quét cổng từ Internet vào các máy chủ trong vùng DMZ","B":"Người dùng gõ sai mật khẩu đăng nhập","C":"Mất điện làm sập máy chủ","D":"Máy nhiễm mã độc gửi dữ liệu hoặc liên lạc máy điều khiển"},"answer":"D","family":"g17c2","style":"distinction","section":"3.1-3.4","source":"Đề cương mục 3.1-3.4; slide Bài 3","explanation":"Outbound filtering ngăn máy nhiễm mã độc đẩy dữ liệu ra ngoài hoặc liên lạc với máy điều khiển.","optionNotes":{"A":"Quét cổng từ Internet vào là việc của lọc chiều vào.","B":"Gõ sai mật khẩu là chuyện xác thực.","C":"Mất điện không liên quan lọc lưu lượng."}},{"id":"gen_206","chapter":"3","question":"Luật lọc gói chỉ cho máy quản trị 10.0.0.5 vào cổng cấu hình firewall. Luật phân biệt máy này với máy khác dựa vào trường nào?","options":{"A":"Địa chỉ IP đích","B":"Cổng đích","C":"Nội dung HTTP của yêu cầu","D":"Địa chỉ IP nguồn"},"answer":"D","family":"g18c1","style":"scenario","section":"3.1-3.4","source":"Đề cương mục 3.1-3.4; slide Bài 3","explanation":"Chỉ máy 10.0.0.5 được vào, máy khác thì không: luật phân biệt theo người gửi, tức địa chỉ IP nguồn.","optionNotes":{"A":"IP đích là firewall, giống nhau với mọi máy gửi tới.","B":"Cổng đích là cổng cấu hình, giống nhau với mọi máy.","C":"Lọc gói không đọc nội dung HTTP."}},{"id":"gen_209","chapter":"3","question":"Chỉ máy web 203.0.113.10 được nhận TCP 443 từ Internet, các máy nội bộ khác thì không. Luật lọc gói phân biệt dựa vào trường nào?","options":{"A":"Địa chỉ IP nguồn","B":"Cổng nguồn","C":"Địa chỉ IP đích","D":"Cờ TCP SYN"},"answer":"C","family":"g18c2","style":"scenario","section":"3.1-3.4","source":"Đề cương mục 3.1-3.4; slide Bài 3","explanation":"Chỉ máy web 203.0.113.10 được nhận: luật phân biệt theo máy nhận, tức địa chỉ IP đích.","optionNotes":{"A":"Nguồn là bất kỳ máy nào trên Internet.","B":"Cổng nguồn do máy khách chọn ngẫu nhiên.","D":"Cờ SYN có ở mọi kết nối mới, không phân biệt máy web với máy khác."}},{"id":"gen_212","chapter":"3","question":"Cùng một máy chủ, luật cho TCP 443 nhưng chặn TCP 23. Luật phân biệt hai luồng dựa vào trường nào?","options":{"A":"Cổng đích","B":"Địa chỉ IP đích","C":"Địa chỉ IP nguồn","D":"Địa chỉ MAC nguồn"},"answer":"A","family":"g18c3","style":"scenario","section":"3.1-3.4","source":"Đề cương mục 3.1-3.4; slide Bài 3","explanation":"Cùng máy chủ, khác dịch vụ (443 và 23): luật phân biệt bằng cổng đích.","optionNotes":{"B":"IP đích như nhau vì cùng một máy chủ.","C":"Câu hỏi không phân biệt theo người gửi.","D":"MAC nguồn không phân biệt dịch vụ."}},{"id":"gen_215","chapter":"3","question":"LAN được duyệt web bên ngoài; gói trả lời vào được nhưng kết nối do Internet khởi tạo bị chặn, không cần luật mở chiều ngược. Loại tường lửa nào làm được việc này?","options":{"A":"Packet filtering không lưu trạng thái","B":"WAF chỉ bảo vệ ứng dụng web","C":"Stateful inspection firewall","D":"Screening router dùng ACL tĩnh"},"answer":"C","family":"g18c4","style":"scenario","section":"3.1-3.4","source":"Đề cương mục 3.1-3.4; slide Bài 3","explanation":"Stateful inspection nhớ phiên do LAN khởi tạo nên tự cho gói trả lời vào và chặn kết nối do Internet khởi tạo, không cần luật chiều ngược.","optionNotes":{"A":"Lọc gói không trạng thái phải mở luật chiều ngược mới cho gói trả lời vào.","B":"WAF chỉ bảo vệ ứng dụng web, không quản lý phiên duyệt web của cả LAN.","D":"ACL tĩnh không biết gói nào là trả lời của phiên nào."}},{"id":"gen_227","chapter":"3","question":"Kỹ thuật nào cho nhiều máy trong LAN cùng ra Internet bằng một địa chỉ IP công khai?","options":{"A":"VPN","B":"Packet filtering","C":"WAF","D":"NAT"},"answer":"D","family":"g19c4","style":"scenario","section":"3.2-3.4","source":"Đề cương mục 3.2-3.4; slide Bài 3","explanation":"NAT (Network Address Translation) dịch nhiều địa chỉ nội bộ sang một địa chỉ IP công khai khi ra Internet.","optionNotes":{"A":"VPN tạo đường hầm mã hóa giữa hai điểm, không phải để nhiều máy dùng chung một IP công khai.","B":"Packet filtering chặn hoặc cho qua gói theo IP, cổng, giao thức; nó không đổi địa chỉ.","C":"WAF bảo vệ ứng dụng web, không dịch địa chỉ."}},{"id":"case_22","chapter":"3","question":"Doanh nghiệp muốn kiểm tra lệnh HTTP và nội dung yêu cầu, không chỉ địa chỉ IP và cổng. Cần loại tường lửa nào?","options":{"A":"Router không có ACL","B":"Circuit-level gateway chỉ xét phiên","C":"Packet filter thuần túy","D":"Application proxy"},"answer":"D","family":"g12c4","style":"application","section":"3.1-3.2","source":"Đề cương mục 3.1-3.2; slide Bài 3","explanation":"Kiểm tra lệnh HTTP và nội dung yêu cầu cần tường lửa tầng ứng dụng (application proxy).","optionNotes":{"A":"Router không ACL không lọc gì.","B":"Circuit-level gateway chỉ xét phiên, không đọc nội dung.","C":"Packet filter chỉ xét IP, cổng."}},{"id":"case_23","chapter":"3","question":"Web công khai cần ở vùng có thể truy cập từ Internet nhưng không được đứng cùng LAN với cơ sở dữ liệu nội bộ. Vùng nào phù hợp?","options":{"A":"Cùng subnet với máy lưu hồ sơ","B":"Mạng quản trị cơ sở dữ liệu","C":"DMZ","D":"VLAN người dùng nội bộ không lọc"},"answer":"C","family":"g15c1","style":"application","section":"3.3","source":"Đề cương mục 3.3; slide Bài 3","explanation":"Web công khai cần truy cập được từ Internet nhưng tách khỏi LAN chứa dữ liệu, nên đặt ở DMZ.","optionNotes":{"A":"Cùng subnet với hồ sơ thì web bị chiếm là lộ hồ sơ.","B":"Mạng quản trị CSDL là vùng nhạy cảm, không được mở ra Internet.","D":"VLAN người dùng không lọc là mạng nội bộ không được bảo vệ."}},{"id":"case_24","chapter":"3","question":"Mạng có router lọc và một bastion host là điểm nhận kết nối từ ngoài, nhưng không có vùng đệm riêng giữa hai lớp lọc. Kiến trúc nào phù hợp?","options":{"A":"Mạng phẳng không tường lửa","B":"Dual-homed host không router lọc","C":"Screened host","D":"Screened subnet"},"answer":"C","family":"g14c3","style":"application","section":"3.3","source":"Đề cương mục 3.3; slide Bài 3","explanation":"Router lọc cộng một bastion host làm điểm nhận kết nối, không có vùng đệm riêng: đó là screened host.","optionNotes":{"A":"Mạng có router lọc, nên không phải mạng phẳng không tường lửa.","B":"Mạng có router lọc, nên không phải dual-homed không router.","D":"Screened subnet phải có vùng đệm (DMZ) giữa hai lớp lọc."}},{"id":"case_26","chapter":"3","question":"Quản trị viên chỉ muốn mở TCP 443 từ Internet vào web DMZ; mọi luồng khác cần từ chối. Chính sách cuối nên là gì?","options":{"A":"Chuyển tất cả máy vào cùng một VLAN","B":"Default deny sau luật cho phép cụ thể","C":"Allow any-any ở đầu danh sách","D":"Tắt ghi log và cho qua mọi cổng"},"answer":"B","family":"case_26","style":"application","section":"3.4","source":"Đề cương mục 3.4; slide Bài 3","explanation":"Mở đúng luật cụ thể (TCP 443 vào web DMZ) rồi đặt default deny ở cuối để chặn mọi thứ khác.","optionNotes":{"A":"Gộp chung một VLAN làm mất phân vùng.","C":"Allow any-any ở đầu thì mọi thứ đều được qua.","D":"Tắt log và mở mọi cổng ngược hẳn yêu cầu."}},{"id":"case_28","chapter":"3","question":"Một web bị khai thác bằng chuỗi SQL injection trong tham số HTTP. Thiết bị nào chuyên kiểm tra loại yêu cầu này nhất?","options":{"A":"NAT thuần túy","B":"WAF","C":"Bộ cấp phát DHCP","D":"Bộ khuếch đại sóng Wi-Fi"},"answer":"B","family":"g19c1","style":"application","section":"3.2-3.4","source":"Đề cương mục 3.2-3.4; slide Bài 3","explanation":"SQL injection nằm trong tham số HTTP; WAF chuyên kiểm tra yêu cầu web để chặn loại tấn công này.","optionNotes":{"A":"NAT chỉ đổi địa chỉ, không đọc yêu cầu HTTP.","C":"DHCP cấp địa chỉ IP.","D":"Bộ khuếch đại Wi-Fi chỉ tăng sóng."}},{"id":"case_29","chapter":"3","question":"Sau sự cố, đội vận hành cần biết IP nguồn, IP đích, cổng và hành động drop của firewall. Dữ liệu nào phải được giữ?","options":{"A":"Chỉ tên SSID của khách","B":"Chỉ mật khẩu của quản trị viên","C":"Nhật ký quyết định lọc","D":"Chỉ ảnh chụp màn hình người dùng"},"answer":"C","family":"case_29","style":"application","section":"3.2-3.4","source":"Đề cương mục 3.2-3.4; slide Bài 3","explanation":"Nhật ký quyết định lọc ghi lại IP nguồn, đích, cổng và hành động drop để điều tra.","optionNotes":{"A":"SSID không chứa thông tin luồng bị chặn.","B":"Mật khẩu quản trị không phải dữ liệu điều tra và không được lưu kiểu này.","D":"Ảnh chụp màn hình không ghi luồng mạng."}},{"id":"case_30","chapter":"3","question":"Mạng khách và mạng cơ sở dữ liệu cùng ở nội bộ. Biện pháp nào giảm nguy cơ khách di chuyển ngang tới DB?","options":{"A":"Mở quyền truy cập DB cho mọi VLAN","B":"Chỉ đặt firewall ở cổng Internet","C":"Phân vùng mạng và lọc lưu lượng giữa các vùng","D":"Tắt xác thực trên DB"},"answer":"C","family":"case_30","style":"application","section":"3.3-3.4","source":"Đề cương mục 3.3-3.4; slide Bài 3","explanation":"Phân vùng mạng và lọc lưu lượng giữa các vùng chặn khách đi ngang tới DB.","optionNotes":{"A":"Mở DB cho mọi VLAN làm tăng rủi ro.","B":"Firewall ở cổng Internet không thấy luồng khách đi tới DB bên trong.","D":"Tắt xác thực DB càng nguy hiểm hơn."}},{"id":"reviewed_atm_74","chapter":"3","question":"Thiết bị kiểm tra luồng theo quy tắc cho phép/chặn tại ranh giới mạng là gì?","options":{"A":"RADIUS","B":"Firewall","C":"IDS thụ động","D":"Keylogger"},"answer":"B","family":"source_74","style":"review","section":"3.1","source":"https://pttp-huitquiz.site/","explanation":"Firewall kiểm tra luồng theo luật cho phép/chặn tại ranh giới mạng.","optionNotes":{"A":"RADIUS là máy chủ xác thực.","C":"IDS thụ động chỉ phát hiện và cảnh báo, không chặn theo luật.","D":"Keylogger là mã độc ghi phím."}},{"id":"abbr_c3_016","chapter":"3","question":"DMZ là viết tắt của:","options":{"A":"Demilitarized Zone – vùng phi quân sự","B":"Dynamic Management Zone – vùng quản lý động","C":"Direct Mail Zone – vùng thư trực tiếp","D":"Data Monitoring Zone – vùng giám sát dữ liệu"},"answer":"A","family":"abbr_c3_016","style":"acronym","section":"3.3","source":"Đề cương mục 3.1-3.4; slide Bài 3","explanation":"DMZ là Demilitarized Zone, vùng phi quân sự, tức vùng đệm giữa Internet và mạng nội bộ.","optionNotes":{"B":"Không phải Dynamic Management Zone.","C":"Không phải Direct Mail Zone.","D":"Không phải Data Monitoring Zone."}},{"id":"abbr_c3_017","chapter":"3","question":"NAT là viết tắt của:","options":{"A":"Node Authentication Table","B":"Network Access Token","C":"Network Alert Tracking","D":"Network Address Translation"},"answer":"D","family":"abbr_c3_017","style":"acronym","section":"3.1","source":"Đề cương mục 3.1-3.4; slide Bài 3","explanation":"NAT là Network Address Translation, dịch địa chỉ mạng.","optionNotes":{"A":"Không phải Node Authentication Table.","B":"Không phải Network Access Token.","C":"Không phải Network Alert Tracking."}},{"id":"abbr_c3_018","chapter":"3","question":"SIF trong slide phân loại tường lửa là:","options":{"A":"Session Integrity Filter","B":"Stateful Inspection Firewall","C":"Secure Internet Firewall","D":"Static Interface Filter"},"answer":"B","family":"abbr_c3_018","style":"acronym","section":"3.2","source":"Đề cương mục 3.1-3.4; slide Bài 3","explanation":"SIF là Stateful Inspection Firewall, tường lửa kiểm tra trạng thái.","optionNotes":{"A":"Không phải Session Integrity Filter.","C":"Không phải Secure Internet Firewall.","D":"Không phải Static Interface Filter; SIF ngược với lọc tĩnh."}},{"id":"abbr_c3_019","chapter":"3","question":"VPN là viết tắt của:","options":{"A":"Virtual Private Network","B":"Verified Public Network","C":"Virtual Packet Node","D":"Vendor Protected Network"},"answer":"A","family":"abbr_c3_019","style":"acronym","section":"3.1","source":"Đề cương mục 3.1-3.4; slide Bài 3","explanation":"VPN là Virtual Private Network, mạng riêng ảo.","optionNotes":{"B":"Không phải Verified Public Network.","C":"Không phải Virtual Packet Node.","D":"Không phải Vendor Protected Network."}},{"id":"abbr_c3_020","chapter":"3","question":"NGFW là viết tắt của:","options":{"A":"Network-Grade Firewall","B":"Network Gateway Firewall","C":"Next-Generation Firewall","D":"New Global Filtering Wall"},"answer":"C","family":"abbr_c3_020","style":"acronym","section":"3.2","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"NGFW là Next-Generation Firewall, tường lửa thế hệ mới.","optionNotes":{"A":"Không phải Network-Grade Firewall.","B":"Không phải Network Gateway Firewall.","D":"Không phải New Global Filtering Wall."}},{"id":"abbr_c3_021","chapter":"3","question":"WAF là viết tắt của:","options":{"A":"Wireless Access Firewall","B":"Web Application Firewall","C":"Web Access Forwarder","D":"Wide Area Filter"},"answer":"B","family":"ab_waf","style":"acronym","section":"3.2","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"WAF là Web Application Firewall, tường lửa ứng dụng web.","optionNotes":{"A":"Không phải Wireless Access Firewall.","C":"Không phải Web Access Forwarder.","D":"Không phải Wide Area Filter."}},{"id":"abbr_c3_022","chapter":"3","question":"FWaaS là viết tắt của:","options":{"A":"Filtering Web as a Standard","B":"Firewall with Antivirus and Scanning","C":"Firewall Wide-area Access System","D":"Firewall as a Service"},"answer":"D","family":"abbr_c3_022","style":"acronym","section":"3.2","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"FWaaS là Firewall as a Service, tường lửa cung cấp dạng dịch vụ đám mây.","optionNotes":{"A":"Không phải Filtering Web as a Standard.","B":"Không phải Firewall with Antivirus and Scanning.","C":"Không phải Firewall Wide-area Access System."}},{"id":"abbr_c3_023","chapter":"3","question":"SASE là viết tắt của:","options":{"A":"Secure Access Service Edge","B":"Software-Assisted Security Engine","C":"Secure Application Server Environment","D":"System Access and Session Encryption"},"answer":"A","family":"ab_sase","style":"acronym","section":"3.3","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"SASE là Secure Access Service Edge.","optionNotes":{"B":"Không phải Software-Assisted Security Engine.","C":"Không phải Secure Application Server Environment.","D":"Không phải System Access and Session Encryption."}},{"id":"abbr_c3_024","chapter":"3","question":"Trong slide về SASE, SSE là viết tắt của:","options":{"A":"Secure Socket Encryption","B":"Session Security Engine","C":"Security Service Edge","D":"Secure Server Exchange"},"answer":"C","family":"ab_sse","style":"acronym","section":"3.3","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"SSE là Security Service Edge, phần dịch vụ bảo mật của SASE.","optionNotes":{"A":"Không phải Secure Socket Encryption.","B":"Không phải Session Security Engine.","D":"Không phải Secure Server Exchange."}},{"id":"abbr_c3_025","chapter":"3","question":"ZTNA là viết tắt của:","options":{"A":"Zoned Traffic Network Analyzer","B":"Zero Trust Network Access","C":"Zero-Time Network Authentication","D":"Zone Transfer Network Address"},"answer":"B","family":"abbr_c3_025","style":"acronym","section":"3.3","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"ZTNA là Zero Trust Network Access, truy cập mạng theo Zero Trust.","optionNotes":{"A":"Không phải Zoned Traffic Network Analyzer.","C":"Chữ T là Trust, không phải Time; chữ A là Access, không phải Authentication.","D":"Không phải Zone Transfer Network Address."}},{"id":"abbr_c3_026","chapter":"3","question":"SWG, một thành phần của SSE, là:","options":{"A":"Switched Wireless Gateway","B":"Software WAN Gateway","C":"Secure Web Gateway","D":"Server Workload Guard"},"answer":"C","family":"ab_sse_parts","style":"acronym","section":"3.3","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"SWG là Secure Web Gateway, cổng kiểm soát truy cập web an toàn.","optionNotes":{"A":"Không phải Switched Wireless Gateway.","B":"Không phải Software WAN Gateway.","D":"Không phải Server Workload Guard."}},{"id":"abbr_c3_027","chapter":"3","question":"CASB, một thành phần của SSE, là:","options":{"A":"Cloud Application Signature Base","B":"Content-Aware Security Backbone","C":"Central Authentication Service Broker","D":"Cloud Access Security Broker"},"answer":"D","family":"ab_sse_parts","style":"acronym","section":"3.3","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"CASB là Cloud Access Security Broker, kiểm soát việc dùng dịch vụ đám mây.","optionNotes":{"A":"Không phải Cloud Application Signature Base.","B":"Không phải Content-Aware Security Backbone.","C":"Không phải Central Authentication Service Broker."}},{"id":"abbr_c3_028","chapter":"3","question":"SD-WAN trong kiến trúc SASE là:","options":{"A":"Software-Defined Wide Area Network","B":"Secure Data Wide Area Network","C":"Single-Domain Wide Area Network","D":"Switched Digital Wide Area Network"},"answer":"A","family":"ab_sase","style":"acronym","section":"3.3","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"SD-WAN là Software-Defined Wide Area Network, mạng diện rộng điều khiển bằng phần mềm.","optionNotes":{"B":"SD là Software-Defined, không phải Secure Data.","C":"SD không phải Single-Domain.","D":"SD không phải Switched Digital."}},{"id":"rev_c3_029","chapter":"3","question":"Theo slide, SSE tập hợp các dịch vụ:","options":{"A":"SWG, CASB, ZTNA và FWaaS","B":"DMZ, NAT, VPN, DHCP và DNS","C":"IDS, IPS, NIDS và HIDS","D":"WEP, WPA, WPA2 và WPA3"},"answer":"A","family":"ab_sse","style":"review","section":"3.3","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Theo slide, SSE gồm SWG, CASB, ZTNA và FWaaS.","optionNotes":{"B":"DMZ, NAT, VPN, DHCP, DNS là các thành phần mạng truyền thống.","C":"IDS, IPS, NIDS, HIDS là nhóm phát hiện xâm nhập ở Bài 4.","D":"WEP, WPA, WPA2 là các chuẩn bảo mật Wi-Fi ở Bài 5."}},{"id":"rev_c3_030","chapter":"3","question":"SASE là sự hội tụ của:","options":{"A":"DMZ với máy chủ proxy truyền thống","B":"IDS với bộ lọc gói tại router biên","C":"WAF với cơ sở dữ liệu chữ ký virus","D":"SSE với kết nối diện rộng như SD-WAN"},"answer":"D","family":"ab_sase","style":"review","section":"3.3","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"SASE = SSE (dịch vụ bảo mật) + kết nối diện rộng như SD-WAN.","optionNotes":{"A":"DMZ và proxy là kiến trúc truyền thống, không phải SASE.","B":"IDS và router lọc không phải định nghĩa của SASE.","C":"WAF và chữ ký virus không phải định nghĩa của SASE."}},{"id":"rev_c3_031","chapter":"3","question":"Theo slide, Zero Trust là:","options":{"A":"Chế độ tin cậy mọi máy trong mạng LAN","B":"Mô hình kiến trúc, không phải một loại thiết bị","C":"Một dòng NGFW đời mới của nhà sản xuất","D":"Giao thức mã hóa mới dùng thay thế cho TLS 1.3"},"answer":"B","family":"rev_c3_031","style":"review","section":"3.4","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Slide nói Zero Trust là mô hình kiến trúc (không mặc định tin ai), không phải một thiết bị cụ thể.","optionNotes":{"A":"Zero Trust ngược lại: không tin mặc định, kể cả máy trong LAN.","C":"Zero Trust không phải dòng sản phẩm NGFW.","D":"Zero Trust không phải giao thức mã hóa."}},{"id":"rev_c3_032","chapter":"3","question":"So với NGFW, WAF:","options":{"A":"Kiểm soát mọi giao thức trong mạng","B":"Chỉ lọc theo IP, cổng và giao thức","C":"Chuyên bảo vệ HTTP/HTTPS và API","D":"Là bản mạnh hơn, thay thế được NGFW"},"answer":"C","family":"ab_waf","style":"review","section":"3.2","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"WAF chuyên bảo vệ ứng dụng web: lưu lượng HTTP/HTTPS và API.","optionNotes":{"A":"Kiểm soát mọi giao thức là phạm vi của NGFW.","B":"Chỉ lọc IP, cổng, giao thức là lọc gói; WAF đọc nội dung yêu cầu web.","D":"WAF không thay NGFW; hai loại bổ sung cho nhau."}},{"id":"rev_c3_033","chapter":"3","question":"Lưu lượng east–west là lưu lượng:","options":{"A":"Từ người dùng từ xa vào VPN","B":"Từ ISP tới router biên","C":"Giữa server, VLAN, VM bên trong","D":"Giữa doanh nghiệp và Internet"},"answer":"C","family":"rev_c3_033","style":"review","section":"3.1","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"East-west là lưu lượng bên trong: giữa các server, VLAN, VM.","optionNotes":{"A":"Người dùng từ xa vào VPN là luồng north-south.","B":"ISP tới router biên là luồng north-south.","D":"Doanh nghiệp ra Internet là north-south."}},{"id":"rev_c3_035","chapter":"3","question":"Hạn chế chính của proxy firewall theo slide là:","options":{"A":"Không kiểm tra được nội dung ứng dụng","B":"Không theo dõi được trạng thái phiên","C":"Chỉ bảo vệ được ứng dụng web và API","D":"Tăng độ trễ do ngắt và tạo lại kết nối"},"answer":"D","family":"rev_c3_035","style":"review","section":"3.2","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Slide ghi proxy firewall chấm dứt rồi tạo lại kết nối, nên tăng độ trễ.","optionNotes":{"A":"Proxy kiểm tra được nội dung ứng dụng; đó là ưu điểm của nó.","B":"Hạn chế slide nêu là độ trễ, không phải theo dõi phiên.","C":"Chỉ bảo vệ web và API là đặc điểm của WAF."}},{"id":"rev_c3_141","chapter":"3","question":"Trong ma trận chính sách mẫu của slide Bài 3, Internet được vào WAF qua dịch vụ nào?","options":{"A":"SMTP/25","B":"HTTPS/443","C":"FTP/21","D":"HTTP/80"},"answer":"B","family":"port_https","style":"review","section":"3.4","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Trong ma trận chính sách mẫu, Internet chỉ được vào WAF qua HTTPS/443.","optionNotes":{"A":"SMTP/25 là thư, không phải dịch vụ vào WAF.","C":"FTP/21 là truyền tệp, không có trong luồng Internet vào WAF.","D":"Ma trận dùng HTTPS/443, không mở HTTP/80 không mã hóa."}},{"id":"rev_c3_142","chapter":"3","question":"Theo slide, tường lửa đóng vai trò gì giữa hai loại mạng?","options":{"A":"Máy chủ cấp địa chỉ IP cho mạng nội bộ","B":"Bộ chuyển tiếp mọi gói tin không cần kiểm tra","C":"Rào chắn giữa mạng tin cậy và mạng không tin cậy","D":"Thiết bị tăng tốc đường truyền Internet"},"answer":"C","family":"rev_c3_142","style":"review","section":"3.1","source":"Đề cương mục 3.1-3.4; slide Bài 3","explanation":"Slide định nghĩa tường lửa là rào chắn giữa mạng tin cậy (nội bộ) và mạng không tin cậy (Internet).","optionNotes":{"A":"Cấp địa chỉ IP là DHCP.","B":"Tường lửa phải kiểm tra gói, không chuyển tiếp mù.","D":"Tường lửa không nhằm tăng tốc đường truyền."}},{"id":"rev_c3_143","chapter":"3","question":"Theo slide, nhóm nào đều là chức năng chính của tường lửa?","options":{"A":"Cấp phát IP, phân giải tên miền, gửi email","B":"Diệt virus, vá lỗi, cập nhật hệ điều hành","C":"Mã hóa ổ cứng, sao lưu, khôi phục dữ liệu","D":"Kiểm soát dịch vụ, hướng, người dùng, hành vi"},"answer":"D","family":"rev_c3_143","style":"review","section":"3.1","source":"Đề cương mục 3.1-3.4; slide Bài 3","explanation":"Slide nêu bốn chức năng: kiểm soát dịch vụ, hướng, người dùng và hành vi.","optionNotes":{"A":"Cấp IP, phân giải tên, gửi mail là DHCP, DNS, mail server.","B":"Diệt virus, vá lỗi là việc của antivirus và quản lý bản vá.","C":"Mã hóa ổ cứng, sao lưu là các biện pháp bảo vệ dữ liệu khác."}},{"id":"rev_c3_144","chapter":"3","question":"Theo slide, sản phẩm nào là tường lửa phần cứng?","options":{"A":"Cisco ASA","B":"ISA Server Firewall","C":"Wireshark","D":"IPCOP"},"answer":"A","family":"rev_c3_144","style":"review","section":"3.1","source":"Đề cương mục 3.1-3.4; slide Bài 3","explanation":"Slide liệt kê Cisco ASA (cùng Checkpoint, CyberRoam) là tường lửa phần cứng.","optionNotes":{"B":"ISA Server Firewall được slide xếp vào giải pháp phần mềm.","C":"Wireshark là công cụ bắt gói, không phải tường lửa.","D":"IPCOP được slide xếp vào giải pháp phần mềm."}},{"id":"rev_c3_145","chapter":"3","question":"Theo slide, kiến trúc tường lửa kết hợp gồm những mô hình nào?","options":{"A":"WEP, WPA, WPA2","B":"Screened Host, Screened Subnet, Multi-homed Firewall","C":"Standalone, Distributed, Hybrid IDPS","D":"Packet Filtering, Circuit Gateway, Application"},"answer":"B","family":"rev_c3_145","style":"review","section":"3.3","source":"Đề cương mục 3.1-3.4; slide Bài 3","explanation":"Slide xếp Screened Host, Screened Subnet và Multi-homed Firewall vào kiến trúc kết hợp.","optionNotes":{"A":"WEP, WPA, WPA2 là chuẩn bảo mật Wi-Fi.","C":"Standalone, Distributed, Hybrid là kiến trúc IDPS ở Bài 4.","D":"Packet Filtering, Circuit Gateway, Application là các loại tường lửa theo cách lọc, không phải kiến trúc."}},{"id":"rev_c3_146","chapter":"3","question":"Multi-homed firewall là tường lửa như thế nào?","options":{"A":"Chỉ có một cổng mạng duy nhất","B":"Cài phần mềm tường lửa trên nhiều máy trạm cùng lúc để bảo vệ từng máy","C":"Có nhiều cổng mạng, nối và tách nhiều vùng như LAN, DMZ, Internet","D":"Chạy hoàn toàn trên dịch vụ đám mây"},"answer":"C","family":"rev_c3_146","style":"review","section":"3.3","source":"Đề cương mục 3.1-3.4; slide Bài 3","explanation":"Multi-homed firewall có nhiều cổng mạng, nối và tách nhiều vùng như LAN, DMZ, Internet.","optionNotes":{"A":"\"Multi-homed\" nghĩa là nhiều cổng, không phải một.","B":"Cài trên nhiều máy trạm là tường lửa trên máy, không phải multi-homed.","D":"Multi-homed nói về số cổng mạng, không phải chạy trên đám mây."}},{"id":"rev_c3_147","chapter":"3","question":"Kiến trúc tường lửa đơn lẻ có đặc điểm gì?","options":{"A":"Chỉ một thiết bị đảm nhận toàn bộ việc lọc và bảo vệ","B":"Không cần chính sách bảo mật nào","C":"Nhiều tường lửa phối hợp với nhau qua một mặt phẳng quản lý chung","D":"Tường lửa đặt trong từng pod Kubernetes"},"answer":"A","family":"rev_c3_147","style":"review","section":"3.3","source":"Đề cương mục 3.1-3.4; slide Bài 3","explanation":"Kiến trúc đơn lẻ: một thiết bị tường lửa duy nhất đảm nhận toàn bộ việc lọc.","optionNotes":{"B":"Kiến trúc nào cũng cần chính sách.","C":"Nhiều tường lửa quản lý chung là hybrid mesh.","D":"Tường lửa trong pod Kubernetes là NetworkPolicy/eBPF."}},{"id":"rev_c3_148","chapter":"3","question":"Theo slide, hybrid mesh firewall là gì?","options":{"A":"Một giao thức tiêu chuẩn mới do IEEE ban hành để thay thế mô hình TCP/IP","B":"Thuật toán mã hóa gói tin của tường lửa","C":"Tường lửa chỉ dùng cho mạng không dây mesh","D":"Thuật ngữ thị trường chỉ nền tảng quản lý thống nhất nhiều loại firewall"},"answer":"D","family":"rev_c3_148","style":"review","section":"3.3","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Slide nói hybrid mesh firewall là thuật ngữ thị trường cho nền tảng quản lý thống nhất nhiều loại firewall (vật lý, ảo, đám mây).","optionNotes":{"A":"Không phải giao thức của IEEE.","B":"Không phải thuật toán mã hóa.","C":"\"Mesh\" ở đây không phải mạng không dây mesh."}},{"id":"rev_c3_149","chapter":"3","question":"Theo slide, nhược điểm của hybrid mesh firewall là gì?","options":{"A":"Không hỗ trợ tường lửa phần cứng","B":"Bắt buộc tắt hết ghi log","C":"Phụ thuộc nhà cung cấp; lộ tài khoản quản trị trung tâm thì ảnh hưởng rộng","D":"Không thể dùng cho môi trường hybrid hoặc multi-cloud vì thiếu chuẩn chung"},"answer":"C","family":"rev_c3_149","style":"review","section":"3.3","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Slide nêu nhược điểm: phụ thuộc nhà cung cấp, và lộ tài khoản quản trị trung tâm thì ảnh hưởng toàn hệ thống.","optionNotes":{"A":"Hybrid mesh quản lý cả tường lửa phần cứng.","B":"Không có yêu cầu tắt log.","D":"Hybrid mesh sinh ra chính để dùng cho hybrid/multi-cloud."}},{"id":"rev_c3_150","chapter":"3","question":"Theo slide, Kubernetes NetworkPolicy chỉ có tác dụng khi nào?","options":{"A":"Khi CNI của cụm hỗ trợ thực thi NetworkPolicy","B":"Khi đã tắt tường lửa ngoại vi","C":"Khi mọi pod dùng chung một địa chỉ IP","D":"Khi cụm có ít hơn ba node và chạy trên một máy chủ vật lý"},"answer":"A","family":"rev_c3_150","style":"review","section":"3.2","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"NetworkPolicy chỉ là khai báo; CNI của cụm phải hỗ trợ thì chính sách mới được thực thi.","optionNotes":{"B":"Tường lửa ngoại vi không liên quan việc NetworkPolicy có tác dụng.","C":"Mỗi pod có IP riêng; NetworkPolicy không đòi chung IP.","D":"Số node không quyết định NetworkPolicy có tác dụng."}},{"id":"rev_c3_151","chapter":"3","question":"Theo slide, eBPF (ví dụ Cilium) thực thi chính sách tường lửa ở đâu?","options":{"A":"Trên máy chủ RADIUS","B":"Ngay trong Linux kernel","C":"Trên router biên của ISP","D":"Trong BIOS của máy chủ"},"answer":"B","family":"rev_c3_151","style":"review","section":"3.2","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"eBPF (như Cilium) chạy chương trình lọc ngay trong Linux kernel.","optionNotes":{"A":"RADIUS là máy chủ xác thực.","C":"Router của ISP nằm ngoài cụm.","D":"BIOS không thực thi chính sách mạng."}},{"id":"rev_c3_152","chapter":"3","question":"Theo slide, vì sao TLS 1.3 và QUIC làm tường lửa khó kiểm tra lưu lượng hơn?","options":{"A":"Chúng tắt hoàn toàn cổng 443","B":"Chúng chỉ chạy trên mạng nội bộ","C":"Hai giao thức này không dùng địa chỉ IP nên tường lửa không định tuyến được","D":"Mã hóa thêm thông tin nên thiết bị trung gian thấy ít hơn"},"answer":"D","family":"rev_c3_152","style":"review","section":"3.2","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"TLS 1.3 và QUIC mã hóa thêm nhiều thông tin, nên thiết bị trung gian thấy ít hơn để kiểm tra.","optionNotes":{"A":"Chúng vẫn dùng cổng 443.","B":"Chúng dùng trên Internet, không chỉ nội bộ.","C":"Chúng vẫn chạy trên IP."}},{"id":"rev_c3_153","chapter":"3","question":"Theo slide, vì sao không nên luôn bật giải mã TLS trên tường lửa?","options":{"A":"Vì giải mã TLS làm mất địa chỉ IP nguồn và cổng đích của mọi gói tin đi qua","B":"Tăng tải, ảnh hưởng quyền riêng tư, có thể vi phạm yêu cầu bảo mật","C":"Vì TLS không thể bị giải mã ở bất kỳ đâu","D":"Vì giải mã TLS bắt buộc phải tắt NAT"},"answer":"B","family":"rev_c3_153","style":"review","section":"3.2","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Slide nêu giải mã TLS làm tăng tải, ảnh hưởng quyền riêng tư và có thể vi phạm yêu cầu bảo mật, nên không bật tràn lan.","optionNotes":{"A":"Giải mã nội dung không làm mất IP nguồn hay cổng đích.","C":"Tường lửa giải mã được TLS (đóng vai trung gian), chỉ là có cái giá phải trả.","D":"Giải mã TLS không bắt buộc tắt NAT."}},{"id":"rev_c3_154","chapter":"3","question":"Theo slide, nhận định \"AI tự động chặn mọi mối đe dọa chưa biết\" được đánh giá thế nào?","options":{"A":"Đúng; AI đã thay thế hoàn toàn luật, chữ ký và người phân tích trong tường lửa","B":"Đúng với mọi tường lửa đời mới","C":"Chỉ đúng khi bật giải mã TLS","D":"Sai; AI chỉ nên bổ trợ luật, chữ ký, sandbox và chuyên gia"},"answer":"D","family":"rev_c3_154","style":"review","section":"3.2","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Slide đánh giá nhận định này sai: AI chỉ bổ trợ cho luật, chữ ký, sandbox và chuyên gia.","optionNotes":{"A":"AI không thay thế hoàn toàn luật và con người.","B":"Không tường lửa nào chặn được mọi mối đe dọa chưa biết.","C":"Bật giải mã TLS không làm AI chặn được mọi thứ."}},{"id":"rev_c3_155","chapter":"3","question":"Theo slide, ngân hàng chỉ mua NGFW mới nhưng vẫn cho máy chủ giao tiếp tự do thì rủi ro nào còn nguyên?","options":{"A":"Hết địa chỉ IP nội bộ","B":"Không truy cập được HTTPS","C":"Di chuyển ngang giữa các máy chủ","D":"Mất kết nối Internet của toàn bộ chi nhánh"},"answer":"C","family":"rev_c3_155","style":"review","section":"3.4","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"NGFW ở biên không chặn luồng giữa các máy chủ bên trong; máy chủ giao tiếp tự do nên kẻ tấn công vẫn di chuyển ngang được.","optionNotes":{"A":"Số địa chỉ IP không liên quan.","B":"HTTPS vẫn truy cập bình thường.","D":"Kết nối Internet không bị ảnh hưởng."}},{"id":"des_c3_01","chapter":"3","question":"Theo slide, nguyên tắc \"không tin cậy theo vị trí\" khi thiết kế tường lửa nghĩa là gì?","options":{"A":"Thiết bị trong LAN hoặc đã kết nối VPN không đương nhiên an toàn","B":"Chỉ tin cậy các máy có địa chỉ IP nội bộ","C":"Lưu lượng đi qua VPN được cho qua mà không cần kiểm tra","D":"Tường lửa chỉ cần đặt ở biên Internet là đủ"},"answer":"A","family":"des_c3_01","style":"review","section":"3.4","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Slide nêu nguyên tắc không tin cậy theo vị trí: thiết bị trong LAN hoặc đã VPN không đương nhiên an toàn, mỗi truy cập vẫn phải được kiểm tra.","optionNotes":{"B":"Tin máy chỉ vì có IP nội bộ chính là tin theo vị trí, điều slide bác bỏ.","C":"Slide nói rõ đã VPN cũng không đương nhiên an toàn.","D":"Slide nhấn mạnh biên mạng không còn là một đường ranh duy nhất; chỉ đặt ở biên là không đủ."}},{"id":"des_c3_02","chapter":"3","question":"Theo slide, \"tách mặt phẳng quản trị\" tường lửa yêu cầu điều gì?","options":{"A":"Quản trị tường lửa từ bất kỳ máy nào trong LAN cho tiện","B":"Không quản trị từ VLAN người dùng; dùng MFA và máy quản trị chuyên dụng","C":"Tắt ghi log các thao tác quản trị để giảm tải","D":"Dùng chung một tài khoản quản trị cho cả nhóm"},"answer":"B","family":"des_c3_02","style":"review","section":"3.4","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Tách mặt phẳng quản trị: không quản trị firewall từ VLAN người dùng, bật MFA, phân quyền theo vai trò, dùng máy quản trị chuyên dụng.","optionNotes":{"A":"Quản trị từ bất kỳ máy LAN nào là đúng điều slide cấm.","C":"Slide yêu cầu quan sát liên tục và giám sát thay đổi chính sách, không tắt log.","D":"Dùng chung tài khoản đi ngược phân quyền theo vai trò và MFA."}},{"id":"des_c3_03","chapter":"3","question":"Theo slide, Policy as Code trong thiết kế tường lửa là gì?","options":{"A":"Viết luật trực tiếp trên thiết bị và không cần lưu lịch sử thay đổi","B":"Một ngôn ngữ lập trình mới thay thế hoàn toàn luật lọc gói","C":"Biểu diễn chính sách dưới dạng mã, lưu phiên bản, kiểm tra trước khi triển khai","D":"Để AI tự sinh luật và tự triển khai mà không cần kiểm tra"},"answer":"C","family":"des_c3_03","style":"review","section":"3.4","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Policy as Code: chính sách được viết dưới dạng mã, lưu phiên bản, kiểm tra trước khi triển khai và tích hợp CI/CD.","optionNotes":{"A":"Không lưu lịch sử là ngược với việc lưu phiên bản.","B":"Policy as Code là cách quản lý luật, không phải ngôn ngữ thay thế luật lọc gói.","D":"Policy as Code nhấn mạnh kiểm tra trước triển khai; AI tự triển khai không kiểm tra là sai."}},{"id":"des_c3_04","chapter":"3","question":"Theo slide, doanh nghiệp lắp hai tường lửa thì có tự động đạt tính sẵn sàng cao (HA) không?","options":{"A":"Có, hai thiết bị luôn tự động tạo thành HA","B":"Có, miễn là hai thiết bị cùng một hãng","C":"Không, vì HA chỉ có trên tường lửa đám mây","D":"Không; còn cần cấu hình HA, dự phòng đường truyền và kiểm thử failover"},"answer":"D","family":"des_c3_04","style":"review","section":"3.4","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Slide ghi rõ hai thiết bị không tự động là HA: còn cần cấu hình HA, dự phòng đường truyền, sao lưu cấu hình và kiểm thử failover.","optionNotes":{"A":"Slide nói ngược lại: 2 thiết bị KHÔNG tự động là HA.","B":"Cùng hãng không làm hai thiết bị tự thành HA.","C":"HA áp dụng cho cả tường lửa phần cứng tại chỗ, không riêng đám mây."}},{"id":"des_c3_05","chapter":"3","question":"Theo slide, microsegmentation dùng để làm gì?","options":{"A":"Chia nhỏ và lọc lưu lượng giữa từng máy chủ, dịch vụ để hạn chế di chuyển ngang","B":"Chia băng thông Internet cho từng người dùng","C":"Mã hóa toàn bộ lưu lượng đi ra Internet","D":"Gộp nhiều VLAN thành một mạng phẳng để dễ quản lý"},"answer":"A","family":"des_c3_05","style":"review","section":"3.3","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Microsegmentation chia nhỏ mạng và lọc lưu lượng giữa từng máy chủ, dịch vụ (east–west) để kẻ tấn công khó di chuyển ngang.","optionNotes":{"B":"Chia băng thông là QoS, không phải microsegmentation.","C":"Mã hóa lưu lượng ra Internet là việc của TLS/VPN.","D":"Gộp thành mạng phẳng làm di chuyển ngang dễ hơn, ngược với mục đích."}},{"id":"des_c3_06","chapter":"3","question":"Theo slide, lưu lượng north–south là lưu lượng nào?","options":{"A":"Giữa các server, VLAN, VM bên trong doanh nghiệp","B":"Giữa doanh nghiệp và bên ngoài","C":"Giữa hai tiến trình trên cùng một máy","D":"Chỉ lưu lượng quản trị thiết bị mạng"},"answer":"B","family":"rev_c3_033","style":"review","section":"3.1","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Slide định nghĩa north–south là lưu lượng giữa doanh nghiệp và bên ngoài; east–west là bên trong.","optionNotes":{"A":"Giữa server, VLAN, VM bên trong là east–west.","C":"Giữa hai tiến trình trên một máy không đi qua mạng nên không phải north–south.","D":"North–south gồm mọi lưu lượng ra vào doanh nghiệp, không riêng lưu lượng quản trị."}},{"id":"des_c3_07","chapter":"3","question":"Theo slide, khi xây dựng ma trận chính sách tường lửa cần tránh loại luật nào?","options":{"A":"Luật cho phép Internet vào WAF qua HTTPS/443","B":"Luật từ chối và ghi log đặt ở cuối","C":"Luật Any–Any–Allow (mọi nguồn, mọi đích, cho phép)","D":"Luật chặn VLAN IoT tới VLAN Server"},"answer":"C","family":"des_c3_07","style":"review","section":"3.4","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Bước 6 của quy trình: xây dựng ma trận chính sách, tránh Any–Any–Allow, ghi rõ lý do và thời hạn từng luật.","optionNotes":{"A":"Internet → WAF qua HTTPS/443 là luật mẫu được cho phép trong slide.","B":"Từ chối và ghi log ở cuối là luật mặc định đúng.","D":"Chặn VLAN IoT tới VLAN Server là luật mẫu đúng trong ma trận của slide."}},{"id":"des_c3_08","chapter":"3","question":"Theo slide, bước \"kiểm thử 2 chiều\" trong quy trình thiết kế tường lửa kiểm tra điều gì?","options":{"A":"Tốc độ tải lên và tải xuống của đường truyền","B":"Tường lửa chạy được trên cả IPv4 và IPv6","C":"Hai quản trị viên cùng đăng nhập được một lúc","D":"Luồng hợp lệ hoạt động và luồng trái phép bị chặn"},"answer":"D","family":"des_c3_08","style":"review","section":"3.4","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Bước 9: kiểm thử 2 chiều, xác nhận luồng hợp lệ vẫn chạy VÀ luồng trái phép thật sự bị chặn.","optionNotes":{"A":"Đo tốc độ đường truyền không kiểm tra chính sách cho phép/từ chối.","B":"Hỗ trợ IPv4/IPv6 không phải nội dung của bước kiểm thử 2 chiều.","C":"Đăng nhập đồng thời không liên quan việc kiểm tra luật."}},{"id":"des_c3_09","chapter":"3","question":"Theo slide, bước đầu tiên của quy trình thiết kế tường lửa là gì?","options":{"A":"Kiểm kê tài sản","B":"Xây dựng ma trận chính sách","C":"Triển khai theo giai đoạn","D":"Vận hành liên tục"},"answer":"A","family":"des_c3_09","style":"review","section":"3.4","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Quy trình 10 bước bắt đầu bằng kiểm kê tài sản: thiết bị, SaaS, tài khoản cloud, API, container.","optionNotes":{"B":"Xây dựng ma trận chính sách là bước 6.","C":"Triển khai theo giai đoạn là bước 8.","D":"Vận hành liên tục là bước cuối (bước 10)."}},{"id":"des_c3_10","chapter":"3","question":"Theo slide, vì sao luật theo ngữ cảnh (nhóm người dùng, thiết bị đạt chuẩn, MFA) chặt chẽ hơn luật \"10.10.20.0/24 → TCP/443\"?","options":{"A":"Vì luật theo IP không chặn được cổng 443","B":"Vì địa chỉ IP không chứng minh người dùng là ai hay thiết bị có an toàn","C":"Vì luật theo ngữ cảnh không cần ghi log","D":"Vì luật theo IP chỉ dùng được cho mạng không dây"},"answer":"B","family":"des_c3_10","style":"review","section":"3.1","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Slide giải thích: địa chỉ IP không chứng minh được người dùng là ai hay thiết bị có an toàn, nên luật theo ngữ cảnh chặt hơn.","optionNotes":{"A":"Luật theo IP vẫn chặn hoặc cho phép được cổng 443.","C":"Luật theo ngữ cảnh trong slide vẫn \"Cho phép và ghi log\".","D":"Luật theo IP dùng cho mọi loại mạng, không riêng mạng không dây."}},{"id":"des_c3_11","chapter":"3","question":"Theo slide, nhân viên làm việc tại nhà dùng SaaS nên được bảo vệ thế nào?","options":{"A":"Buộc toàn bộ lưu lượng SaaS quay về tường lửa ở trụ sở","B":"Tắt tường lửa khi làm việc tại nhà để tăng tốc độ","C":"Dùng FWaaS ở điểm dịch vụ gần người dùng, ZTNA cho ứng dụng nội bộ","D":"Chỉ cần NGFW tại trụ sở là đủ cho mọi trường hợp"},"answer":"C","family":"des_c3_11","style":"review","section":"3.2","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Slide khuyên không kéo lưu lượng SaaS về trụ sở: dùng FWaaS gần người dùng, ZTNA cho ứng dụng nội bộ, NGFW trụ sở lo tài nguyên tại chỗ.","optionNotes":{"A":"Slide nói rõ KHÔNG nên buộc lưu lượng SaaS quay về trụ sở.","B":"Tắt tường lửa bỏ mất lớp bảo vệ.","D":"Lưu lượng SaaS từ nhà có thể không đi qua NGFW trụ sở, nên chỉ NGFW là không đủ."}},{"id":"des_c3_12","chapter":"3","question":"Theo slide, tường lửa có thay thế được vá lỗi (patch management), EDR, IAM và sao lưu không?","options":{"A":"Có, NGFW đời mới đã bao gồm tất cả các chức năng đó","B":"Có, nếu bật giải mã TLS cho mọi luồng","C":"Không, vì tường lửa chỉ dùng cho mạng không dây","D":"Không; tường lửa chỉ là một lớp bảo vệ"},"answer":"D","family":"des_c3_12","style":"review","section":"3.1","source":"Đề cương mục 3.1-3.4; slide Bài 3 bản cập nhật","explanation":"Slide cảnh báo tường lửa chỉ là MỘT lớp bảo vệ, không thay thế patch management, EDR, IAM, backup, đào tạo người dùng.","optionNotes":{"A":"NGFW không làm thay vá lỗi, EDR, IAM hay sao lưu.","B":"Giải mã TLS chỉ giúp thấy nội dung, không thay các lớp bảo vệ khác.","C":"Tường lửa dùng cho mọi loại mạng, và câu trả lời đúng là không vì nó chỉ là một lớp."}},{"id":"gen_230","chapter":"4","question":"Sensor gửi cảnh báo cho SOC nhưng không tự chặn gói. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"IDS","B":"Firewall","C":"IDPS","D":"IPS"},"answer":"A","family":"g20c1","style":"scenario","section":"4.1-4.3","source":"Đề cương mục 4.1-4.3; slide Bài 4","explanation":"Chỉ gửi cảnh báo mà không tự chặn là IDS (hệ thống phát hiện xâm nhập).","optionNotes":{"B":"Firewall chặn hoặc cho qua theo luật, không chỉ gửi cảnh báo.","C":"IDPS gồm cả phát hiện lẫn ngăn chặn; ở đây không có chặn.","D":"IPS chủ động chặn gói, trái với tình huống."}},{"id":"gen_231","chapter":"4","question":"Khi phát hiện dấu hiệu tấn công, IDS thường làm gì?","options":{"A":"Tự động xóa tệp bị nhiễm và khởi động lại máy chủ bị tấn công","B":"Ngắt điện máy chủ bị tấn công","C":"Đổi mật khẩu của mọi người dùng","D":"Tạo cảnh báo và ghi log cho người quản trị"},"answer":"D","family":"g20c1","style":"distinction","section":"4.1-4.3","source":"Đề cương mục 4.1-4.3; slide Bài 4","explanation":"IDS phát hiện thì tạo cảnh báo và ghi log để quản trị viên xử lý; nó không tự can thiệp.","optionNotes":{"A":"Xóa tệp, khởi động lại máy là hành động chủ động mà IDS không làm.","B":"IDS không ngắt điện máy chủ.","C":"IDS không đổi mật khẩu người dùng."}},{"id":"gen_234","chapter":"4","question":"Điểm khác biệt chính của IPS so với IDS là gì?","options":{"A":"IPS chỉ ghi log và gửi cảnh báo, không bao giờ chặn lưu lượng","B":"IPS có thể chủ động chặn lưu lượng tấn công","C":"IPS chỉ dùng được cho mạng không dây","D":"IPS không cần luật hay chữ ký nào"},"answer":"B","family":"g20c2","style":"distinction","section":"4.1-4.3","source":"Đề cương mục 4.1-4.3; slide Bài 4","explanation":"IPS đặt trên đường truyền nên có thể chủ động chặn lưu lượng tấn công; IDS chỉ cảnh báo.","optionNotes":{"A":"Chỉ ghi log và cảnh báo là IDS.","C":"IPS dùng cho mọi loại mạng, có bản riêng cho không dây là WIPS.","D":"IPS cũng cần luật hoặc chữ ký để nhận ra tấn công."}},{"id":"gen_236","chapter":"4","question":"Nếu một tài liệu mô tả cả chức năng cảnh báo lẫn chặn, hiện tượng nào đang xảy ra?","options":{"A":"Firewall","B":"IDPS","C":"IPS","D":"IDS"},"answer":"B","family":"g20c3","style":"scenario","section":"4.1-4.3","source":"Đề cương mục 4.1-4.3; slide Bài 4","explanation":"Hệ thống vừa cảnh báo vừa chặn là IDPS (Intrusion Detection and Prevention System).","optionNotes":{"A":"Firewall lọc theo luật, không phải hệ phát hiện xâm nhập.","C":"IPS nhấn vào việc chặn; tên gọi bao cả hai chức năng là IDPS.","D":"IDS chỉ phát hiện, không chặn."}},{"id":"gen_237","chapter":"4","question":"Theo slide, IDPS có thể triển khai theo các mô hình nào?","options":{"A":"Personal, Enterprise và Open","B":"Packet, Circuit và Application","C":"Boot, File và Macro","D":"Standalone, Distributed và Hybrid"},"answer":"D","family":"g20c3","style":"distinction","section":"4.1-4.3","source":"Đề cương mục 4.1-4.3; slide Bài 4","explanation":"Slide nêu ba mô hình triển khai IDPS: Standalone, Distributed và Hybrid.","optionNotes":{"A":"Personal, Enterprise, Open là chế độ bảo mật Wi-Fi.","B":"Packet, Circuit, Application là các loại tường lửa.","C":"Boot, File, Macro là các loại virus."}},{"id":"gen_239","chapter":"4","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Thiết bị biên chặn cổng không được mở theo ACL?","options":{"A":"IDS","B":"IPS","C":"IDPS","D":"Firewall"},"answer":"D","family":"g20c4","style":"scenario","section":"4.1-4.3","source":"Đề cương mục 4.1-4.3; slide Bài 4","explanation":"Chặn cổng không được mở theo ACL là việc của firewall.","optionNotes":{"A":"IDS chỉ cảnh báo, không chặn theo ACL.","B":"IPS chặn theo dấu hiệu tấn công, không theo ACL mở/đóng cổng.","C":"IDPS phát hiện/ngăn tấn công theo dấu hiệu, không phải lọc cổng theo ACL."}},{"id":"gen_240","chapter":"4","question":"Vì sao đã có firewall vẫn nên triển khai thêm IDS/IPS?","options":{"A":"Firewall không có khả năng chặn bất kỳ cổng dịch vụ nào","B":"Firewall lọc theo luật, không phân tích dấu hiệu tấn công","C":"IDS/IPS thay thế hoàn toàn chức năng lọc của firewall","D":"Firewall chỉ hoạt động được trong mạng không dây"},"answer":"B","family":"g20c4","style":"distinction","section":"4.1-4.3","source":"Đề cương mục 4.1-4.3; slide Bài 4","explanation":"Firewall chỉ cho qua/chặn theo luật (IP, cổng); tấn công đi qua cổng được mở vẫn lọt, nên cần IDS/IPS phân tích dấu hiệu tấn công.","optionNotes":{"A":"Firewall chặn được cổng; đó là chức năng chính của nó.","C":"IDS/IPS bổ sung chứ không thay firewall.","D":"Firewall dùng cho mọi loại mạng."}},{"id":"gen_242","chapter":"4","question":"Xét tình huống: Thiết bị nhận bản sao gói từ cổng SPAN của switch. Cách gọi đúng là gì?","options":{"A":"HIDS","B":"NIPS","C":"NIDS","D":"WIDS"},"answer":"C","family":"g21c1","style":"scenario","section":"4.2-4.5","source":"Đề cương mục 4.2-4.5; slide Bài 4","explanation":"Thiết bị nhận bản sao gói từ cổng SPAN để phân tích lưu lượng mạng là NIDS.","optionNotes":{"A":"HIDS chạy trên máy, đọc sự kiện của máy, không nhận gói từ SPAN.","B":"NIPS phải đặt inline; nhận bản sao thì không chặn được.","D":"WIDS giám sát sóng vô tuyến, không nhận gói từ switch."}},{"id":"gen_243","chapter":"4","question":"Tầm nhìn của NIDS phụ thuộc chủ yếu vào điều gì?","options":{"A":"Số phần mềm diệt virus được cài trên từng máy trạm trong mạng","B":"Độ dài mật khẩu của người dùng","C":"Vị trí đặt sensor và lưu lượng nó quan sát được","D":"Dung lượng ổ cứng của máy chủ web"},"answer":"C","family":"g21c1","style":"distinction","section":"4.2-4.5","source":"Đề cương mục 4.2-4.5; slide Bài 4","explanation":"NIDS chỉ thấy lưu lượng đi qua chỗ đặt sensor, nên vị trí đặt quyết định tầm nhìn.","optionNotes":{"A":"Antivirus trên máy trạm không ảnh hưởng thứ NIDS nhìn thấy.","B":"Mật khẩu không liên quan tầm nhìn của sensor.","D":"Dung lượng ổ cứng máy chủ web không liên quan."}},{"id":"gen_245","chapter":"4","question":"Nếu agent phát hiện thay đổi tệp hệ thống trên server, hiện tượng nào đang xảy ra?","options":{"A":"HIDS","B":"NIDS","C":"WIDS","D":"NIPS"},"answer":"A","family":"g21c2","style":"scenario","section":"4.2-4.5","source":"Đề cương mục 4.2-4.5; slide Bài 4","explanation":"Agent cài trên server theo dõi thay đổi tệp hệ thống là HIDS.","optionNotes":{"B":"NIDS xem lưu lượng mạng, không thấy tệp trên máy.","C":"WIDS giám sát mạng không dây.","D":"NIPS chặn gói trên đường truyền, không theo dõi tệp."}},{"id":"gen_246","chapter":"4","question":"HIDS thấy được điều gì mà NIDS thường không thấy?","options":{"A":"Sự kiện trên máy như tiến trình, tệp, nhật ký hệ thống","B":"Toàn bộ lưu lượng đi giữa các switch ở lớp lõi của mạng doanh nghiệp","C":"Tín hiệu vô tuyến của AP lạ","D":"Mọi gói tin đi qua router biên"},"answer":"A","family":"g21c2","style":"distinction","section":"4.2-4.5","source":"Đề cương mục 4.2-4.5; slide Bài 4","explanation":"HIDS chạy trên máy nên thấy tiến trình, tệp, nhật ký hệ thống; NIDS chỉ thấy gói tin.","optionNotes":{"B":"Lưu lượng lớp lõi là phạm vi của NIDS.","C":"Tín hiệu vô tuyến là phạm vi của WIDS.","D":"Gói qua router biên là phạm vi của NIDS."}},{"id":"gen_248","chapter":"4","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Bộ dò phát hiện AP lạ phát cùng SSID của trường?","options":{"A":"NIDS","B":"NIPS","C":"WIDS","D":"HIDS"},"answer":"C","family":"g21c3","style":"scenario","section":"4.2-4.5","source":"Đề cương mục 4.2-4.5; slide Bài 4","explanation":"Phát hiện AP lạ phát cùng SSID (evil twin/rogue AP) là việc của WIDS.","optionNotes":{"A":"NIDS xem lưu lượng có dây, không quét sóng vô tuyến.","B":"NIPS chặn gói trên đường truyền có dây.","D":"HIDS chỉ giám sát một máy."}},{"id":"gen_249","chapter":"4","question":"WIDS giám sát loại lưu lượng nào?","options":{"A":"Nhật ký tiến trình và tệp hệ thống trên từng máy chủ","B":"Lưu lượng cáp quang giữa hai tòa nhà","C":"Truy vấn SQL vào cơ sở dữ liệu","D":"Khung và hoạt động vô tuyến của mạng không dây"},"answer":"D","family":"g21c3","style":"distinction","section":"4.2-4.5","source":"Đề cương mục 4.2-4.5; slide Bài 4","explanation":"WIDS giám sát khung và hoạt động vô tuyến của mạng không dây.","optionNotes":{"A":"Tiến trình và tệp trên máy là HIDS.","B":"Cáp quang là mạng có dây, thuộc NIDS.","C":"Truy vấn SQL là phạm vi của WAF hoặc giám sát CSDL."}},{"id":"gen_251","chapter":"4","question":"Gói tấn công bị bỏ trước khi tới máy chủ. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"NIDS","B":"NIPS","C":"WIDS","D":"HIDS"},"answer":"B","family":"g21c4","style":"scenario","section":"4.2-4.5","source":"Đề cương mục 4.2-4.5; slide Bài 4","explanation":"Bỏ gói tấn công trước khi tới máy chủ là chặn trên đường truyền mạng, tức NIPS.","optionNotes":{"A":"NIDS chỉ cảnh báo, không bỏ gói.","C":"WIDS giám sát không dây, không bỏ gói trước máy chủ.","D":"HIDS chạy trên máy chủ, chỉ thấy sau khi gói đã tới."}},{"id":"gen_252","chapter":"4","question":"Vì sao NIPS phải đặt inline trên đường truyền?","options":{"A":"Để chỉ nhận bản sao lưu lượng từ cổng SPAN mà không ảnh hưởng mạng","B":"Để lưu lượng đi qua nó và bị chặn ngay khi cần","C":"Để đọc nhật ký trên từng máy trạm","D":"Để phát sóng Wi-Fi cho người dùng"},"answer":"B","family":"g21c4","style":"distinction","section":"4.2-4.5","source":"Đề cương mục 4.2-4.5; slide Bài 4","explanation":"NIPS phải inline để lưu lượng đi xuyên qua nó; như vậy nó mới bỏ được gói tấn công ngay.","optionNotes":{"A":"Nhận bản sao từ SPAN là cách của NIDS thụ động, không chặn được.","C":"Đọc nhật ký trên máy là HIDS.","D":"NIPS không phát Wi-Fi."}},{"id":"gen_254","chapter":"4","question":"Nếu switch mirror traffic tới máy phân tích độc lập, hiện tượng nào đang xảy ra?","options":{"A":"SPAN port","B":"Sensor inline","C":"Network TAP","D":"Sensor thụ động"},"answer":"D","family":"g22c1","style":"scenario","section":"4.2-4.3","source":"Đề cương mục 4.2-4.3; slide Bài 4","explanation":"Câu hỏi nói về máy phân tích độc lập nhận bản sao lưu lượng: đó là sensor thụ động, không nằm trên đường truyền và không chặn.","optionNotes":{"A":"SPAN port là cổng trên switch làm việc sao chép; câu hỏi gọi tên máy phân tích nhận bản sao, tức sensor thụ động.","B":"Sensor inline nằm trên đường truyền, không nhận bản sao.","C":"Network TAP là đầu nối phần cứng trên đường cáp, không phải switch mirror."}},{"id":"gen_255","chapter":"4","question":"Sensor IDS thụ động (passive) có đặc điểm gì?","options":{"A":"Nằm trực tiếp trên đường truyền và tự động thả các gói bị nghi ngờ","B":"Cài trên từng máy để đọc tiến trình","C":"Chỉ hoạt động khi mất kết nối mạng","D":"Nhận bản sao lưu lượng, cảnh báo nhưng không chặn trực tiếp"},"answer":"D","family":"g22c1","style":"distinction","section":"4.2-4.3","source":"Đề cương mục 4.2-4.3; slide Bài 4","explanation":"Sensor thụ động nhận bản sao lưu lượng, phát cảnh báo nhưng không chặn trực tiếp.","optionNotes":{"A":"Nằm trên đường truyền và thả gói là sensor inline.","B":"Cài trên từng máy để đọc tiến trình là HIDS.","C":"Sensor cần lưu lượng mạng mới hoạt động."}},{"id":"gen_257","chapter":"4","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Tất cả gói tới DMZ đi qua IPS trước khi tới server?","options":{"A":"Sensor inline","B":"Sensor thụ động","C":"Network TAP","D":"SPAN port"},"answer":"A","family":"g22c2","style":"scenario","section":"4.2-4.3","source":"Đề cương mục 4.2-4.3; slide Bài 4","explanation":"Mọi gói đi qua IPS trước khi tới server nghĩa là IPS nằm trên đường truyền: sensor inline.","optionNotes":{"B":"Sensor thụ động chỉ nhận bản sao, gói không phải đi qua nó.","C":"TAP chỉ sao chép lưu lượng, không để gói đi xuyên qua một IPS.","D":"SPAN port là cổng sao chép trên switch."}},{"id":"gen_258","chapter":"4","question":"Nhược điểm của sensor inline là gì?","options":{"A":"Thiết bị lỗi có thể làm gián đoạn đường truyền","B":"Không thể chặn được gói tin nào vì chỉ nhận bản sao lưu lượng","C":"Chỉ thấy bản sao lưu lượng từ SPAN","D":"Không ghi được log cảnh báo"},"answer":"A","family":"g22c2","style":"distinction","section":"4.2-4.3","source":"Đề cương mục 4.2-4.3; slide Bài 4","explanation":"Sensor inline nằm trên đường truyền; nếu nó hỏng thì đường truyền có thể bị gián đoạn.","optionNotes":{"B":"Sensor inline chặn được gói, đó là ưu điểm của nó.","C":"Nhận bản sao từ SPAN là sensor thụ động.","D":"Sensor inline vẫn ghi log."}},{"id":"gen_260","chapter":"4","question":"Switch sao chép gói từ uplink sang một cổng IDS. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"Network TAP","B":"SPAN port","C":"Sensor thụ động","D":"Sensor inline"},"answer":"B","family":"g22c3","style":"scenario","section":"4.2-4.3","source":"Đề cương mục 4.2-4.3; slide Bài 4","explanation":"Switch sao chép gói từ uplink sang một cổng để IDS nghe là SPAN port (port mirroring).","optionNotes":{"A":"TAP là đầu nối phần cứng trên cáp, không phải chức năng của switch.","C":"Sensor thụ động là máy nhận bản sao, còn cơ chế switch sao chép gói được hỏi ở đây là SPAN.","D":"Inline là nằm trên đường truyền, không phải sao chép."}},{"id":"gen_261","chapter":"4","question":"Hạn chế của SPAN port khi lấy lưu lượng cho IDS là gì?","options":{"A":"Có thể thiếu gói khi switch quá tải","B":"Làm ngắt mạng nếu IDS bị hỏng","C":"Không sao chép được lưu lượng TCP","D":"Chỉ hoạt động với mạng Wi-Fi"},"answer":"A","family":"g22c3","style":"distinction","section":"4.2-4.3","source":"Đề cương mục 4.2-4.3; slide Bài 4","explanation":"SPAN do switch sao chép bằng tài nguyên của nó, nên khi switch quá tải có thể bỏ sót gói.","optionNotes":{"B":"SPAN chỉ gửi bản sao, IDS hỏng không làm ngắt mạng.","C":"SPAN sao chép được mọi loại gói, kể cả TCP.","D":"SPAN là chức năng của switch có dây."}},{"id":"gen_263","chapter":"4","question":"Xét tình huống: Đầu nối chuyên dụng đưa bản sao gói tới sensor. Cách gọi đúng là gì?","options":{"A":"Network TAP","B":"Sensor thụ động","C":"SPAN port","D":"Sensor inline"},"answer":"A","family":"g22c4","style":"scenario","section":"4.2-4.3","source":"Đề cương mục 4.2-4.3; slide Bài 4","explanation":"Đầu nối chuyên dụng đặt trên đường cáp để đưa bản sao gói tới sensor là Network TAP.","optionNotes":{"B":"Sensor thụ động là máy nhận bản sao, không phải đầu nối.","C":"SPAN là chức năng trên switch, không phải đầu nối riêng.","D":"Inline là nằm trên đường truyền để chặn."}},{"id":"gen_264","chapter":"4","question":"Network TAP dùng để làm gì?","options":{"A":"Chặn gói tin độc hại theo chữ ký trước khi chúng tới máy chủ đích","B":"Cấp địa chỉ IP cho máy trạm","C":"Sao chép lưu lượng trên đường truyền vật lý cho sensor","D":"Mã hóa lưu lượng giữa hai chi nhánh"},"answer":"C","family":"g22c4","style":"distinction","section":"4.2-4.3","source":"Đề cương mục 4.2-4.3; slide Bài 4","explanation":"Network TAP sao chép lưu lượng trên đường truyền vật lý để đưa cho sensor.","optionNotes":{"A":"Chặn gói theo chữ ký là việc của IPS.","B":"Cấp IP là DHCP.","D":"Mã hóa giữa chi nhánh là VPN."}},{"id":"gen_266","chapter":"4","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Luật IDS phát cảnh báo khi thấy chuỗi exploit cụ thể?","options":{"A":"Behavior analysis","B":"Anomaly detection","C":"Machine learning IDS","D":"Signature detection"},"answer":"D","family":"g23c1","style":"scenario","section":"4.4","source":"Đề cương mục 4.4; slide Bài 4","explanation":"Luật cảnh báo khi thấy một chuỗi exploit cụ thể là phát hiện theo chữ ký.","optionNotes":{"A":"Phân tích hành vi xét chuỗi hành động theo thời gian.","B":"Phát hiện bất thường so với baseline, không tìm chuỗi cụ thể.","C":"IDS máy học chấm điểm theo mô hình, không dùng luật chuỗi cố định."}},{"id":"gen_267","chapter":"4","question":"Nhược điểm của phát hiện dựa trên chữ ký (signature-based) là gì?","options":{"A":"Cần baseline nên báo động giả nhiều","B":"Dễ bỏ sót tấn công mới chưa có chữ ký","C":"Không ghi được log cảnh báo","D":"Chỉ chạy được trên mạng không dây"},"answer":"B","family":"g23c1","style":"distinction","section":"4.4","source":"Đề cương mục 4.4; slide Bài 4","explanation":"Chữ ký chỉ bắt được cái đã biết, nên dễ bỏ sót tấn công mới (zero-day) hoặc biến thể.","optionNotes":{"A":"Cần baseline và báo động giả nhiều là nhược điểm của phát hiện bất thường.","C":"IDS dùng chữ ký vẫn ghi log.","D":"Chữ ký dùng được trên mọi loại mạng."}},{"id":"gen_269","chapter":"4","question":"Lưu lượng DNS tăng đột biến so với lịch sử mạng. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"Behavior analysis","B":"Signature detection","C":"Machine learning IDS","D":"Anomaly detection"},"answer":"D","family":"g23c2","style":"scenario","section":"4.4","source":"Đề cương mục 4.4; slide Bài 4","explanation":"Lưu lượng tăng đột biến so với lịch sử là lệch khỏi baseline, tức phát hiện bất thường.","optionNotes":{"A":"Phân tích hành vi xét chuỗi hành động của một tài khoản/tiến trình, không chỉ so lượng.","B":"Không có chuỗi tấn công cụ thể nào để khớp chữ ký.","C":"Tình huống chỉ so với lịch sử, không nói tới mô hình máy học."}},{"id":"gen_270","chapter":"4","question":"Phát hiện dựa trên bất thường (anomaly-based) cần gì để hoạt động tốt?","options":{"A":"Baseline hành vi bình thường phù hợp","B":"Cơ sở dữ liệu chữ ký tấn công đầy đủ","C":"Mật khẩu quản trị đủ mạnh","D":"Card mạng hỗ trợ Wi-Fi 7"},"answer":"A","family":"g23c2","style":"distinction","section":"4.4","source":"Đề cương mục 4.4; slide Bài 4","explanation":"Phát hiện bất thường so với hành vi bình thường, nên cần một baseline phù hợp; baseline sai thì báo nhầm nhiều.","optionNotes":{"B":"Cơ sở dữ liệu chữ ký là thứ phát hiện theo chữ ký cần.","C":"Mật khẩu quản trị không quyết định chất lượng phát hiện.","D":"Chuẩn Wi-Fi không liên quan."}},{"id":"gen_272","chapter":"4","question":"Xét tình huống: Một tài khoản đăng nhập rồi quét hàng loạt host bất thường. Cách gọi đúng là gì?","options":{"A":"Anomaly detection","B":"Signature detection","C":"Behavior analysis","D":"Machine learning IDS"},"answer":"C","family":"g23c3","style":"scenario","section":"4.4","source":"Đề cương mục 4.4; slide Bài 4","explanation":"Một tài khoản đăng nhập rồi đi quét hàng loạt máy là chuỗi hành động đáng ngờ của một chủ thể: phân tích hành vi.","optionNotes":{"A":"Phát hiện bất thường so lượng/chỉ số với baseline; ở đây trọng tâm là chuỗi việc tài khoản làm.","B":"Không có chữ ký cụ thể nào được khớp.","D":"Tình huống không nói tới mô hình máy học."}},{"id":"gen_273","chapter":"4","question":"Phân tích hành vi (behavior-based) tập trung vào gì?","options":{"A":"Một mẫu byte cố định trong gói tin, so khớp với cơ sở dữ liệu chữ ký","B":"Tên miền của trang web được truy cập","C":"Chuỗi hành động của tiến trình hoặc người dùng theo thời gian","D":"Kích thước tệp đính kèm email"},"answer":"C","family":"g23c3","style":"distinction","section":"4.4","source":"Đề cương mục 4.4; slide Bài 4","explanation":"Behavior-based xét chuỗi hành động của tiến trình hoặc người dùng theo thời gian.","optionNotes":{"A":"Mẫu byte cố định so với chữ ký là signature-based.","B":"Tên miền chỉ là một thuộc tính, không phải chuỗi hành vi.","D":"Kích thước tệp đính kèm không phải hành vi."}},{"id":"gen_275","chapter":"4","question":"Nếu mô hình dùng đặc trưng flow để chấm điểm phiên đáng ngờ, hiện tượng nào đang xảy ra?","options":{"A":"Anomaly detection","B":"Signature detection","C":"Behavior analysis","D":"Machine learning IDS"},"answer":"D","family":"g23c4","style":"scenario","section":"4.4","source":"Đề cương mục 4.4; slide Bài 4","explanation":"Dùng mô hình chấm điểm phiên từ các đặc trưng flow là IDS máy học.","optionNotes":{"A":"Phát hiện bất thường so với baseline, không cần mô hình chấm điểm.","B":"Chữ ký khớp mẫu cố định.","C":"Phân tích hành vi theo dõi chuỗi hành động, không nói tới mô hình."}},{"id":"gen_276","chapter":"4","question":"Theo slide, hạn chế của IDS dùng máy học là gì?","options":{"A":"Không cần dữ liệu huấn luyện, mô hình tự nhận ra mọi kiểu tấn công","B":"Luôn chính xác 100% với tấn công mới","C":"Phụ thuộc dữ liệu huấn luyện và có thể bị tấn công adversarial","D":"Chỉ phát hiện được virus boot"},"answer":"C","family":"g23c4","style":"distinction","section":"4.4","source":"Đề cương mục 4.4; slide Bài 4","explanation":"Slide nêu IDS máy học phụ thuộc dữ liệu huấn luyện và có thể bị tấn công adversarial (đánh lừa mô hình).","optionNotes":{"A":"Máy học cần dữ liệu huấn luyện.","B":"Không mô hình nào chính xác 100%.","D":"Virus boot không liên quan IDS máy học."}},{"id":"gen_278","chapter":"4","question":"Một mẫu exploit được IDS báo và điều tra xác nhận. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"False positive","B":"True negative","C":"True positive","D":"False negative"},"answer":"C","family":"g24c1","style":"scenario","section":"4.4","source":"Đề cương mục 4.4; slide Bài 4","explanation":"Có tấn công thật (đã xác nhận) và IDS báo: true positive.","optionNotes":{"A":"False positive là báo nhầm khi không có tấn công.","B":"True negative là không tấn công và không báo.","D":"False negative là có tấn công nhưng không báo."}},{"id":"gen_279","chapter":"4","question":"True positive (TP) trong đánh giá IDS là trường hợp nào?","options":{"A":"Không có tấn công nhưng IDS cảnh báo","B":"Có tấn công thật nhưng IDS bỏ sót","C":"Không có tấn công và IDS không cảnh báo","D":"Có tấn công thật và IDS cảnh báo"},"answer":"D","family":"g24c1","style":"distinction","section":"4.4","source":"Đề cương mục 4.4; slide Bài 4","explanation":"TP: có tấn công thật và IDS cảnh báo đúng.","optionNotes":{"A":"Không có tấn công mà cảnh báo là FP.","B":"Có tấn công mà bỏ sót là FN.","C":"Không tấn công và không cảnh báo là TN."}},{"id":"gen_282","chapter":"4","question":"Hậu quả chính khi IPS có nhiều false positive là gì?","options":{"A":"Chặn nhầm lưu lượng hợp lệ, gián đoạn nghiệp vụ","B":"Bỏ sót nhiều cuộc tấn công thật vì sensor không thấy lưu lượng","C":"Làm lộ khóa mã hóa của WLAN","D":"Xóa toàn bộ log trên máy chủ"},"answer":"A","family":"g24c2","style":"distinction","section":"4.4","source":"Đề cương mục 4.4; slide Bài 4","explanation":"IPS chặn theo cảnh báo của nó; báo nhầm nhiều thì chặn nhầm lưu lượng hợp lệ, gây gián đoạn nghiệp vụ.","optionNotes":{"B":"Bỏ sót tấn công là false negative.","C":"FP không làm lộ khóa WLAN.","D":"FP không xóa log."}},{"id":"gen_285","chapter":"4","question":"Vì sao false negative nguy hiểm?","options":{"A":"Người quản trị nhận quá nhiều cảnh báo giả","B":"Lưu lượng hợp lệ bị chặn nhầm","C":"Tạo cảm giác an toàn trong khi tấn công vẫn diễn ra","D":"Sensor tự khởi động lại liên tục"},"answer":"C","family":"g24c3","style":"distinction","section":"4.4","source":"Đề cương mục 4.4; slide Bài 4","explanation":"False negative là có tấn công mà không cảnh báo, nên mọi người tưởng an toàn trong khi tấn công vẫn diễn ra.","optionNotes":{"A":"Nhiều cảnh báo giả là false positive.","B":"Chặn nhầm lưu lượng hợp lệ là false positive của IPS.","D":"FN không làm sensor khởi động lại."}},{"id":"gen_287","chapter":"4","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Lưu lượng hợp lệ đi qua mà không bị cảnh báo?","options":{"A":"True negative","B":"False negative","C":"True positive","D":"False positive"},"answer":"A","family":"g24c4","style":"scenario","section":"4.4","source":"Đề cương mục 4.4; slide Bài 4","explanation":"Lưu lượng hợp lệ (không tấn công) và không bị cảnh báo: true negative.","optionNotes":{"B":"False negative là có tấn công mà không báo.","C":"True positive là có tấn công và báo.","D":"False positive là không tấn công mà báo."}},{"id":"gen_288","chapter":"4","question":"True negative (TN) trong đánh giá IDS là trường hợp nào?","options":{"A":"Có tấn công thật và IDS cảnh báo","B":"Không có tấn công nhưng IDS cảnh báo","C":"Không có tấn công và IDS không cảnh báo","D":"Có tấn công thật nhưng IDS bỏ sót"},"answer":"C","family":"g24c4","style":"distinction","section":"4.4","source":"Đề cương mục 4.4; slide Bài 4","explanation":"TN: không có tấn công và IDS không cảnh báo.","optionNotes":{"A":"Có tấn công và cảnh báo là TP.","B":"Không tấn công mà cảnh báo là FP.","D":"Có tấn công mà bỏ sót là FN."}},{"id":"gen_290","chapter":"4","question":"Xét tình huống: SOC giảm số báo động giả trong tổng số alert. Cách gọi đúng là gì?","options":{"A":"Precision","B":"Recall","C":"Baseline","D":"Tuning"},"answer":"A","family":"g25c1","style":"scenario","section":"4.4-4.5","source":"Đề cương mục 4.4-4.5; slide Bài 4","explanation":"Precision = TP/(TP+FP) đo tỷ lệ cảnh báo đúng trong tổng số cảnh báo; giảm báo động giả là tăng precision.","optionNotes":{"B":"Recall đo tỷ lệ tấn công được phát hiện, không phải tỷ lệ báo giả.","C":"Baseline là mức bình thường dùng để so sánh.","D":"Tuning là cách tinh chỉnh luật; chỉ số được hỏi ở đây là precision."}},{"id":"gen_291","chapter":"4","question":"Theo slide, công thức Precision là gì?","options":{"A":"TP / (TP + FN)","B":"TN / (TN + FP)","C":"TP / (TP + FP)","D":"(TP + TN) / tổng số mẫu"},"answer":"C","family":"g25c1","style":"distinction","section":"4.4-4.5","source":"Đề cương mục 4.4-4.5; slide Bài 4","explanation":"Precision = TP / (TP + FP): trong các cảnh báo, bao nhiêu phần là đúng.","optionNotes":{"A":"TP/(TP+FN) là recall.","B":"TN/(TN+FP) là độ đặc hiệu (specificity).","D":"(TP+TN)/tổng là độ chính xác chung (accuracy)."}},{"id":"gen_293","chapter":"4","question":"Nếu sensor bỏ sót ít hơn các đợt tấn công thử nghiệm, hiện tượng nào đang xảy ra?","options":{"A":"Baseline","B":"Recall","C":"Precision","D":"Tuning"},"answer":"B","family":"g25c2","style":"scenario","section":"4.4-4.5","source":"Đề cương mục 4.4-4.5; slide Bài 4","explanation":"Bỏ sót ít hơn nghĩa là phát hiện được nhiều tấn công thật hơn, tức recall tăng.","optionNotes":{"A":"Baseline là mức bình thường để so sánh.","C":"Precision liên quan báo động giả, không phải bỏ sót.","D":"Tuning là tinh chỉnh luật, không phải chỉ số đo."}},{"id":"gen_294","chapter":"4","question":"Theo slide, công thức Recall là gì?","options":{"A":"TP / (TP + FP)","B":"FP / (FP + TN)","C":"TP / (TP + FN)","D":"TN / (TN + FN)"},"answer":"C","family":"g25c2","style":"distinction","section":"4.4-4.5","source":"Đề cương mục 4.4-4.5; slide Bài 4","explanation":"Recall = TP / (TP + FN): trong các tấn công thật, bao nhiêu phần được phát hiện.","optionNotes":{"A":"TP/(TP+FP) là precision.","B":"FP/(FP+TN) là tỷ lệ báo động giả (FPR).","D":"TN/(TN+FN) không phải recall."}},{"id":"gen_296","chapter":"4","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Luật báo nhầm tác vụ backup được giới hạn theo lịch?","options":{"A":"Precision","B":"Recall","C":"Baseline","D":"Tuning"},"answer":"D","family":"g25c3","style":"scenario","section":"4.4-4.5","source":"Đề cương mục 4.4-4.5; slide Bài 4","explanation":"Chỉnh luật đang báo nhầm (giới hạn theo lịch backup) là tuning.","optionNotes":{"A":"Precision là chỉ số đo, không phải hành động chỉnh luật.","B":"Recall là chỉ số đo.","C":"Baseline là mức bình thường, không phải việc chỉnh luật."}},{"id":"gen_299","chapter":"4","question":"Nhóm xác định mức DNS trung bình theo ngày làm việc. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"Baseline","B":"Recall","C":"Tuning","D":"Precision"},"answer":"A","family":"g25c4","style":"scenario","section":"4.4-4.5","source":"Đề cương mục 4.4-4.5; slide Bài 4","explanation":"Xác định mức DNS trung bình ngày làm việc là xây baseline (mức bình thường).","optionNotes":{"B":"Recall là chỉ số đo tỷ lệ phát hiện.","C":"Tuning là chỉnh luật, còn đây là đo mức bình thường.","D":"Precision là chỉ số đo cảnh báo đúng."}},{"id":"gen_302","chapter":"4","question":"Nếu chi nhánh nhỏ vận hành một bộ ids riêng, hiện tượng nào đang xảy ra?","options":{"A":"Standalone IDPS","B":"Distributed IDPS","C":"SIEM","D":"Hybrid IDPS"},"answer":"A","family":"g26c1","style":"scenario","section":"4.5","source":"Đề cương mục 4.5; slide Bài 4","explanation":"Một bộ IDS riêng, tự vận hành ở chi nhánh nhỏ là mô hình standalone.","optionNotes":{"B":"Distributed có nhiều sensor gửi về bộ điều khiển chung.","C":"SIEM là hệ thống tương quan log, không phải mô hình IDPS.","D":"Hybrid kết hợp nhiều loại sensor (như HIDS + NIDS)."}},{"id":"gen_308","chapter":"4","question":"HIDS máy chủ cùng NIDS biên gửi log về trung tâm. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"Standalone IDPS","B":"SIEM","C":"Hybrid IDPS","D":"Distributed IDPS"},"answer":"C","family":"g26c3","style":"scenario","section":"4.5","source":"Đề cương mục 4.5; slide Bài 4","explanation":"Kết hợp HIDS (trên máy) với NIDS (mạng) và gửi về trung tâm là hybrid IDPS.","optionNotes":{"A":"Standalone là một bộ IDS riêng lẻ.","B":"SIEM tương quan log, không phải mô hình triển khai IDPS.","D":"Distributed nói về nhiều sensor phân tán; điểm nhấn ở đây là kết hợp hai loại HIDS và NIDS."}},{"id":"gen_317","chapter":"4","question":"Thiết bị inline hỏng và luồng bị ngắt theo chính sách. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"Fail-open","B":"Prevention mode","C":"Fail-close","D":"Detection mode"},"answer":"C","family":"g27c2","style":"scenario","section":"4.1-4.5","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"Thiết bị inline hỏng thì ngắt luồng để không cho gì đi qua mà không kiểm tra: fail-close.","optionNotes":{"A":"Fail-open là hỏng thì vẫn cho lưu lượng đi qua.","B":"Prevention mode là chế độ chặn khi đang hoạt động bình thường.","D":"Detection mode là chỉ quan sát, không chặn."}},{"id":"gen_320","chapter":"4","question":"Xét tình huống: Luật mới chạy quan sát trước khi bật chặn. Cách gọi đúng là gì?","options":{"A":"Prevention mode","B":"Fail-close","C":"Fail-open","D":"Detection mode"},"answer":"D","family":"g27c3","style":"scenario","section":"4.1-4.5","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"Chạy luật mới chỉ quan sát, chưa chặn là detection mode.","optionNotes":{"A":"Prevention mode là chặn thật.","B":"Fail-close là cách xử lý khi thiết bị hỏng.","C":"Fail-open là cách xử lý khi thiết bị hỏng."}},{"id":"gen_323","chapter":"4","question":"Nếu luật đã kiểm thử chuyển sang drop gói tấn công, hiện tượng nào đang xảy ra?","options":{"A":"Detection mode","B":"Fail-close","C":"Prevention mode","D":"Fail-open"},"answer":"C","family":"g27c4","style":"scenario","section":"4.1-4.5","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"Chuyển luật sang drop gói tấn công là bật prevention mode.","optionNotes":{"A":"Detection mode chỉ quan sát.","B":"Fail-close là hành vi khi thiết bị hỏng.","D":"Fail-open là hành vi khi thiết bị hỏng."}},{"id":"case_31","chapter":"4","question":"Đơn vị mới triển khai luật phát hiện và muốn quan sát báo động giả trước khi bật chặn. Cấu hình nào phù hợp?","options":{"A":"IDS hoặc chế độ detection","B":"Fail-close trên toàn bộ mạng","C":"IPS chặn mọi gói khớp ngay","D":"Tắt sensor để tránh cảnh báo"},"answer":"A","family":"case_31","style":"application","section":"4.1-4.3","source":"Đề cương mục 4.1-4.3; slide Bài 4","explanation":"Muốn quan sát báo động giả trước khi chặn thì chạy IDS hoặc chế độ detection.","optionNotes":{"B":"Fail-close là cách xử lý khi thiết bị hỏng, không phải giai đoạn quan sát.","C":"Chặn ngay thì chưa kịp đánh giá báo nhầm và dễ chặn nhầm.","D":"Tắt sensor thì không quan sát được gì."}},{"id":"case_32","chapter":"4","question":"Sensor nằm inline và bỏ gói tấn công trước khi đến server. Chức năng này thuộc loại nào?","options":{"A":"IDS thụ động","B":"SPAN port sao chép gói","C":"SIEM chỉ tương quan log","D":"IPS"},"answer":"D","family":"g20c2","style":"application","section":"4.1-4.3","source":"Đề cương mục 4.1-4.3; slide Bài 4","explanation":"Nằm inline và bỏ gói tấn công trước khi tới server là IPS.","optionNotes":{"A":"IDS thụ động không chặn.","B":"SPAN chỉ sao chép gói.","C":"SIEM chỉ tương quan log."}},{"id":"case_33","chapter":"4","question":"Sensor mạng không thấy một tệp hệ thống trên server bị sửa trái phép. Loại sensor nào bổ sung đúng góc nhìn này?","options":{"A":"Router chỉ làm NAT","B":"HIDS trên server","C":"AP phát cùng SSID","D":"NIDS ở một cổng SPAN khác"},"answer":"B","family":"case_33","style":"application","section":"4.2-4.5","source":"Đề cương mục 4.2-4.5; slide Bài 4","explanation":"Thay đổi tệp hệ thống trên server chỉ thấy được từ trong máy, nên cần HIDS trên server.","optionNotes":{"A":"Router làm NAT không thấy tệp trên server.","C":"AP không liên quan.","D":"NIDS ở cổng nào cũng chỉ thấy gói tin, không thấy tệp."}},{"id":"case_34","chapter":"4","question":"IDS nhận diện mẫu exploit đã biết nhưng bỏ sót biến thể không khớp chữ ký. Phương pháp đang dùng là gì?","options":{"A":"Phân tích nguyên nhân gốc","B":"Phát hiện bất thường theo baseline","C":"Phát hiện theo chữ ký","D":"Đánh giá hành vi người dùng lâu dài"},"answer":"C","family":"case_34","style":"application","section":"4.4","source":"Đề cương mục 4.4; slide Bài 4","explanation":"Bắt được mẫu đã biết nhưng bỏ sót biến thể không khớp: đó là phát hiện theo chữ ký.","optionNotes":{"A":"Phân tích nguyên nhân gốc là việc sau sự cố.","B":"Baseline có thể bắt biến thể mới vì không phụ thuộc mẫu.","D":"Đánh giá hành vi không dựa vào chữ ký."}},{"id":"case_35","chapter":"4","question":"IPS chặn nhầm tác vụ sao lưu hợp lệ vì tưởng là tấn công. Trường hợp này là gì?","options":{"A":"True negative","B":"True positive","C":"False positive","D":"False negative"},"answer":"C","family":"g24c2","style":"application","section":"4.4","source":"Đề cương mục 4.4; slide Bài 4","explanation":"Tác vụ hợp lệ bị coi là tấn công: false positive.","optionNotes":{"A":"True negative là hợp lệ và không báo.","B":"True positive là tấn công thật và báo.","D":"False negative là tấn công thật mà không báo."}},{"id":"case_36","chapter":"4","question":"Một cuộc tấn công thật đi qua sensor nhưng không có cảnh báo. Trường hợp này là gì?","options":{"A":"True negative","B":"True positive","C":"False positive","D":"False negative"},"answer":"D","family":"g24c3","style":"application","section":"4.4","source":"Đề cương mục 4.4; slide Bài 4","explanation":"Tấn công thật mà không có cảnh báo: false negative.","optionNotes":{"A":"True negative là không có tấn công.","B":"True positive phải có cảnh báo.","C":"False positive là cảnh báo khi không có tấn công."}},{"id":"case_37","chapter":"4","question":"Trong thử nghiệm có TP=30, FP=10. Precision của hệ phát hiện là bao nhiêu?","options":{"A":"30%","B":"90%","C":"25%","D":"75%"},"answer":"D","family":"case_37","style":"application","section":"4.4-4.5","source":"Đề cương mục 4.4-4.5; slide Bài 4","explanation":"Precision = TP/(TP+FP) = 30/(30+10) = 30/40 = 75%.","optionNotes":{"A":"30% lấy nhầm TP làm phần trăm.","B":"90% không khớp công thức nào với số liệu này.","C":"25% là FP/(TP+FP), tức tỷ lệ cảnh báo sai."}},{"id":"case_38","chapter":"4","question":"Trong thử nghiệm có TP=30, FN=20. Recall của hệ phát hiện là bao nhiêu?","options":{"A":"60%","B":"50%","C":"40%","D":"80%"},"answer":"A","family":"case_38","style":"application","section":"4.4-4.5","source":"Đề cương mục 4.4-4.5; slide Bài 4","explanation":"Recall = TP/(TP+FN) = 30/(30+20) = 30/50 = 60%.","optionNotes":{"B":"50% không khớp công thức recall.","C":"40% là FN/(TP+FN), tức tỷ lệ bỏ sót.","D":"80% không khớp công thức recall."}},{"id":"case_39","chapter":"4","question":"IPS inline hỏng; tổ chức ưu tiên giữ dịch vụ hoạt động dù tạm mất chức năng chặn. Chế độ dự phòng nào phù hợp?","options":{"A":"Default deny","B":"Quarantine toàn bộ máy","C":"Fail-close","D":"Fail-open"},"answer":"D","family":"g27c1","style":"application","section":"4.1-4.5","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"Ưu tiên giữ dịch vụ khi IPS hỏng thì để lưu lượng tiếp tục đi qua: fail-open.","optionNotes":{"A":"Default deny là luật tường lửa, không phải chế độ khi thiết bị hỏng.","B":"Cách ly mọi máy làm dừng dịch vụ.","C":"Fail-close ngắt luồng, trái với ưu tiên giữ dịch vụ."}},{"id":"case_40","chapter":"4","question":"Nhiều sensor ở các cơ sở gửi log về một nơi để tương quan với log firewall và xác thực. Công cụ nào làm nhiệm vụ tương quan tập trung?","options":{"A":"BSSID","B":"SIEM","C":"WEP","D":"NAT"},"answer":"B","family":"g26c4","style":"application","section":"4.5","source":"Đề cương mục 4.5; slide Bài 4","explanation":"Gom log từ nhiều nguồn về một nơi để tương quan là SIEM.","optionNotes":{"A":"BSSID là địa chỉ MAC của AP.","C":"WEP là chuẩn bảo mật Wi-Fi cũ.","D":"NAT là dịch địa chỉ."}},{"id":"reviewed_atm_27","chapter":"4","question":"Bộ giám sát nào có thể chặn gói tấn công ngay khi lưu lượng đi qua?","options":{"A":"SIEM lưu log","B":"SPAN port","C":"IDS thụ động","D":"IPS inline"},"answer":"D","family":"source_27","style":"review","section":"4.3","source":"https://pttp-huitquiz.site/","explanation":"IPS inline nằm trên đường truyền nên chặn được gói tấn công ngay.","optionNotes":{"A":"SIEM chỉ lưu và tương quan log.","B":"SPAN chỉ sao chép gói.","C":"IDS thụ động chỉ cảnh báo."}},{"id":"reviewed_atm_89","chapter":"4","question":"Muốn phát hiện xâm nhập mà chưa tự động chặn để đánh giá báo động giả, nên dùng chế độ nào?","options":{"A":"Fail-close","B":"Default deny","C":"IDS/detection","D":"IPS/prevention"},"answer":"C","family":"source_89","style":"review","section":"4.1","source":"https://pttp-huitquiz.site/","explanation":"Phát hiện mà chưa chặn để đánh giá báo động giả: dùng IDS/detection mode.","optionNotes":{"A":"Fail-close là cách xử lý khi thiết bị hỏng.","B":"Default deny là luật tường lửa.","D":"Prevention là chặn thật, trái với yêu cầu."}},{"id":"reviewed_atm_106","chapter":"4","question":"Nhiều sensor IDS ở các cơ sở cần chung bộ điều khiển. Mô hình nào phù hợp?","options":{"A":"Một host đơn lẻ","B":"Distributed IDPS","C":"Standalone IDPS","D":"Một AP không dây"},"answer":"B","family":"source_106","style":"review","section":"4.5","source":"https://pttp-huitquiz.site/","explanation":"Nhiều sensor ở nhiều cơ sở cùng một bộ điều khiển là distributed IDPS.","optionNotes":{"A":"Một host đơn lẻ không quản lý nhiều cơ sở.","C":"Standalone là một bộ riêng lẻ.","D":"AP không phải mô hình IDS."}},{"id":"reviewed_atm_141","chapter":"4","question":"IDS báo sự kiện nhưng không được đặt trên đường truyền để bỏ gói. Chức năng cốt lõi là gì?","options":{"A":"Mã hóa mọi phiên","B":"Cấp địa chỉ IP","C":"Phát hiện và cảnh báo","D":"Chặn mọi lưu lượng"},"answer":"C","family":"source_141","style":"review","section":"4.2","source":"https://pttp-huitquiz.site/","explanation":"IDS không nằm trên đường truyền nên chức năng cốt lõi là phát hiện và cảnh báo.","optionNotes":{"A":"IDS không mã hóa phiên.","B":"Cấp IP là DHCP.","D":"IDS không chặn lưu lượng."}},{"id":"abbr_c4_036","chapter":"4","question":"IDS là viết tắt của:","options":{"A":"Intrusion Detection System","B":"Intrusion Deterrence Software","C":"Integrated Data Security","D":"Internet Defense Service"},"answer":"A","family":"ab_ids","style":"acronym","section":"4.2","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"IDS là Intrusion Detection System, hệ thống phát hiện xâm nhập.","optionNotes":{"B":"D là Detection, không phải Deterrence.","C":"Không phải Integrated Data Security.","D":"Không phải Internet Defense Service."}},{"id":"abbr_c4_037","chapter":"4","question":"IPS là viết tắt của:","options":{"A":"Integrated Policy Server","B":"Internet Protection Service","C":"Intrusion Prediction Software","D":"Intrusion Prevention System"},"answer":"D","family":"ab_ids","style":"acronym","section":"4.3","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"IPS là Intrusion Prevention System, hệ thống ngăn chặn xâm nhập.","optionNotes":{"A":"Không phải Integrated Policy Server.","B":"Không phải Internet Protection Service.","C":"P là Prevention (ngăn chặn), không phải Prediction (dự đoán)."}},{"id":"abbr_c4_038","chapter":"4","question":"IDPS là viết tắt của:","options":{"A":"Intrusion Detection and Prevention System","B":"Intrusion Data Processing Server","C":"Integrated Detection and Policy System","D":"Internet Defense and Protection Service"},"answer":"A","family":"abbr_c4_038","style":"acronym","section":"4.1","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"IDPS là Intrusion Detection and Prevention System.","optionNotes":{"B":"Không phải Intrusion Data Processing Server.","C":"Không phải Integrated Detection and Policy System.","D":"Không phải Internet Defense and Protection Service."}},{"id":"abbr_c4_039","chapter":"4","question":"Chữ N trong NIDS và chữ H trong HIDS lần lượt là:","options":{"A":"New-generation và Host-based","B":"Network-based và Host-based","C":"Network-based và Hardware-based","D":"Node-based và Hybrid-based"},"answer":"B","family":"ab_nids","style":"acronym","section":"4.2","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"N là Network-based (đặt trên mạng), H là Host-based (đặt trên máy).","optionNotes":{"A":"N không phải New-generation.","C":"H không phải Hardware-based.","D":"N không phải Node-based, H không phải Hybrid-based."}},{"id":"abbr_c4_040","chapter":"4","question":"HIPS là:","options":{"A":"High-speed Intrusion Protection Switch","B":"Hybrid Intrusion Prevention Sensor","C":"Host-based Intrusion Prevention System","D":"Host Integrity Policy Service"},"answer":"C","family":"ab_nids","style":"acronym","section":"4.3","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"HIPS là Host-based Intrusion Prevention System, IPS chạy trên máy.","optionNotes":{"A":"Không phải High-speed Intrusion Protection Switch.","B":"H là Host-based, không phải Hybrid.","D":"Không phải Host Integrity Policy Service."}},{"id":"abbr_c4_041","chapter":"4","question":"WIDS/WIPS là hệ thống IDS/IPS dành cho:","options":{"A":"Mạng không dây (Wireless)","B":"Máy trạm Windows","C":"Mạng diện rộng giữa các chi nhánh (WAN)","D":"Ứng dụng web (Web)"},"answer":"A","family":"abbr_c4_041","style":"acronym","section":"4.5","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"W trong WIDS/WIPS là Wireless, dành cho mạng không dây.","optionNotes":{"B":"W không phải Windows.","C":"W không phải WAN.","D":"W không phải Web."}},{"id":"abbr_c4_042","chapter":"4","question":"NBA trong phân loại IDPS là:","options":{"A":"Network Baseline Alert","B":"Network Backup Archive","C":"Network Behavior Analysis","D":"Node Blocking Agent"},"answer":"C","family":"abbr_c4_042","style":"acronym","section":"4.2","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"NBA là Network Behavior Analysis, phân tích hành vi mạng.","optionNotes":{"A":"Không phải Network Baseline Alert.","B":"Không phải Network Backup Archive.","D":"Không phải Node Blocking Agent."}},{"id":"abbr_c4_043","chapter":"4","question":"SIEM là viết tắt của:","options":{"A":"Secure Internet Exchange Monitor","B":"Security Information and Event Management","C":"Security Incident and Exposure Matrix","D":"System Integrity and Encryption Module"},"answer":"B","family":"ab_siem","style":"acronym","section":"4.5","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"SIEM là Security Information and Event Management, quản lý thông tin và sự kiện an ninh.","optionNotes":{"A":"Không phải Secure Internet Exchange Monitor.","C":"Không phải Security Incident and Exposure Matrix.","D":"Không phải System Integrity and Encryption Module."}},{"id":"abbr_c4_044","chapter":"4","question":"SOAR là viết tắt của:","options":{"A":"Signature Optimization and Alert Reduction","B":"Secure Online Access and Routing","C":"System Operation, Audit and Recovery","D":"Security Orchestration, Automation and Response"},"answer":"D","family":"ab_siem","style":"acronym","section":"4.5","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"SOAR là Security Orchestration, Automation and Response: điều phối, tự động hóa và phản ứng.","optionNotes":{"A":"Không phải Signature Optimization and Alert Reduction.","B":"Không phải Secure Online Access and Routing.","C":"Không phải System Operation, Audit and Recovery."}},{"id":"abbr_c4_045","chapter":"4","question":"SOC là viết tắt của:","options":{"A":"System Optimization Console","B":"Security Operations Center","C":"Security Ownership Certificate","D":"Secure Online Channel"},"answer":"B","family":"abbr_c4_045","style":"acronym","section":"4.5","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"SOC là Security Operations Center, trung tâm điều hành an ninh.","optionNotes":{"A":"Không phải System Optimization Console.","C":"Không phải Security Ownership Certificate.","D":"Không phải Secure Online Channel."}},{"id":"abbr_c4_046","chapter":"4","question":"EDR là viết tắt của:","options":{"A":"Endpoint Detection and Response","B":"Event Data Repository","C":"Encrypted Data Recovery","D":"Edge Defense Router"},"answer":"A","family":"ab_edr","style":"acronym","section":"4.5","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"EDR là Endpoint Detection and Response, phát hiện và phản ứng trên thiết bị đầu cuối.","optionNotes":{"B":"Không phải Event Data Repository.","C":"Không phải Encrypted Data Recovery.","D":"Không phải Edge Defense Router."}},{"id":"abbr_c4_047","chapter":"4","question":"XDR là viết tắt của:","options":{"A":"Extra Defense Rule","B":"External Data Replication and Recovery","C":"Extended Detection and Response","D":"Cross-Domain Routing"},"answer":"C","family":"ab_edr","style":"acronym","section":"4.5","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"XDR là Extended Detection and Response, mở rộng EDR ra nhiều nguồn.","optionNotes":{"A":"Không phải Extra Defense Rule.","B":"Không phải External Data Replication and Recovery.","D":"Không phải Cross-Domain Routing."}},{"id":"abbr_c4_048","chapter":"4","question":"NDR là viết tắt của:","options":{"A":"Network Domain Registry","B":"Network Defense Router","C":"Node Data Replication","D":"Network Detection and Response"},"answer":"D","family":"abbr_c4_048","style":"acronym","section":"4.2","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"NDR là Network Detection and Response, phát hiện và phản ứng trên lưu lượng mạng.","optionNotes":{"A":"Không phải Network Domain Registry.","B":"Không phải Network Defense Router.","C":"Không phải Node Data Replication."}},{"id":"abbr_c4_049","chapter":"4","question":"IOC trong threat intelligence là:","options":{"A":"Intrusion Origin Code","B":"Integrity of Content","C":"Indicator of Compromise","D":"Index of Connections"},"answer":"C","family":"abbr_c4_049","style":"acronym","section":"4.5","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"IOC là Indicator of Compromise, chỉ dấu cho thấy hệ thống đã bị xâm nhập (IP, tên miền, băm tệp độc...).","optionNotes":{"A":"Không phải Intrusion Origin Code.","B":"Không phải Integrity of Content.","D":"Không phải Index of Connections."}},{"id":"abbr_c4_050","chapter":"4","question":"SPAN dùng để sao chép lưu lượng cho NIDS thụ động là:","options":{"A":"Signal Path Amplifier Network","B":"Switched Port Analyzer","C":"Sensor Port Allocation","D":"Secure Packet Access Node"},"answer":"B","family":"abbr_c4_050","style":"acronym","section":"4.2","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"SPAN là Switched Port Analyzer, chức năng sao chép lưu lượng của switch sang một cổng.","optionNotes":{"A":"Không phải Signal Path Amplifier Network.","C":"Không phải Sensor Port Allocation.","D":"Không phải Secure Packet Access Node."}},{"id":"abbr_c4_051","chapter":"4","question":"FP (False Positive) trong đánh giá IDS là:","options":{"A":"Lưu lượng bình thường bị cảnh báo là tấn công","B":"Tấn công thật nhưng không được cảnh báo","C":"Tấn công thật và được cảnh báo đúng","D":"Lưu lượng bình thường hoàn toàn không bị cảnh báo"},"answer":"A","family":"ab_fp","style":"acronym","section":"4.2","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"FP: lưu lượng bình thường nhưng bị cảnh báo là tấn công (báo nhầm).","optionNotes":{"B":"Tấn công thật mà không cảnh báo là FN.","C":"Tấn công thật và cảnh báo đúng là TP.","D":"Bình thường và không cảnh báo là TN."}},{"id":"abbr_c4_052","chapter":"4","question":"FN (False Negative) trong đánh giá IDS là:","options":{"A":"Tấn công thật và được cảnh báo đúng","B":"Lưu lượng bình thường bị cảnh báo là tấn công","C":"Lưu lượng bình thường không bị cảnh báo","D":"Tấn công thật nhưng không được cảnh báo"},"answer":"D","family":"ab_fp","style":"acronym","section":"4.2","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"FN: có tấn công thật nhưng không được cảnh báo (bỏ sót).","optionNotes":{"A":"Tấn công thật và cảnh báo đúng là TP.","B":"Bình thường bị cảnh báo là FP.","C":"Bình thường không cảnh báo là TN."}},{"id":"rev_c4_055","chapter":"4","question":"Theo slide, điểm khác của XDR so với EDR là:","options":{"A":"Chỉ đặt inline để chặn gói tin","B":"Tương quan endpoint, mạng, cloud, danh tính","C":"Chỉ giám sát log trên một máy chủ","D":"Chỉ phát hiện rogue AP trong mạng Wi-Fi của trường"},"answer":"B","family":"ab_edr","style":"review","section":"4.5","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"EDR chỉ xét endpoint; XDR tương quan dữ liệu từ endpoint, mạng, cloud và danh tính.","optionNotes":{"A":"XDR không phải thiết bị inline chặn gói.","C":"Chỉ một máy chủ là phạm vi hẹp hơn cả EDR.","D":"Phát hiện rogue AP là WIDS."}},{"id":"rev_c4_056","chapter":"4","question":"MITRE ATT&CK được dùng trong IDPS để:","options":{"A":"Mã hóa kênh giữa sensor và console","B":"Cấp chứng nhận cho sản phẩm IDS","C":"Ánh xạ cảnh báo vào kỹ thuật tấn công","D":"Phân giải địa chỉ IP sang MAC"},"answer":"C","family":"rev_c4_056","style":"review","section":"4.4","source":"Đề cương mục 4.1-4.5; slide Bài 4","explanation":"MITRE ATT&CK là danh mục kỹ thuật tấn công; IDPS dùng để ánh xạ cảnh báo vào kỹ thuật tương ứng.","optionNotes":{"A":"ATT&CK không phải giao thức mã hóa.","B":"ATT&CK không cấp chứng nhận sản phẩm.","D":"Phân giải IP sang MAC là ARP."}},{"id":"gen_326","chapter":"5","question":"Sinh viên chọn tên Wi-Fi của trường trong danh sách mạng. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"BSSID","B":"Access Point","C":"Station","D":"SSID"},"answer":"D","family":"g28c1","style":"scenario","section":"5.1","source":"Đề cương mục 5.1; slide Bài 5","explanation":"Tên Wi-Fi hiện trong danh sách mạng là SSID, tên logic của WLAN.","optionNotes":{"A":"BSSID là địa chỉ MAC của từng AP/radio, không phải tên mạng người dùng chọn.","B":"Access Point là thiết bị phát sóng, không phải tên mạng.","C":"Station là thiết bị của người dùng (laptop, điện thoại)."}},{"id":"gen_327","chapter":"5","question":"Vì sao thấy đúng SSID của trường vẫn chưa chắc AP đó là thật?","options":{"A":"Vì SSID luôn được mã hóa bằng WPA3 nên không ai đọc được tên mạng","B":"Vì mỗi SSID chỉ dùng được một lần","C":"Vì SSID chứa sẵn mật khẩu của mạng","D":"Kẻ tấn công có thể dựng AP giả phát cùng tên mạng"},"answer":"D","family":"g28c1","style":"distinction","section":"5.1","source":"Đề cương mục 5.1; slide Bài 5","explanation":"SSID chỉ là một cái tên ai cũng đặt được, nên kẻ tấn công có thể dựng AP giả cùng tên (Evil Twin).","optionNotes":{"A":"SSID được phát công khai trong beacon, không được mã hóa.","B":"Một SSID dùng được cho nhiều AP và nhiều lần.","C":"SSID không chứa mật khẩu."}},{"id":"gen_330","chapter":"5","question":"BSSID dùng để phân biệt gì?","options":{"A":"Từng người dùng đăng nhập qua máy chủ RADIUS của doanh nghiệp","B":"Từng kiểu mã hóa WEP hoặc WPA","C":"Từng băng tần 2.4 GHz và 5 GHz","D":"Từng AP hoặc radio cụ thể, kể cả khi cùng SSID"},"answer":"D","family":"g28c2","style":"distinction","section":"5.1","source":"Đề cương mục 5.1; slide Bài 5","explanation":"BSSID là MAC của từng AP/radio, nên phân biệt được các AP dù cùng SSID.","optionNotes":{"A":"Phân biệt người dùng là việc của xác thực (802.1X/RADIUS).","B":"Kiểu mã hóa không xác định bằng BSSID.","C":"Băng tần không xác định bằng BSSID."}},{"id":"gen_332","chapter":"5","question":"Nếu laptop kết nối vô tuyến tới thiết bị nối vào lan có dây, hiện tượng nào đang xảy ra?","options":{"A":"Station","B":"BSSID","C":"Access Point","D":"SSID"},"answer":"C","family":"g28c3","style":"scenario","section":"5.1","source":"Đề cương mục 5.1; slide Bài 5","explanation":"Thiết bị nhận kết nối vô tuyến và nối vào LAN có dây là Access Point.","optionNotes":{"A":"Station là chính chiếc laptop, không phải thiết bị nối vào LAN.","B":"BSSID là địa chỉ của AP, không phải thiết bị.","D":"SSID là tên mạng."}},{"id":"gen_333","chapter":"5","question":"Access Point (AP) đóng vai trò gì trong WLAN?","options":{"A":"Điểm kết nối giữa các máy không dây và mạng có dây","B":"Máy khách không dây của người dùng, như laptop hay điện thoại","C":"Máy chủ xác thực RADIUS","D":"Thiết bị phát nhiễu chặn sóng"},"answer":"A","family":"g28c3","style":"distinction","section":"5.1","source":"Đề cương mục 5.1; slide Bài 5","explanation":"AP là điểm kết nối giữa các máy không dây và mạng có dây.","optionNotes":{"B":"Máy khách không dây là station (STA).","C":"Máy chủ xác thực là RADIUS.","D":"Phát nhiễu chặn sóng là jamming, không phải vai trò của AP."}},{"id":"gen_335","chapter":"5","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Điện thoại gửi khung 802.11 tới điểm truy cập?","options":{"A":"SSID","B":"Station","C":"Access Point","D":"BSSID"},"answer":"B","family":"g28c4","style":"scenario","section":"5.1","source":"Đề cương mục 5.1; slide Bài 5","explanation":"Điện thoại là thiết bị đầu cuối không dây gửi khung tới AP, tức station.","optionNotes":{"A":"SSID là tên mạng.","C":"AP là đầu nhận, còn điện thoại là station.","D":"BSSID là địa chỉ của AP."}},{"id":"gen_336","chapter":"5","question":"Trong WLAN, STA (station) là gì?","options":{"A":"Điểm truy cập phát sóng Wi-Fi và nối máy không dây vào mạng có dây","B":"Máy chủ cấp phát địa chỉ IP","C":"Bộ điều khiển quản lý nhiều AP","D":"Thiết bị đầu cuối có card không dây, như laptop hay điện thoại"},"answer":"D","family":"g28c4","style":"distinction","section":"5.1","source":"Đề cương mục 5.1; slide Bài 5","explanation":"STA là thiết bị đầu cuối có card không dây như laptop, điện thoại.","optionNotes":{"A":"Thiết bị phát sóng nối vào mạng có dây là AP.","B":"Cấp IP là DHCP.","C":"Quản lý nhiều AP là bộ điều khiển WLAN (controller)."}},{"id":"gen_338","chapter":"5","question":"Xét tình huống: Máy trạm hoãn truyền khi kênh radio đang bận. Cách gọi đúng là gì?","options":{"A":"RTS/CTS","B":"Beacon frame","C":"Association","D":"CSMA/CA"},"answer":"D","family":"g29c1","style":"scenario","section":"5.1","source":"Đề cương mục 5.1; slide Bài 5","explanation":"Nghe kênh, thấy bận thì hoãn truyền để tránh xung đột là CSMA/CA.","optionNotes":{"A":"RTS/CTS là trao đổi khung xin/cho phép gửi trước khi truyền.","B":"Beacon là khung AP quảng bá thông tin mạng.","C":"Association là bước ghép nối với AP."}},{"id":"gen_339","chapter":"5","question":"Theo slide, WLAN dùng cơ chế truy nhập môi trường nào?","options":{"A":"CSMA/CD","B":"Token Ring","C":"TDMA","D":"CSMA/CA"},"answer":"D","family":"g29c1","style":"distinction","section":"5.1","source":"Đề cương mục 5.1; slide Bài 5","explanation":"WLAN dùng CSMA/CA (tránh xung đột) vì máy không dây không vừa phát vừa nghe để phát hiện xung đột được.","optionNotes":{"A":"CSMA/CD (phát hiện xung đột) dùng cho Ethernet có dây.","B":"Token Ring là mạng vòng có dây kiểu cũ.","C":"TDMA chia khe thời gian, dùng ở mạng di động, không phải WLAN."}},{"id":"gen_341","chapter":"5","question":"Nếu hai máy không nghe thấy nhau dùng khung điều phối trước khi gửi dữ liệu, hiện tượng nào đang xảy ra?","options":{"A":"Association","B":"CSMA/CA","C":"Beacon frame","D":"RTS/CTS"},"answer":"D","family":"g29c2","style":"scenario","section":"5.1","source":"Đề cương mục 5.1; slide Bài 5","explanation":"Hai máy không nghe thấy nhau (trạm ẩn) trao đổi khung RTS/CTS với AP trước khi gửi dữ liệu.","optionNotes":{"A":"Association là ghép nối với AP.","B":"CSMA/CA thuần chỉ nghe kênh, không giải quyết được trạm ẩn.","C":"Beacon là khung quảng bá của AP."}},{"id":"gen_342","chapter":"5","question":"Theo slide, RTS/CTS hữu ích nhất trong trường hợp nào?","options":{"A":"Khi cần chống kẻ tấn công nghe lén WLAN","B":"Khi cần mã hóa khung dữ liệu giữa STA và AP","C":"Khi cần ẩn SSID khỏi các máy khách lạ","D":"Khi xung đột do trạm ẩn (hidden node) đáng kể"},"answer":"D","family":"g29c2","style":"distinction","section":"5.1","source":"Đề cương mục 5.1; slide Bài 5","explanation":"RTS/CTS hữu ích khi xung đột do trạm ẩn (hidden node) đáng kể.","optionNotes":{"A":"RTS/CTS không chống nghe lén.","B":"RTS/CTS không mã hóa dữ liệu.","C":"RTS/CTS không ẩn SSID."}},{"id":"gen_344","chapter":"5","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Máy quét thấy mạng nhờ thông báo định kỳ từ điểm truy cập?","options":{"A":"Beacon frame","B":"Association","C":"RTS/CTS","D":"CSMA/CA"},"answer":"A","family":"g29c3","style":"scenario","section":"5.1","source":"Đề cương mục 5.1; slide Bài 5","explanation":"Máy quét thấy mạng nhờ khung AP phát định kỳ: beacon frame.","optionNotes":{"B":"Association là bước kết nối sau khi đã thấy mạng.","C":"RTS/CTS dùng để điều phối truyền dữ liệu.","D":"CSMA/CA là cơ chế truy nhập kênh."}},{"id":"gen_345","chapter":"5","question":"Beacon frame trong WLAN dùng để làm gì?","options":{"A":"Mã hóa dữ liệu truyền giữa STA và AP sau khi kết nối","B":"Xác thực người dùng với RADIUS","C":"AP định kỳ quảng bá thông tin mạng như SSID","D":"Ngắt kết nối máy khách khỏi AP"},"answer":"C","family":"g29c3","style":"distinction","section":"5.1","source":"Đề cương mục 5.1; slide Bài 5","explanation":"AP định kỳ phát beacon để quảng bá thông tin mạng như SSID.","optionNotes":{"A":"Beacon không mã hóa dữ liệu.","B":"Xác thực với RADIUS là 802.1X/EAP.","D":"Ngắt kết nối dùng khung deauthentication."}},{"id":"gen_347","chapter":"5","question":"Máy trạm hoàn tất ghép nối logic với AP sau khi chọn mạng. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"CSMA/CA","B":"Association","C":"Beacon frame","D":"RTS/CTS"},"answer":"B","family":"g29c4","style":"scenario","section":"5.1","source":"Đề cương mục 5.1; slide Bài 5","explanation":"Ghép nối logic giữa máy trạm và AP sau khi chọn mạng là association.","optionNotes":{"A":"CSMA/CA là cơ chế truy nhập kênh.","C":"Beacon là khung quảng bá của AP.","D":"RTS/CTS điều phối việc gửi dữ liệu."}},{"id":"gen_348","chapter":"5","question":"Thứ tự thông thường khi STA kết nối vào AP là gì?","options":{"A":"Kết hợp → dò tìm mạng → xác thực","B":"Xác thực → dò tìm mạng → kết hợp","C":"Mã hóa → dò tìm mạng → xác thực","D":"Dò tìm mạng → xác thực → kết hợp (association)"},"answer":"D","family":"g29c4","style":"distinction","section":"5.1","source":"Đề cương mục 5.1; slide Bài 5","explanation":"STA dò tìm mạng trước, rồi xác thực với AP, cuối cùng mới kết hợp (association).","optionNotes":{"A":"Phải thấy mạng trước khi kết hợp.","B":"Phải dò tìm mạng trước khi xác thực.","C":"Mã hóa diễn ra sau khi đã kết nối, không phải bước đầu tiên."}},{"id":"gen_350","chapter":"5","question":"Nếu nhân viên cắm ap cá nhân vào cổng lan công ty, hiện tượng nào đang xảy ra?","options":{"A":"Rogue AP","B":"Evil Twin","C":"Deauthentication spoofing","D":"Jamming"},"answer":"A","family":"g30c1","style":"scenario","section":"5.2","source":"Đề cương mục 5.2; slide Bài 5","explanation":"AP cá nhân cắm vào LAN công ty mà không được phê duyệt là rogue AP.","optionNotes":{"B":"Evil Twin là AP giả cùng tên mạng để dụ người dùng.","C":"Deauth spoofing là gửi khung ngắt kết nối giả.","D":"Jamming là phát nhiễu."}},{"id":"gen_351","chapter":"5","question":"Rogue AP là gì?","options":{"A":"AP chính thức của tổ chức, được cấu hình và giám sát đầy đủ","B":"AP đã tắt phát SSID","C":"AP dùng chuẩn WPA3","D":"AP gắn vào mạng mà không được quản trị phê duyệt"},"answer":"D","family":"g30c1","style":"distinction","section":"5.2","source":"Đề cương mục 5.2; slide Bài 5","explanation":"Rogue AP là AP gắn vào mạng mà không được quản trị phê duyệt.","optionNotes":{"A":"AP chính thức được quản lý thì không phải rogue.","B":"Ẩn SSID không làm AP thành rogue.","C":"Dùng WPA3 không liên quan việc AP có được phê duyệt."}},{"id":"gen_354","chapter":"5","question":"Tấn công Evil Twin hoạt động thế nào?","options":{"A":"Phát nhiễu vô tuyến cường độ cao làm tê liệt kênh truyền của AP","B":"Dò mã PIN WPS để lấy mật khẩu","C":"Bẻ khóa WEP bằng các IV bị lặp","D":"Dựng AP giả cùng tên mạng để dụ người dùng kết nối"},"answer":"D","family":"g30c2","style":"distinction","section":"5.2","source":"Đề cương mục 5.2; slide Bài 5","explanation":"Evil Twin dựng AP giả cùng tên mạng để người dùng kết nối nhầm vào.","optionNotes":{"A":"Phát nhiễu là jamming.","B":"Dò PIN WPS là tấn công WPS.","C":"Bẻ WEP bằng IV lặp là tấn công WEP."}},{"id":"gen_356","chapter":"5","question":"Thiết bị phát nhiễu cùng băng tần khiến STA mất kết nối. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"Jamming","B":"Evil Twin","C":"Deauthentication spoofing","D":"Rogue AP"},"answer":"A","family":"g30c3","style":"scenario","section":"5.2","source":"Đề cương mục 5.2; slide Bài 5","explanation":"Phát nhiễu cùng băng tần làm thiết bị mất kết nối là jamming.","optionNotes":{"B":"Evil Twin là AP giả, không phát nhiễu.","C":"Deauth spoofing dùng khung quản lý giả, không phải nhiễu.","D":"Rogue AP là AP không được phê duyệt."}},{"id":"gen_357","chapter":"5","question":"Tấn công jamming trong WLAN là gì?","options":{"A":"Dựng AP giả phát cùng SSID để dụ người dùng kết nối vào","B":"Bẻ khóa WEP bằng IV bị lặp","C":"Phát nhiễu vô tuyến làm gián đoạn kênh truyền","D":"Dò mật khẩu bằng từ điển"},"answer":"C","family":"g30c3","style":"distinction","section":"5.2","source":"Đề cương mục 5.2; slide Bài 5","explanation":"Jamming phát nhiễu vô tuyến để làm gián đoạn kênh truyền.","optionNotes":{"A":"Dựng AP giả cùng SSID là Evil Twin.","B":"Bẻ WEP bằng IV lặp là tấn công WEP.","D":"Dò mật khẩu bằng từ điển là tấn công từ điển."}},{"id":"gen_359","chapter":"5","question":"Xét tình huống: STA bị đá khỏi AP do khung quản lý giả mạo. Cách gọi đúng là gì?","options":{"A":"Jamming","B":"Rogue AP","C":"Deauthentication spoofing","D":"Evil Twin"},"answer":"C","family":"g30c4","style":"scenario","section":"5.2","source":"Đề cương mục 5.2; slide Bài 5","explanation":"Khung quản lý giả làm STA bị ngắt khỏi AP là deauthentication spoofing.","optionNotes":{"A":"Jamming dùng nhiễu, không dùng khung giả.","B":"Rogue AP là AP không được phê duyệt.","D":"Evil Twin là AP giả cùng tên."}},{"id":"gen_360","chapter":"5","question":"Tấn công deauthentication giả mạo gây ra hậu quả gì?","options":{"A":"Máy khách bị ngắt kết nối khỏi AP","B":"Mật khẩu Wi-Fi bị đổi","C":"AP bị hỏng phần cứng","D":"Dữ liệu được mã hóa mạnh hơn"},"answer":"A","family":"g30c4","style":"distinction","section":"5.2","source":"Đề cương mục 5.2; slide Bài 5","explanation":"Khung deauthentication giả làm máy khách bị ngắt kết nối khỏi AP.","optionNotes":{"B":"Tấn công này không đổi mật khẩu.","C":"Nó không làm hỏng phần cứng AP.","D":"Nó không làm mã hóa mạnh hơn."}},{"id":"gen_362","chapter":"5","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Kẻ lạ thu khung phát trên Wi-Fi mở?","options":{"A":"Tấn công từ điển mật khẩu","B":"Truy cập trái phép WLAN","C":"Tấn công WPS PIN","D":"Nghe lén WLAN"},"answer":"D","family":"g31c1","style":"scenario","section":"5.2-5.3","source":"Đề cương mục 5.2-5.3; slide Bài 5","explanation":"Thu khung phát trên Wi-Fi mở để xem nội dung là nghe lén WLAN.","optionNotes":{"A":"Tấn công từ điển là dò mật khẩu.","B":"Truy cập trái phép là vào mạng khi không được phép; ở đây chỉ thu khung.","C":"Tấn công WPS PIN là dò mã PIN."}},{"id":"gen_363","chapter":"5","question":"Vì sao WLAN dễ bị nghe lén hơn mạng có dây?","options":{"A":"Vì WLAN không dùng địa chỉ IP nên không thể áp dụng tường lửa","B":"Vì WLAN luôn chạy chậm hơn","C":"Sóng radio có thể bị thu mà không cần cắm vào mạng","D":"Vì AP không có địa chỉ MAC"},"answer":"C","family":"g31c1","style":"distinction","section":"5.2-5.3","source":"Đề cương mục 5.2-5.3; slide Bài 5","explanation":"Sóng radio lan ra không gian, ai trong vùng phủ cũng thu được mà không cần cắm dây.","optionNotes":{"A":"WLAN vẫn dùng IP và áp dụng được tường lửa.","B":"Tốc độ không quyết định việc bị nghe lén.","D":"AP có địa chỉ MAC (chính là BSSID)."}},{"id":"gen_365","chapter":"5","question":"Mật khẩu PSK yếu bị đoán từ danh sách từ thông dụng. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"Tấn công WPS PIN","B":"Nghe lén WLAN","C":"Truy cập trái phép WLAN","D":"Tấn công từ điển mật khẩu"},"answer":"D","family":"g31c2","style":"scenario","section":"5.2-5.3","source":"Đề cương mục 5.2-5.3; slide Bài 5","explanation":"Đoán PSK yếu từ danh sách từ thông dụng là tấn công từ điển mật khẩu.","optionNotes":{"A":"Tấn công WPS PIN dò mã PIN 8 chữ số, không dùng từ điển.","B":"Nghe lén chỉ thu khung.","C":"Truy cập trái phép là hậu quả sau khi có mật khẩu, không phải cách đoán."}},{"id":"gen_366","chapter":"5","question":"Biện pháp nào làm tấn công từ điển vào mật khẩu Wi-Fi (PSK) khó thành công hơn?","options":{"A":"Đổi SSID thành một tên khác","B":"Giảm công suất phát của AP","C":"Dùng mật khẩu dài và ngẫu nhiên","D":"Bật WPS để kết nối nhanh hơn"},"answer":"C","family":"g31c2","style":"distinction","section":"5.2-5.3","source":"Đề cương mục 5.2-5.3; slide Bài 5","explanation":"Mật khẩu dài, ngẫu nhiên không có trong từ điển nên tấn công từ điển khó thành công.","optionNotes":{"A":"Đổi SSID không làm mật khẩu khó đoán hơn.","B":"Giảm công suất phát không bảo vệ mật khẩu.","D":"Bật WPS thêm một điểm yếu khác."}},{"id":"gen_368","chapter":"5","question":"Xét tình huống: Bộ định tuyến mở WPS PIN khiến kẻ gần đó thử nhiều tổ hợp. Cách gọi đúng là gì?","options":{"A":"Truy cập trái phép WLAN","B":"Tấn công WPS PIN","C":"Tấn công từ điển mật khẩu","D":"Nghe lén WLAN"},"answer":"B","family":"g31c3","style":"scenario","section":"5.2-5.3","source":"Đề cương mục 5.2-5.3; slide Bài 5","explanation":"Router mở WPS PIN để kẻ gần đó thử nhiều tổ hợp là tấn công WPS PIN.","optionNotes":{"A":"Truy cập trái phép là kết quả, không phải tên kỹ thuật tấn công.","C":"Tấn công từ điển nhắm vào mật khẩu PSK, không vào mã PIN.","D":"Nghe lén chỉ thu khung."}},{"id":"gen_369","chapter":"5","question":"Biện pháp phù hợp với rủi ro tấn công WPS PIN là gì?","options":{"A":"Tắt WPS khi không cần dùng","B":"Bật WPS cho mọi thiết bị","C":"Đổi SSID mỗi ngày","D":"Chuyển sang mạng WLAN mở"},"answer":"A","family":"g31c3","style":"distinction","section":"5.2-5.3","source":"Đề cương mục 5.2-5.3; slide Bài 5","explanation":"Tắt WPS khi không dùng thì không còn mã PIN để dò.","optionNotes":{"B":"Bật WPS cho mọi thiết bị làm rủi ro tăng.","C":"Đổi SSID không ảnh hưởng tới WPS.","D":"Mạng mở kém an toàn hơn."}},{"id":"gen_371","chapter":"5","question":"Nếu người ngoài biết mật khẩu chung và kết nối lan nội bộ, hiện tượng nào đang xảy ra?","options":{"A":"Nghe lén WLAN","B":"Truy cập trái phép WLAN","C":"Tấn công WPS PIN","D":"Tấn công từ điển mật khẩu"},"answer":"B","family":"g31c4","style":"scenario","section":"5.2-5.3","source":"Đề cương mục 5.2-5.3; slide Bài 5","explanation":"Người ngoài dùng mật khẩu chung để vào LAN nội bộ là truy cập trái phép WLAN.","optionNotes":{"A":"Nghe lén chỉ thu khung, không vào mạng.","C":"Họ đã biết mật khẩu, không cần dò PIN.","D":"Họ được biết mật khẩu, không phải đoán bằng từ điển."}},{"id":"gen_372","chapter":"5","question":"Biện pháp nào ngăn người ngoài dùng mật khẩu Wi-Fi bị chia sẻ để vào mạng?","options":{"A":"Ẩn SSID khỏi danh sách mạng để người ngoài không nhìn thấy","B":"Lọc theo tên thiết bị","C":"Tăng công suất phát của AP","D":"Xác thực riêng từng người qua 802.1X và RADIUS"},"answer":"D","family":"g31c4","style":"distinction","section":"5.2-5.3","source":"Đề cương mục 5.2-5.3; slide Bài 5","explanation":"802.1X với RADIUS cho mỗi người một tài khoản riêng; mật khẩu chung không còn, và thu hồi được từng người.","optionNotes":{"A":"SSID ẩn vẫn bị lộ khi quét, và không ngăn người biết mật khẩu.","B":"Tên thiết bị đổi được dễ dàng.","C":"Tăng công suất phát làm sóng lan xa hơn."}},{"id":"gen_375","chapter":"5","question":"Theo slide, WEP hiện nay nên được xem là gì?","options":{"A":"Tiêu chuẩn hiện hành song song với WPA3","B":"Lựa chọn tốt cho mạng khách vì cấu hình nhẹ","C":"Kiến thức legacy, không dùng cho thiết kế mới","D":"Chuẩn bảo mật bắt buộc của Wi-Fi 6 và Wi-Fi 7"},"answer":"C","family":"g32c1","style":"distinction","section":"5.3-5.4","source":"Đề cương mục 5.3-5.4; slide Bài 5","explanation":"Slide coi WEP là kiến thức legacy, không dùng cho thiết kế mới vì đã bị bẻ.","optionNotes":{"A":"WEP không còn là tiêu chuẩn hiện hành.","B":"WEP không an toàn, kể cả cho mạng khách.","D":"Wi-Fi 6/7 dùng WPA3, không dùng WEP."}},{"id":"gen_377","chapter":"5","question":"Xét tình huống: Thiết bị cũ chỉ hỗ trợ lớp bảo vệ trung gian trước thế hệ dùng AES-CCMP. Cách gọi đúng là gì?","options":{"A":"WPA2","B":"WEP","C":"WPA","D":"Mạng WLAN mở"},"answer":"C","family":"g32c2","style":"scenario","section":"5.3-5.4","source":"Đề cương mục 5.3-5.4; slide Bài 5","explanation":"Lớp trung gian giữa WEP và WPA2 (AES-CCMP) là WPA, dùng TKIP.","optionNotes":{"A":"WPA2 chính là thế hệ dùng AES-CCMP.","B":"WEP là thế hệ trước, không phải lớp trung gian.","D":"Mạng mở không có bảo vệ."}},{"id":"gen_378","chapter":"5","question":"Theo slide, WPA ra đời nhằm mục đích gì?","options":{"A":"Thay thế WPA3 trong mạng doanh nghiệp vì WPA3 quá chậm","B":"Thay thế WEP, dùng TKIP để tăng cường bảo mật","C":"Mã hóa SSID thay cho dữ liệu","D":"Chuẩn hóa tốc độ của Wi-Fi 6"},"answer":"B","family":"g32c2","style":"distinction","section":"5.3-5.4","source":"Đề cương mục 5.3-5.4; slide Bài 5","explanation":"WPA ra đời để thay WEP, dùng TKIP đổi khóa theo gói nhằm tăng bảo mật.","optionNotes":{"A":"WPA ra trước WPA3 nhiều năm.","C":"WPA mã hóa dữ liệu, không mã hóa SSID.","D":"WPA không liên quan tốc độ Wi-Fi 6."}},{"id":"gen_380","chapter":"5","question":"Nếu mạng doanh nghiệp dùng chế độ enterprise và 802.1x, hiện tượng nào đang xảy ra?","options":{"A":"WPA","B":"Mạng WLAN mở","C":"WEP","D":"WPA2"},"answer":"D","family":"g32c3","style":"scenario","section":"5.3-5.4","source":"Đề cương mục 5.3-5.4; slide Bài 5","explanation":"Chế độ Enterprise với 802.1X là WPA2-Enterprise.","optionNotes":{"A":"WPA là thế hệ cũ dùng TKIP; câu hỏi nhắm tới WPA2 trong slide.","B":"Mạng mở không có xác thực.","C":"WEP không có chế độ Enterprise với 802.1X."}},{"id":"gen_381","chapter":"5","question":"Theo slide, WPA2 được chuẩn hóa năm nào và dùng cơ chế mã hóa gì?","options":{"A":"Năm 1997, RC4","B":"Năm 2004, AES-CCMP","C":"Năm 2018, SAE","D":"Năm 2003, TKIP"},"answer":"B","family":"g32c3","style":"distinction","section":"5.3-5.4","source":"Đề cương mục 5.3-5.4; slide Bài 5","explanation":"Theo slide, WPA2 chuẩn hóa năm 2004 và dùng AES-CCMP.","optionNotes":{"A":"1997 là năm 802.11 gốc; RC4 là của WEP.","C":"2018 và SAE là của WPA3.","D":"2003 và TKIP là của WPA."}},{"id":"gen_383","chapter":"5","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Khách kết nối SSID mà không cần khóa WLAN?","options":{"A":"WEP","B":"WPA2","C":"Mạng WLAN mở","D":"WPA"},"answer":"C","family":"g32c4","style":"scenario","section":"5.3-5.4","source":"Đề cương mục 5.3-5.4; slide Bài 5","explanation":"Kết nối SSID mà không cần khóa là mạng WLAN mở.","optionNotes":{"A":"WEP cần khóa.","B":"WPA2 cần khóa hoặc tài khoản.","D":"WPA cần khóa."}},{"id":"gen_384","chapter":"5","question":"Rủi ro chính khi dùng Wi-Fi công cộng mở (không mật khẩu) là gì?","options":{"A":"Không thể truy cập Internet vì AP không có mật khẩu cấu hình","B":"Máy tự động bị chuyển sang WPA3","C":"Dữ liệu không được mã hóa ở tầng WLAN, dễ bị nghe lén","D":"AP không phát được SSID"},"answer":"C","family":"g32c4","style":"distinction","section":"5.3-5.4","source":"Đề cương mục 5.3-5.4; slide Bài 5","explanation":"Mạng mở không mã hóa ở tầng WLAN, nên dữ liệu dễ bị nghe lén.","optionNotes":{"A":"Mạng mở vẫn vào được Internet.","B":"Máy không tự chuyển sang WPA3.","D":"Mạng mở vẫn phát SSID."}},{"id":"gen_386","chapter":"5","question":"Xét tình huống: Phân tích giao thức cũ thấy khóa dòng và IV ngắn. Cách gọi đúng là gì?","options":{"A":"RC4","B":"IV","C":"AES-CCMP","D":"TKIP"},"answer":"A","family":"g33c1","style":"scenario","section":"5.3-5.4","source":"Đề cương mục 5.3-5.4; slide Bài 5","explanation":"Khóa dòng kèm IV ngắn là đặc điểm của RC4 trong WEP.","optionNotes":{"B":"IV chỉ là một thành phần; thuật toán khóa dòng được hỏi là RC4.","C":"AES-CCMP là mã hóa khối, không phải khóa dòng.","D":"TKIP là giao thức quản lý khóa bọc quanh RC4."}},{"id":"gen_387","chapter":"5","question":"RC4 mà WEP sử dụng thuộc loại thuật toán nào?","options":{"A":"Mã hóa dòng (stream cipher)","B":"Mã hóa khối AES chế độ CCM","C":"Hàm băm một chiều tạo ICV","D":"Giao thức trao đổi khóa SAE"},"answer":"A","family":"g33c1","style":"distinction","section":"5.3-5.4","source":"Đề cương mục 5.3-5.4; slide Bài 5","explanation":"RC4 là mã hóa dòng (stream cipher).","optionNotes":{"B":"AES-CCM là mã hóa khối, dùng ở WPA2.","C":"RC4 không phải hàm băm.","D":"SAE là giao thức trao đổi khóa của WPA3."}},{"id":"gen_389","chapter":"5","question":"Nếu thiết bị cũ nâng từ wep lên chế độ trộn khóa theo từng gói, hiện tượng nào đang xảy ra?","options":{"A":"AES-CCMP","B":"RC4","C":"IV","D":"TKIP"},"answer":"D","family":"g33c2","style":"scenario","section":"5.3-5.4","source":"Đề cương mục 5.3-5.4; slide Bài 5","explanation":"Trộn khóa theo từng gói để nâng cấp từ WEP trên thiết bị cũ là TKIP.","optionNotes":{"A":"AES-CCMP cần phần cứng mới hơn, không phải nâng cấp cho thiết bị WEP.","B":"RC4 là thuật toán cũ của WEP.","C":"IV là vector khởi tạo, không phải cơ chế nâng cấp."}},{"id":"gen_390","chapter":"5","question":"So với WEP, TKIP của WPA cải thiện điểm nào?","options":{"A":"Chuyển hẳn sang mã hóa khối AES-CCMP","B":"Bỏ mã hóa, chỉ dùng SSID ẩn để bảo vệ","C":"Đổi khóa theo từng gói thay vì dùng một khóa tĩnh","D":"Bắt buộc máy chủ RADIUS cho mọi mạng"},"answer":"C","family":"g33c2","style":"distinction","section":"5.3-5.4","source":"Đề cương mục 5.3-5.4; slide Bài 5","explanation":"TKIP đổi khóa theo từng gói thay cho một khóa tĩnh như WEP.","optionNotes":{"A":"Chuyển sang AES-CCMP là WPA2, không phải TKIP.","B":"TKIP vẫn mã hóa.","D":"TKIP không bắt buộc RADIUS."}},{"id":"gen_392","chapter":"5","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Bộ định tuyến chọn WPA2 với CCMP thay cho TKIP?","options":{"A":"TKIP","B":"AES-CCMP","C":"RC4","D":"IV"},"answer":"B","family":"g33c3","style":"scenario","section":"5.3-5.4","source":"Đề cương mục 5.3-5.4; slide Bài 5","explanation":"Chọn WPA2 với CCMP là dùng AES-CCMP.","optionNotes":{"A":"TKIP là thứ bị thay thế trong tình huống.","C":"RC4 là thuật toán của WEP.","D":"IV là thành phần của WEP."}},{"id":"gen_395","chapter":"5","question":"Tái sử dụng giá trị 24 bit làm lộ điểm yếu của WEP. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"AES-CCMP","B":"IV","C":"TKIP","D":"RC4"},"answer":"B","family":"g33c4","style":"scenario","section":"5.3-5.4","source":"Đề cương mục 5.3-5.4; slide Bài 5","explanation":"Giá trị 24 bit bị dùng lại trong WEP là IV (vector khởi tạo).","optionNotes":{"A":"AES-CCMP không có điểm yếu này.","C":"TKIP ra đời để khắc phục điểm yếu này.","D":"RC4 là thuật toán; giá trị 24 bit bị lặp là IV."}},{"id":"gen_398","chapter":"5","question":"Nếu quán nhỏ phát mật khẩu wi-fi chung cho khách quen, hiện tượng nào đang xảy ra?","options":{"A":"WPA2-Personal","B":"RADIUS","C":"802.1X","D":"WPA2-Enterprise"},"answer":"A","family":"g34c1","style":"scenario","section":"5.4-5.5","source":"Đề cương mục 5.4-5.5; slide Bài 5","explanation":"Một mật khẩu chung cho mọi khách là WPA2-Personal (PSK).","optionNotes":{"B":"RADIUS là máy chủ xác thực từng người.","C":"802.1X là xác thực từng người, không dùng mật khẩu chung.","D":"Enterprise dùng tài khoản riêng."}},{"id":"gen_401","chapter":"5","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Trường dùng tài khoản sinh viên với RADIUS thay mật khẩu chung?","options":{"A":"WPA2-Personal","B":"802.1X","C":"RADIUS","D":"WPA2-Enterprise"},"answer":"D","family":"g34c2","style":"scenario","section":"5.4-5.5","source":"Đề cương mục 5.4-5.5; slide Bài 5","explanation":"Tài khoản riêng từng sinh viên qua RADIUS là WPA2-Enterprise.","optionNotes":{"A":"Personal dùng mật khẩu chung.","B":"802.1X chỉ là cơ chế kiểm soát cổng bên trong; cấu hình WLAN được gọi là WPA2-Enterprise.","C":"RADIUS chỉ là máy chủ xác thực, không phải tên chế độ bảo mật."}},{"id":"gen_404","chapter":"5","question":"AP chuyển yêu cầu xác thực doanh nghiệp tới server AAA. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"RADIUS","B":"WPA2-Enterprise","C":"WPA2-Personal","D":"802.1X"},"answer":"A","family":"g34c3","style":"scenario","section":"5.4-5.5","source":"Đề cương mục 5.4-5.5; slide Bài 5","explanation":"Máy chủ AAA nhận yêu cầu xác thực từ AP là RADIUS.","optionNotes":{"B":"WPA2-Enterprise là tên chế độ, còn server AAA là RADIUS.","C":"Personal không có server AAA.","D":"802.1X là cơ chế kiểm soát cổng, không phải máy chủ."}},{"id":"gen_407","chapter":"5","question":"Xét tình huống: STA phải hoàn tất EAP trước khi được cấp quyền vào mạng. Cách gọi đúng là gì?","options":{"A":"WPA2-Personal","B":"WPA2-Enterprise","C":"802.1X","D":"RADIUS"},"answer":"C","family":"g34c4","style":"scenario","section":"5.4-5.5","source":"Đề cương mục 5.4-5.5; slide Bài 5","explanation":"Phải xong EAP mới được vào mạng là kiểm soát truy cập theo cổng 802.1X.","optionNotes":{"A":"Personal không dùng EAP.","B":"Enterprise là tên chế độ; cơ chế chặn cổng tới khi xong EAP là 802.1X.","D":"RADIUS là máy chủ xác thực phía sau."}},{"id":"gen_410","chapter":"5","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Khách chỉ ra Internet mà không tới server đào tạo?","options":{"A":"Quản lý AP tập trung","B":"Phân tách mạng khách","C":"Giám sát WLAN","D":"Phân tách mạng IoT"},"answer":"B","family":"g35c1","style":"scenario","section":"5.5","source":"Đề cương mục 5.5; slide Bài 5","explanation":"Khách chỉ ra Internet mà không vào server nội bộ là phân tách mạng khách.","optionNotes":{"A":"Quản lý AP tập trung là cấu hình AP từ một nơi.","C":"Giám sát WLAN là phát hiện bất thường.","D":"Phân tách IoT dành cho thiết bị IoT, không phải khách."}},{"id":"gen_413","chapter":"5","question":"Camera chỉ được đến máy chủ ghi hình, không tới máy nhân sự. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"Giám sát WLAN","B":"Quản lý AP tập trung","C":"Phân tách mạng khách","D":"Phân tách mạng IoT"},"answer":"D","family":"g35c2","style":"scenario","section":"5.5","source":"Đề cương mục 5.5; slide Bài 5","explanation":"Camera (IoT) chỉ được tới máy ghi hình là phân tách mạng IoT.","optionNotes":{"A":"Giám sát WLAN là phát hiện bất thường.","B":"Quản lý AP tập trung là cấu hình AP.","C":"Mạng khách dành cho người dùng khách, không phải camera."}},{"id":"gen_416","chapter":"5","question":"Xét tình huống: Trường đẩy chính sách SSID đồng bộ cho các tòa nhà. Cách gọi đúng là gì?","options":{"A":"Phân tách mạng IoT","B":"Phân tách mạng khách","C":"Giám sát WLAN","D":"Quản lý AP tập trung"},"answer":"D","family":"g35c3","style":"scenario","section":"5.5","source":"Đề cương mục 5.5; slide Bài 5","explanation":"Đẩy chính sách SSID đồng bộ cho nhiều tòa nhà là quản lý AP tập trung.","optionNotes":{"A":"Phân tách IoT là tách vùng mạng cho thiết bị IoT.","B":"Phân tách mạng khách là tách vùng cho khách.","C":"Giám sát WLAN là phát hiện bất thường."}},{"id":"gen_419","chapter":"5","question":"Nếu bộ phận mạng cảnh báo khi xuất hiện ssid giả gần khuôn viên, hiện tượng nào đang xảy ra?","options":{"A":"Quản lý AP tập trung","B":"Phân tách mạng khách","C":"Phân tách mạng IoT","D":"Giám sát WLAN"},"answer":"D","family":"g35c4","style":"scenario","section":"5.5","source":"Đề cương mục 5.5; slide Bài 5","explanation":"Cảnh báo khi có SSID giả gần khuôn viên là giám sát WLAN.","optionNotes":{"A":"Quản lý tập trung là cấu hình AP.","B":"Phân tách mạng khách là tách vùng.","C":"Phân tách IoT là tách vùng."}},{"id":"case_41","chapter":"5","question":"Hai AP phát cùng SSID của trường; quản trị viên cần phân biệt từng AP/radio để điều tra. Thông tin nào hữu ích nhất?","options":{"A":"SSID","B":"BSSID","C":"Tên VLAN người dùng","D":"Địa chỉ website của trường"},"answer":"B","family":"g28c2","style":"application","section":"5.1","source":"Đề cương mục 5.1; slide Bài 5","explanation":"BSSID là địa chỉ riêng của từng AP/radio, nên phân biệt được hai AP cùng SSID.","optionNotes":{"A":"SSID giống nhau nên không phân biệt được.","C":"Tên VLAN không nhận dạng AP.","D":"Địa chỉ website không liên quan AP."}},{"id":"case_42","chapter":"5","question":"Kẻ xấu dựng AP cùng tên Wi-Fi của trường để dụ sinh viên kết nối. Đây là kiểu tấn công nào?","options":{"A":"Worm qua SMB","B":"Tràn bộ đệm","C":"Evil Twin","D":"Jamming"},"answer":"C","family":"g30c2","style":"application","section":"5.2","source":"Đề cương mục 5.2; slide Bài 5","explanation":"AP giả cùng tên Wi-Fi để dụ kết nối là Evil Twin.","optionNotes":{"A":"Worm qua SMB lây qua chia sẻ tệp.","B":"Tràn bộ đệm là lỗi chương trình.","D":"Jamming là phát nhiễu."}},{"id":"case_43","chapter":"5","question":"Một nguồn phát sóng gây nhiễu khiến nhiều thiết bị không duy trì được kết nối dù mật khẩu đúng. Thuộc tính nào bị ảnh hưởng trực tiếp?","options":{"A":"Tính xác thực của chứng thư web","B":"Tính toàn vẹn của tệp Word","C":"Tính bí mật của bản sao lưu","D":"Tính sẵn sàng của WLAN"},"answer":"D","family":"case_43","style":"application","section":"5.2","source":"Đề cương mục 5.2; slide Bài 5","explanation":"Nhiễu sóng khiến thiết bị không duy trì được kết nối: WLAN mất tính sẵn sàng.","optionNotes":{"A":"Chứng thư web không liên quan nhiễu sóng.","B":"Tệp Word không bị sửa.","C":"Bản sao lưu không bị lộ."}},{"id":"case_44","chapter":"5","question":"AP vẫn dùng WEP. Điểm yếu lịch sử nào gắn trực tiếp với cơ chế này?","options":{"A":"Bắt buộc dùng chứng thư máy chủ","B":"Chặn mọi khung quản lý giả mạo","C":"Dùng SAE thay cho khóa chia sẻ","D":"IV ngắn và tái sử dụng trong RC4"},"answer":"D","family":"case_44","style":"application","section":"5.3","source":"Đề cương mục 5.3; slide Bài 5","explanation":"Điểm yếu lịch sử của WEP là IV ngắn (24 bit) bị tái sử dụng với RC4.","optionNotes":{"A":"WEP không dùng chứng thư máy chủ.","B":"Chặn khung quản lý giả là PMF, không có trong WEP.","C":"SAE là của WPA3."}},{"id":"case_45","chapter":"5","question":"Trường cần thu hồi quyền Wi-Fi của từng sinh viên mà không đổi mật khẩu chung cho mọi người. Cấu hình nào phù hợp nhất?","options":{"A":"WPA2-Enterprise với 802.1X và RADIUS","B":"WEP dùng một khóa chia sẻ","C":"Mạng mở chỉ ẩn SSID","D":"WPA2-Personal dùng một PSK chung"},"answer":"A","family":"case_45","style":"application","section":"5.4","source":"Đề cương mục 5.4; slide Bài 5","explanation":"WPA2-Enterprise với 802.1X và RADIUS cấp tài khoản riêng, khóa được từng người mà không đổi mật khẩu chung.","optionNotes":{"B":"WEP một khóa chung, lại không an toàn.","C":"Mạng mở không có xác thực.","D":"PSK chung phải đổi cho mọi người khi thu hồi."}},{"id":"case_46","chapter":"5","question":"Một nhóm muốn thay PSK yếu bằng cơ chế xác thực mật khẩu của WPA3-Personal trong slide cập nhật. Cơ chế đó là gì?","options":{"A":"SAE","B":"TKIP","C":"WEP","D":"RC4"},"answer":"A","family":"case_46","style":"application","section":"5.4","source":"Đề cương mục 5.4; slide Bài 5","explanation":"WPA3-Personal thay PSK cũ bằng SAE, chống đoán mật khẩu ngoại tuyến.","optionNotes":{"B":"TKIP là của WPA.","C":"WEP là chuẩn cũ.","D":"RC4 là thuật toán của WEP."}},{"id":"case_47","chapter":"5","question":"Khung deauthentication giả làm thiết bị liên tục rớt Wi-Fi. Tính năng nào trong slide WLAN cập nhật giúp bảo vệ khung quản lý tương ứng?","options":{"A":"PMF","B":"WEP IV","C":"NAT","D":"DHCP"},"answer":"A","family":"case_47","style":"application","section":"5.4","source":"Đề cương mục 5.4; slide Bài 5","explanation":"PMF (Protected Management Frames) bảo vệ khung quản lý, chống deauthentication giả.","optionNotes":{"B":"WEP IV là điểm yếu cũ, không bảo vệ gì.","C":"NAT là dịch địa chỉ.","D":"DHCP cấp địa chỉ IP."}},{"id":"case_48","chapter":"5","question":"Mạng khách cần mã hóa liên kết cho từng thiết bị mà không cấp mật khẩu chung. Cơ chế nào được slide WLAN cập nhật nêu cho mạng mở nâng cao?","options":{"A":"OWE","B":"WPS PIN","C":"TKIP","D":"WEP"},"answer":"A","family":"case_48","style":"application","section":"5.4","source":"Đề cương mục 5.4; slide Bài 5","explanation":"OWE (Enhanced Open) mã hóa liên kết cho từng thiết bị trên mạng mở mà không cần mật khẩu.","optionNotes":{"B":"WPS PIN là cơ chế cài đặt dễ bị dò.","C":"TKIP cần mật khẩu.","D":"WEP cần khóa chung."}},{"id":"case_49","chapter":"5","question":"AP dùng WPA2; một người nghĩ chỉ cần thấy SSID giống trường là có thể bỏ qua việc xác thực máy chủ. Nhận định nào đúng?","options":{"A":"SSID giống nhau bảo đảm cùng một AP","B":"WPA2 tự xác minh mọi trang web","C":"SSID giống nhau không chứng minh AP là thật","D":"BSSID không thể bị quan sát"},"answer":"C","family":"case_49","style":"application","section":"5.4-5.5","source":"Đề cương mục 5.4-5.5; slide Bài 5","explanation":"SSID chỉ là tên, AP giả đặt được trùng tên, nên SSID giống không chứng minh AP là thật.","optionNotes":{"A":"Nhiều AP (kể cả AP giả) có thể cùng SSID.","B":"WPA2 bảo vệ liên kết Wi-Fi, không xác minh trang web.","D":"BSSID được phát công khai, quan sát được."}},{"id":"case_50","chapter":"5","question":"Khách dùng Wi-Fi trường nhưng không được truy cập máy chủ nội bộ. Thiết kế nào phù hợp?","options":{"A":"VLAN khách riêng và luật lọc giữa các vùng","B":"Bỏ kiểm soát ở gateway","C":"Cho khách vào cùng VLAN với DB","D":"Chỉ đổi tên SSID mà giữ cùng quyền LAN"},"answer":"A","family":"case_50","style":"application","section":"5.5","source":"Đề cương mục 5.5; slide Bài 5","explanation":"VLAN khách riêng cộng luật lọc giữa các vùng chặn khách tới máy chủ nội bộ.","optionNotes":{"B":"Bỏ kiểm soát làm khách vào được mọi nơi.","C":"Cùng VLAN với DB là mở đường tới DB.","D":"Đổi tên SSID không đổi quyền truy cập."}},{"id":"reviewed_atm_42","chapter":"5","question":"Giao thức WLAN cũ dùng RC4 và IV ngắn, không nên triển khai mới, là gì?","options":{"A":"WPA","B":"802.1X","C":"WEP","D":"WPA2"},"answer":"C","family":"source_42","style":"review","section":"5.3","source":"https://pttp-huitquiz.site/","explanation":"WEP dùng RC4 với IV ngắn và không nên triển khai mới.","optionNotes":{"A":"WPA dùng TKIP để khắc phục WEP.","B":"802.1X là cơ chế xác thực, không phải giao thức mã hóa.","D":"WPA2 dùng AES-CCMP."}},{"id":"reviewed_atm_93","chapter":"5","question":"Khi dùng Wi-Fi công cộng mở, biện pháp nào bảo vệ nội dung gửi tới website tốt nhất?","options":{"A":"Bỏ kiểm tra chứng thư","B":"Dùng HTTPS hợp lệ","C":"Bật chia sẻ tệp LAN","D":"Tắt cập nhật trình duyệt"},"answer":"B","family":"source_93","style":"review","section":"5.2","source":"https://pttp-huitquiz.site/","explanation":"HTTPS hợp lệ mã hóa đầu cuối tới website, nên nội dung vẫn an toàn dù Wi-Fi không mã hóa.","optionNotes":{"A":"Bỏ kiểm tra chứng thư mở đường cho MITM.","C":"Chia sẻ tệp trên mạng công cộng làm lộ dữ liệu.","D":"Tắt cập nhật trình duyệt giữ lại lỗ hổng."}},{"id":"reviewed_atm_104","chapter":"5","question":"Trong cấu hình WLAN phổ biến, giao thức nào gắn với AES-CCMP thay cho WEP/RC4?","options":{"A":"WPA/TKIP","B":"Mạng mở","C":"WPA2","D":"WEP"},"answer":"C","family":"source_104","style":"review","section":"5.4","source":"https://pttp-huitquiz.site/","explanation":"WPA2 gắn với AES-CCMP thay cho WEP/RC4.","optionNotes":{"A":"WPA dùng TKIP, vẫn dựa trên RC4.","B":"Mạng mở không mã hóa.","D":"WEP chính là thứ bị thay thế."}},{"id":"reviewed_atm_124","chapter":"5","question":"Trường có Wi-Fi khách. Cách nào giảm khả năng khách truy cập máy chủ nội bộ?","options":{"A":"Dùng chung VLAN nội bộ","B":"Mở mọi cổng LAN","C":"Tắt log điểm truy cập","D":"Tách VLAN và lọc truy cập"},"answer":"D","family":"source_124","style":"review","section":"5.5","source":"https://pttp-huitquiz.site/","explanation":"Tách VLAN khách và lọc truy cập giữa các vùng.","optionNotes":{"A":"Dùng chung VLAN nội bộ làm khách thấy máy chủ.","B":"Mở mọi cổng làm tăng rủi ro.","C":"Tắt log không ngăn truy cập."}},{"id":"abbr_c5_057","chapter":"5","question":"WLAN là viết tắt của:","options":{"A":"Wireless Link Access Node","B":"Wide Local Access Network","C":"Wireless Local Area Network","D":"Wired LAN Access Network"},"answer":"C","family":"abbr_c5_057","style":"acronym","section":"5.1","source":"Đề cương mục 5.1-5.5; slide Bài 5","explanation":"WLAN là Wireless Local Area Network, mạng cục bộ không dây.","optionNotes":{"A":"Không phải Wireless Link Access Node.","B":"W là Wireless, không phải Wide.","D":"W là Wireless, không phải Wired."}},{"id":"abbr_c5_058","chapter":"5","question":"SSID là:","options":{"A":"Service Set Identifier – tên logic của WLAN","B":"Secure Station ID – mã bảo mật máy trạm","C":"Signal Strength Indicator – chỉ số tín hiệu","D":"Shared Secret ID – mã khóa chia sẻ"},"answer":"A","family":"ab_ssid","style":"acronym","section":"5.1","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"SSID là Service Set Identifier, tên logic của WLAN.","optionNotes":{"B":"Không phải Secure Station ID.","C":"Chỉ số tín hiệu là RSSI.","D":"Không phải Shared Secret ID."}},{"id":"abbr_c5_059","chapter":"5","question":"BSSID thường dùng để:","options":{"A":"Xác thực người dùng với RADIUS","B":"Ẩn tên mạng khỏi danh sách quét","C":"Mã hóa khung dữ liệu giữa STA và AP","D":"Nhận dạng một BSS/radio cụ thể"},"answer":"D","family":"ab_ssid","style":"acronym","section":"5.1","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"BSSID nhận dạng một BSS/radio cụ thể (thường là MAC của AP).","optionNotes":{"A":"Xác thực người dùng là RADIUS.","B":"Ẩn tên mạng là tắt phát SSID.","C":"Mã hóa khung là WPA2/WPA3."}},{"id":"abbr_c5_060","chapter":"5","question":"Trong WLAN, STA và AP lần lượt là:","options":{"A":"Standard Antenna và Access Port","B":"Station (thiết bị đầu cuối) và Access Point","C":"Station (máy trạm) và Authentication Proxy server","D":"Static Address và Access Protocol"},"answer":"B","family":"abbr_c5_060","style":"acronym","section":"5.1","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"STA là Station (thiết bị đầu cuối), AP là Access Point (điểm truy cập).","optionNotes":{"A":"Không phải Standard Antenna và Access Port.","C":"AP không phải Authentication Proxy server.","D":"Không phải Static Address và Access Protocol."}},{"id":"abbr_c5_061","chapter":"5","question":"WEP là viết tắt của:","options":{"A":"Wireless Enhanced Privacy","B":"Wireless Encryption Protocol","C":"Wired Equivalent Privacy","D":"Wi-Fi Encrypted Password"},"answer":"C","family":"ab_wep","style":"acronym","section":"5.3","source":"Đề cương mục 5.1-5.5; slide Bài 5","explanation":"WEP là Wired Equivalent Privacy, mục tiêu riêng tư tương đương mạng có dây.","optionNotes":{"A":"Không phải Wireless Enhanced Privacy.","B":"Tên hay bị nhầm là Wireless Encryption Protocol, nhưng tên đúng là Wired Equivalent Privacy.","D":"Không phải Wi-Fi Encrypted Password."}},{"id":"abbr_c5_062","chapter":"5","question":"IV trong WEP là:","options":{"A":"Initialization Vector","B":"Identity Validation","C":"Integrity Value","D":"Internal Verification"},"answer":"A","family":"ab_wep","style":"acronym","section":"5.3","source":"Đề cương mục 5.1-5.5; slide Bài 5","explanation":"IV là Initialization Vector, vector khởi tạo 24 bit ghép với khóa WEP.","optionNotes":{"B":"Không phải Identity Validation.","C":"Không phải Integrity Value (đó là ICV).","D":"Không phải Internal Verification."}},{"id":"abbr_c5_063","chapter":"5","question":"WPA là viết tắt của:","options":{"A":"Wired Protection Access","B":"Wi-Fi Protected Access","C":"Wi-Fi Password Authentication","D":"Wireless Privacy Algorithm"},"answer":"B","family":"ab_wpa","style":"acronym","section":"5.4","source":"Đề cương mục 5.1-5.5; slide Bài 5","explanation":"WPA là Wi-Fi Protected Access.","optionNotes":{"A":"W là Wi-Fi, không phải Wired.","C":"Không phải Wi-Fi Password Authentication.","D":"Không phải Wireless Privacy Algorithm."}},{"id":"abbr_c5_064","chapter":"5","question":"TKIP mà WPA dùng để thay WEP là:","options":{"A":"Transport Key Interchange Protocol","B":"Trusted Key Infrastructure Protocol","C":"Timed Key Initialization Process","D":"Temporal Key Integrity Protocol"},"answer":"D","family":"ab_tkip","style":"acronym","section":"5.4","source":"Đề cương mục 5.1-5.5; slide Bài 5","explanation":"TKIP là Temporal Key Integrity Protocol, dùng khóa tạm thời đổi theo gói.","optionNotes":{"A":"Không phải Transport Key Interchange Protocol.","B":"Không phải Trusted Key Infrastructure Protocol.","C":"Không phải Timed Key Initialization Process."}},{"id":"abbr_c5_065","chapter":"5","question":"CCMP trong AES-CCMP của WPA2 là:","options":{"A":"Cipher Chain Management Protocol","B":"Central Certificate Management Protocol","C":"Counter Mode with CBC-MAC Protocol","D":"Combined Cipher and MAC Process"},"answer":"C","family":"ab_tkip","style":"acronym","section":"5.4","source":"Đề cương mục 5.1-5.5; slide Bài 5","explanation":"CCMP là Counter Mode with CBC-MAC Protocol.","optionNotes":{"A":"Không phải Cipher Chain Management Protocol.","B":"Không phải Central Certificate Management Protocol.","D":"Không phải Combined Cipher and MAC Process."}},{"id":"abbr_c5_066","chapter":"5","question":"PSK trong WPA2-PSK là:","options":{"A":"Private Session Key","B":"Public Signing Key","C":"Protected Station Key","D":"Pre-Shared Key"},"answer":"D","family":"ab_psk","style":"acronym","section":"5.4","source":"Đề cương mục 5.1-5.5; slide Bài 5","explanation":"PSK là Pre-Shared Key, khóa chia sẻ trước dùng chung.","optionNotes":{"A":"Không phải Private Session Key.","B":"Không phải Public Signing Key.","C":"Không phải Protected Station Key."}},{"id":"abbr_c5_067","chapter":"5","question":"SAE trong WPA3-Personal là:","options":{"A":"Simultaneous Authentication of Equals","B":"Secure AES Encryption","C":"Shared Access Exchange","D":"Station Authentication and Encryption"},"answer":"A","family":"ab_psk","style":"acronym","section":"5.4","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"SAE là Simultaneous Authentication of Equals, xác thực đồng thời giữa hai bên ngang hàng.","optionNotes":{"B":"Không phải Secure AES Encryption.","C":"Không phải Shared Access Exchange.","D":"Không phải Station Authentication and Encryption."}},{"id":"abbr_c5_068","chapter":"5","question":"PMF là viết tắt của:","options":{"A":"Protected Media Format","B":"Protected Management Frames","C":"Primary MAC Filter","D":"Pre-shared Master Frame"},"answer":"B","family":"ab_pmf","style":"acronym","section":"5.2","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"PMF là Protected Management Frames, bảo vệ khung quản lý.","optionNotes":{"A":"Không phải Protected Media Format.","C":"Không phải Primary MAC Filter.","D":"Không phải Pre-shared Master Frame."}},{"id":"abbr_c5_069","chapter":"5","question":"OWE (Enhanced Open) là:","options":{"A":"Optional WPA Encryption","B":"Offline Wi-Fi Enrollment","C":"Open Wireless Exchange","D":"Opportunistic Wireless Encryption"},"answer":"D","family":"abbr_c5_069","style":"acronym","section":"5.4","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"OWE là Opportunistic Wireless Encryption, mã hóa cơ hội cho mạng mở.","optionNotes":{"A":"Không phải Optional WPA Encryption.","B":"Không phải Offline Wi-Fi Enrollment.","C":"Không phải Open Wireless Exchange."}},{"id":"abbr_c5_070","chapter":"5","question":"EAP là viết tắt của:","options":{"A":"Extensible Authentication Protocol","B":"Encrypted Access Protocol","C":"External AP Protocol","D":"Enterprise Authorization Policy"},"answer":"A","family":"ab_eap","style":"acronym","section":"5.5","source":"Đề cương mục 5.1-5.5; slide Bài 5","explanation":"EAP là Extensible Authentication Protocol, khung xác thực mở rộng.","optionNotes":{"B":"Không phải Encrypted Access Protocol.","C":"Không phải External AP Protocol.","D":"Không phải Enterprise Authorization Policy."}},{"id":"abbr_c5_071","chapter":"5","question":"RADIUS là viết tắt của:","options":{"A":"Radio Access Domain Identity Service","B":"Remote Authentication Dial-In User Service","C":"Remote Access Directory Integration Unit","D":"Routing Authentication and Data Integrity Service"},"answer":"B","family":"ab_eap","style":"acronym","section":"5.5","source":"Đề cương mục 5.1-5.5; slide Bài 5","explanation":"RADIUS là Remote Authentication Dial-In User Service.","optionNotes":{"A":"Không phải Radio Access Domain Identity Service.","C":"Không phải Remote Access Directory Integration Unit.","D":"Không phải Routing Authentication and Data Integrity Service."}},{"id":"abbr_c5_072","chapter":"5","question":"AAA mà RADIUS cung cấp gồm:","options":{"A":"Association, Authentication, ACK","B":"Access, Audit, Alert","C":"Authentication, Authorization, Accounting","D":"Authentication, Availability, Anonymity"},"answer":"C","family":"abbr_c5_072","style":"acronym","section":"5.5","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"AAA là Authentication (xác thực), Authorization (phân quyền), Accounting (ghi nhận).","optionNotes":{"A":"Association, ACK là khái niệm WLAN, không phải AAA.","B":"Không phải Access, Audit, Alert.","D":"Availability, Anonymity không thuộc AAA."}},{"id":"abbr_c5_073","chapter":"5","question":"WPS, cơ chế nên tắt nếu không cần, là:","options":{"A":"Wi-Fi Privacy Service","B":"Wi-Fi Protected Setup","C":"WPA Pre-Shared","D":"Wireless Password Storage"},"answer":"B","family":"abbr_c5_073","style":"acronym","section":"5.2","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"WPS là Wi-Fi Protected Setup, cơ chế cài đặt nhanh bằng nút/PIN.","optionNotes":{"A":"Không phải Wi-Fi Privacy Service.","C":"Không phải WPA Pre-Shared.","D":"Không phải Wireless Password Storage."}},{"id":"abbr_c5_074","chapter":"5","question":"NAC trong thiết kế WLAN là:","options":{"A":"Network Authentication Certificate","B":"Network Alert Console","C":"Network Access Control","D":"Node Address Cache"},"answer":"C","family":"abbr_c5_074","style":"acronym","section":"5.5","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"NAC là Network Access Control, kiểm soát truy cập mạng.","optionNotes":{"A":"Không phải Network Authentication Certificate.","B":"Không phải Network Alert Console.","D":"Không phải Node Address Cache."}},{"id":"abbr_c5_075","chapter":"5","question":"Trong 4-Way Handshake, PMK là:","options":{"A":"Pairwise Master Key","B":"Public Master Key","C":"Protected Management Key","D":"Primary MAC Key"},"answer":"A","family":"ab_ptk","style":"acronym","section":"5.4","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"PMK là Pairwise Master Key, khóa chủ dùng để sinh khóa phiên trong 4-Way Handshake.","optionNotes":{"B":"P là Pairwise, không phải Public.","C":"Không phải Protected Management Key.","D":"Không phải Primary MAC Key."}},{"id":"abbr_c5_076","chapter":"5","question":"Khóa dùng cho lưu lượng broadcast/multicast được phân phối trong 4-Way Handshake là:","options":{"A":"PSK – Pre-Shared Key","B":"PTK – Pairwise Transient Key","C":"PMK – Pairwise Master Key","D":"GTK – Group Temporal Key"},"answer":"D","family":"ab_ptk","style":"acronym","section":"5.4","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"GTK (Group Temporal Key) là khóa nhóm cho broadcast/multicast, được AP gửi trong 4-Way Handshake.","optionNotes":{"A":"PSK là mật khẩu chung để sinh PMK, không phải khóa nhóm.","B":"PTK là khóa riêng cho từng cặp STA–AP (unicast).","C":"PMK là khóa chủ, không dùng trực tiếp cho broadcast."}},{"id":"abbr_c5_077","chapter":"5","question":"CSMA/CA trong WLAN là:","options":{"A":"Carrier Sense Multiple Access with Collision Authentication","B":"Carrier Sense Multiple Access with Collision Avoidance","C":"Channel Security Management with Certificate Authority","D":"Carrier Signal Modulation with Channel Allocation"},"answer":"B","family":"abbr_c5_077","style":"acronym","section":"5.1","source":"Đề cương mục 5.1-5.5; slide Bài 5","explanation":"CSMA/CA là Carrier Sense Multiple Access with Collision Avoidance (tránh xung đột).","optionNotes":{"A":"CA là Collision Avoidance, không phải Authentication.","C":"Không phải Channel Security Management with Certificate Authority.","D":"Không phải Carrier Signal Modulation with Channel Allocation."}},{"id":"std_c5_078","chapter":"5","question":"Theo slide, chuẩn IEEE quy định giao thức bảo mật trong WLAN là:","options":{"A":"IEEE 802.3","B":"IEEE 802.11ac","C":"IEEE 802.11i","D":"IEEE 802.11n"},"answer":"C","family":"std_80211","style":"standard","section":"5.1","source":"Đề cương mục 5.1-5.5; slide Bài 5","explanation":"IEEE 802.11i quy định các giao thức bảo mật WLAN (nền tảng của WPA2).","optionNotes":{"A":"802.3 là Ethernet có dây.","B":"802.11ac là chuẩn tốc độ (Wi-Fi 5).","D":"802.11n là chuẩn tốc độ (Wi-Fi 4)."}},{"id":"std_c5_079","chapter":"5","question":"PMF được chuẩn hóa trong:","options":{"A":"IEEE 802.11be","B":"IEEE 802.11g","C":"IEEE 802.1Q","D":"IEEE 802.11w"},"answer":"D","family":"std_80211","style":"standard","section":"5.1","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"PMF được chuẩn hóa trong IEEE 802.11w.","optionNotes":{"A":"802.11be là Wi-Fi 7.","B":"802.11g là chuẩn tốc độ cũ 54 Mbps.","C":"802.1Q là chuẩn VLAN."}},{"id":"std_c5_080","chapter":"5","question":"Wi-Fi 6 tương ứng với chuẩn:","options":{"A":"IEEE 802.11ax","B":"IEEE 802.11ac","C":"IEEE 802.11be","D":"IEEE 802.11n"},"answer":"A","family":"std_wifi_gen","style":"standard","section":"5.1","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"Wi-Fi 6 là IEEE 802.11ax.","optionNotes":{"B":"802.11ac là Wi-Fi 5.","C":"802.11be là Wi-Fi 7.","D":"802.11n là Wi-Fi 4."}},{"id":"std_c5_081","chapter":"5","question":"Wi-Fi 7 tương ứng với chuẩn:","options":{"A":"IEEE 802.11ac","B":"IEEE 802.11be","C":"IEEE 802.11i","D":"IEEE 802.11ax"},"answer":"B","family":"std_wifi_gen","style":"standard","section":"5.1","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"Wi-Fi 7 là IEEE 802.11be.","optionNotes":{"A":"802.11ac là Wi-Fi 5.","C":"802.11i là chuẩn bảo mật.","D":"802.11ax là Wi-Fi 6."}},{"id":"std_c5_082","chapter":"5","question":"Theo slide, nâng cấp từ Wi-Fi 6 lên Wi-Fi 7:","options":{"A":"Chủ yếu cải tiến PHY/MAC, không tự an toàn hơn","B":"Chống được mọi kiểu gây nhiễu RF","C":"Tự động thay thế WPA3 bằng cơ chế mới","D":"Loại bỏ nhu cầu dùng 802.1X và PMF"},"answer":"A","family":"std_wifi_gen","style":"standard","section":"5.1","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"Slide nói Wi-Fi 7 chủ yếu cải tiến PHY/MAC (tốc độ, độ trễ), không tự làm mạng an toàn hơn.","optionNotes":{"B":"Không chuẩn nào chống được mọi kiểu gây nhiễu.","C":"Wi-Fi 7 vẫn dùng WPA3.","D":"Vẫn cần 802.1X và PMF."}},{"id":"std_c5_083","chapter":"5","question":"Chuẩn IEEE 802.11 gốc được ban hành năm:","options":{"A":"2004","B":"1999","C":"1997","D":"2009"},"answer":"C","family":"std_c5_083","style":"standard","section":"5.1","source":"Đề cương mục 5.1-5.5; slide Bài 5","explanation":"Chuẩn IEEE 802.11 gốc ban hành năm 1997.","optionNotes":{"A":"2004 là năm WPA2 (802.11i).","B":"1999 là năm 802.11a/b, không phải bản gốc.","D":"2009 là năm 802.11n."}},{"id":"std_c5_084","chapter":"5","question":"WPA2 được chuẩn hóa năm 2004 và dùng cơ chế mã hóa:","options":{"A":"TKIP","B":"SAE + OWE","C":"RC4 + IV 24 bit","D":"AES-CCMP"},"answer":"D","family":"std_wpa_ver","style":"standard","section":"5.4","source":"Đề cương mục 5.1-5.5; slide Bài 5","explanation":"WPA2 dùng AES-CCMP.","optionNotes":{"A":"TKIP là của WPA.","B":"SAE và OWE là của WPA3/Enhanced Open.","C":"RC4 + IV 24 bit là WEP."}},{"id":"std_c5_085","chapter":"5","question":"Thành phần bắt buộc trong chứng nhận WPA3 theo slide là:","options":{"A":"Khóa WEP chia sẻ","B":"WPS PIN","C":"TKIP","D":"PMF"},"answer":"D","family":"std_wpa_ver","style":"standard","section":"5.4","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"Slide nêu PMF là bắt buộc trong chứng nhận WPA3.","optionNotes":{"A":"WPA3 không dùng khóa WEP.","B":"WPS PIN không bắt buộc và nên tắt.","C":"TKIP không có trong WPA3."}},{"id":"std_c5_086","chapter":"5","question":"Theo slide, khóa WEP có độ dài:","options":{"A":"56 bit kèm salt","B":"40/104 bit kèm IV","C":"192 bit kèm PMK","D":"128/256 bit kèm nonce"},"answer":"B","family":"std_c5_086","style":"standard","section":"5.3","source":"Đề cương mục 5.1-5.5; slide Bài 5","explanation":"Khóa WEP dài 40 hoặc 104 bit, ghép với IV 24 bit (thành 64/128 bit).","optionNotes":{"A":"56 bit là độ dài khóa DES.","C":"192 bit kèm PMK không phải WEP.","D":"128/256 bit kèm nonce không phải WEP."}},{"id":"std_c5_087","chapter":"5","question":"Vai trò lần lượt của 802.1X, EAP và RADIUS là:","options":{"A":"Dịch vụ AAA – thuật toán mã hóa – lọc gói tin tại AP","B":"Khung xác thực – mã hóa – định tuyến","C":"Kiểm soát theo cổng – khung xác thực – dịch vụ AAA","D":"Mã hóa khung – hàm băm – chữ ký số"},"answer":"C","family":"std_8021x","style":"standard","section":"5.5","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"802.1X kiểm soát truy cập theo cổng, EAP là khung xác thực, RADIUS cung cấp dịch vụ AAA.","optionNotes":{"A":"802.1X không phải dịch vụ AAA, EAP không phải thuật toán mã hóa.","B":"EAP không mã hóa, RADIUS không định tuyến.","D":"Không cái nào trong ba là mã hóa khung, hàm băm hay chữ ký số."}},{"id":"std_c5_088","chapter":"5","question":"Theo slide, 802.1X là:","options":{"A":"Cơ chế kiểm soát truy cập theo cổng","B":"Chuẩn tốc độ của Wi-Fi 6","C":"Giao thức cấp địa chỉ IP động","D":"Thuật toán mã hóa khung Wi-Fi"},"answer":"A","family":"std_8021x","style":"standard","section":"5.5","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"802.1X là cơ chế kiểm soát truy cập theo cổng (port-based).","optionNotes":{"B":"Chuẩn tốc độ Wi-Fi 6 là 802.11ax.","C":"Cấp IP động là DHCP.","D":"802.1X không mã hóa khung."}},{"id":"std_c5_089","chapter":"5","question":"KRACK khai thác:","options":{"A":"Mã PIN WPS quá ngắn","B":"Lỗi cài lại khóa trong 4-Way Handshake","C":"Việc phá trực tiếp thuật toán AES","D":"Khung beacon không được mã hóa"},"answer":"B","family":"std_c5_089","style":"standard","section":"5.4","source":"Đề cương mục 5.1-5.5; slide Bài 5 bản cập nhật","explanation":"KRACK khai thác lỗi cài lại khóa (key reinstallation) trong 4-Way Handshake.","optionNotes":{"A":"Dò PIN WPS là tấn công khác.","C":"KRACK không phá AES.","D":"Beacon không mã hóa là bình thường, không phải điểm KRACK khai thác."}},{"id":"gen_431","chapter":"6","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Nhóm đánh giá ưu tiên bảo vệ cơ sở dữ liệu điểm thi?","options":{"A":"ISMS","B":"Đánh giá rủi ro","C":"ISO/IEC 27001:2005","D":"ISO/IEC 27002:2005"},"answer":"B","family":"g36c4","style":"scenario","section":"6.1-6.2","source":"Đề cương mục 6.1-6.2; slide Bài 6","explanation":"Xác định tài sản quan trọng nhất (CSDL điểm thi) để ưu tiên bảo vệ là việc của đánh giá rủi ro.","optionNotes":{"A":"ISMS là cả hệ thống quản lý; tình huống chỉ là một bước bên trong nó.","C":"27001 là tiêu chuẩn yêu cầu cho ISMS, không phải hoạt động ưu tiên tài sản.","D":"27002 là danh mục biện pháp kiểm soát, không phải hoạt động đánh giá."}},{"id":"gen_434","chapter":"6","question":"Xét tình huống: Một thiết bị được đánh giá theo Common Criteria. Cách gọi đúng là gì?","options":{"A":"ISO/IEC 13335","B":"EAL","C":"TOE","D":"ISO/IEC 15408"},"answer":"D","family":"g37c1","style":"scenario","section":"6.3-6.4","source":"Đề cương mục 6.3-6.4; slide Bài 6","explanation":"Common Criteria chính là ISO/IEC 15408, chuẩn đánh giá sản phẩm CNTT.","optionNotes":{"A":"13335 là hướng dẫn quản lý an ninh CNTT, không phải Common Criteria.","B":"EAL là cấp bảo đảm, kết quả của đánh giá, không phải tên chuẩn.","C":"TOE là đối tượng được đánh giá, không phải tên chuẩn."}},{"id":"gen_440","chapter":"6","question":"Trong ví dụ sau, khái niệm nào được thể hiện: Báo cáo thiết bị ghi một cấp bảo đảm sau quy trình thẩm định?","options":{"A":"ISO/IEC 15408","B":"ISO/IEC 13335","C":"EAL","D":"TOE"},"answer":"C","family":"g37c3","style":"scenario","section":"6.3-6.4","source":"Đề cương mục 6.3-6.4; slide Bài 6","explanation":"Cấp bảo đảm ghi sau khi thẩm định theo Common Criteria là EAL (Evaluation Assurance Level).","optionNotes":{"A":"15408 là tên chuẩn, còn cấp ghi trong báo cáo là EAL.","B":"13335 không cấp mức bảo đảm cho thiết bị.","D":"TOE là đối tượng được đánh giá, không phải cấp bảo đảm."}},{"id":"gen_443","chapter":"6","question":"Chứng nhận chỉ áp dụng cho phiên bản thiết bị đã xác định. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"EAL","B":"ISO/IEC 13335","C":"ISO/IEC 15408","D":"TOE"},"answer":"D","family":"g37c4","style":"scenario","section":"6.3-6.4","source":"Đề cương mục 6.3-6.4; slide Bài 6","explanation":"Chứng nhận chỉ gắn với đúng phiên bản thiết bị được đánh giá, tức TOE (Target of Evaluation).","optionNotes":{"A":"EAL là mức bảo đảm, không xác định phạm vi phiên bản.","B":"13335 không liên quan chứng nhận sản phẩm.","C":"15408 là chuẩn; phần xác định đúng thứ được đánh giá là TOE."}},{"id":"gen_452","chapter":"6","question":"HSM giữ khóa và thực hiện phép ký là một ví dụ. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"PCI DSS","B":"Mô-đun mật mã","C":"Dữ liệu chủ thẻ","D":"FIPS 140-2"},"answer":"B","family":"g38c3","style":"scenario","section":"6.5-6.6","source":"Đề cương mục 6.5-6.6; slide Bài 6","explanation":"HSM giữ khóa và thực hiện phép ký là một mô-đun mật mã.","optionNotes":{"A":"PCI DSS là chuẩn cho môi trường dữ liệu thẻ, không phải thiết bị.","C":"Dữ liệu chủ thẻ là thông tin thẻ của khách hàng.","D":"FIPS 140-2 là chuẩn đánh giá mô-đun mật mã, còn HSM là chính mô-đun đó."}},{"id":"gen_455","chapter":"6","question":"Xét tình huống: Cửa hàng lưu số thẻ thanh toán của khách. Cách gọi đúng là gì?","options":{"A":"FIPS 140-2","B":"Dữ liệu chủ thẻ","C":"Mô-đun mật mã","D":"PCI DSS"},"answer":"B","family":"g38c4","style":"scenario","section":"6.5-6.6","source":"Đề cương mục 6.5-6.6; slide Bài 6","explanation":"Số thẻ thanh toán của khách là dữ liệu chủ thẻ (cardholder data).","optionNotes":{"A":"FIPS 140-2 là chuẩn mô-đun mật mã.","C":"Mô-đun mật mã là thiết bị/phần mềm mã hóa.","D":"PCI DSS là chuẩn bảo vệ dữ liệu này, không phải tên của dữ liệu."}},{"id":"gen_461","chapter":"6","question":"Hệ thống tuyển sinh lưu họ tên và liên hệ người nộp hồ sơ. Trường hợp này phù hợp với khái niệm nào?","options":{"A":"Luật An toàn thông tin mạng 2015","B":"Phòng chống thư rác","C":"Ứng cứu sự cố ATTT","D":"Bảo vệ thông tin cá nhân"},"answer":"D","family":"g39c2","style":"scenario","section":"6.7","source":"Đề cương mục 6.7; slide Bài 6","explanation":"Họ tên và thông tin liên hệ là thông tin cá nhân, nên áp dụng nội dung bảo vệ thông tin cá nhân.","optionNotes":{"A":"Luật ATTT mạng 2015 là cả bộ luật; nội dung cụ thể áp dụng ở đây là bảo vệ thông tin cá nhân.","B":"Tình huống không nói về thư rác.","C":"Tình huống không có sự cố cần ứng cứu."}},{"id":"gen_464","chapter":"6","question":"Xét tình huống: Người dùng nhận hàng loạt email quảng cáo trái phép. Cách gọi đúng là gì?","options":{"A":"Phòng chống thư rác","B":"Luật An toàn thông tin mạng 2015","C":"Ứng cứu sự cố ATTT","D":"Bảo vệ thông tin cá nhân"},"answer":"A","family":"g39c3","style":"scenario","section":"6.7","source":"Đề cương mục 6.7; slide Bài 6","explanation":"Email quảng cáo trái phép hàng loạt thuộc nội dung phòng chống thư rác.","optionNotes":{"B":"Luật là cả bộ; nội dung cụ thể là phòng chống thư rác.","C":"Thư rác không phải sự cố cần ứng cứu.","D":"Tình huống không nói về xử lý thông tin cá nhân."}},{"id":"gen_467","chapter":"6","question":"Nếu đơn vị cô lập máy chủ bị xâm nhập rồi khôi phục dịch vụ, hiện tượng nào đang xảy ra?","options":{"A":"Bảo vệ thông tin cá nhân","B":"Luật An toàn thông tin mạng 2015","C":"Ứng cứu sự cố ATTT","D":"Phòng chống thư rác"},"answer":"C","family":"g39c4","style":"scenario","section":"6.7","source":"Đề cương mục 6.7; slide Bài 6","explanation":"Cô lập máy bị xâm nhập rồi khôi phục dịch vụ là ứng cứu sự cố ATTT.","optionNotes":{"A":"Tình huống không nói về thông tin cá nhân.","B":"Luật là cả bộ; hoạt động cụ thể là ứng cứu sự cố.","D":"Tình huống không liên quan thư rác."}},{"id":"case_51","chapter":"6","question":"Theo slide Bài 6, tổ chức muốn được đánh giá chứng nhận hệ thống quản lý an toàn thông tin. Tiêu chuẩn yêu cầu phù hợp là gì?","options":{"A":"ISO/IEC 15408","B":"ISO/IEC 27002:2005","C":"ISO/IEC 27001:2005","D":"FIPS 140-2"},"answer":"C","family":"g36c1","style":"application","section":"6.1-6.2","source":"Đề cương mục 6.1-6.2; slide Bài 6","explanation":"ISO/IEC 27001:2005 nêu yêu cầu cho ISMS và là tiêu chuẩn dùng để đánh giá chứng nhận.","optionNotes":{"A":"15408 đánh giá sản phẩm, không chứng nhận ISMS.","B":"27002 chỉ hướng dẫn biện pháp, không dùng để chứng nhận.","D":"FIPS 140-2 đánh giá mô-đun mật mã."}},{"id":"case_52","chapter":"6","question":"Theo slide Bài 6, tổ chức cần hướng dẫn các biện pháp kiểm soát an toàn thông tin nhưng không tìm một tiêu chuẩn chứng nhận ISMS. Tài liệu nào phù hợp?","options":{"A":"ISO/IEC 27002:2005","B":"PCI DSS","C":"FIPS 140-2","D":"ISO/IEC 27001:2005"},"answer":"A","family":"g36c2","style":"application","section":"6.1-6.2","source":"Đề cương mục 6.1-6.2; slide Bài 6","explanation":"ISO/IEC 27002:2005 là bộ hướng dẫn biện pháp kiểm soát, không dùng để chứng nhận ISMS.","optionNotes":{"B":"PCI DSS dành riêng cho dữ liệu thẻ.","C":"FIPS 140-2 dành cho mô-đun mật mã.","D":"27001 là tiêu chuẩn chứng nhận ISMS, trái với yêu cầu."}},{"id":"case_53","chapter":"6","question":"Một sản phẩm firewall cần đánh giá mức bảo đảm an ninh của chính sản phẩm, không phải chứng nhận ISMS của cả tổ chức. Chuẩn nào phù hợp?","options":{"A":"PCI DSS","B":"ISO/IEC 27002:2005","C":"ISO/IEC 27001:2005","D":"ISO/IEC 15408 (Common Criteria)"},"answer":"D","family":"case_53","style":"application","section":"6.3","source":"Đề cương mục 6.3; slide Bài 6","explanation":"Đánh giá mức bảo đảm an ninh của chính một sản phẩm dùng ISO/IEC 15408 (Common Criteria).","optionNotes":{"A":"PCI DSS là chuẩn môi trường thẻ.","B":"27002 hướng dẫn biện pháp cho tổ chức.","C":"27001 chứng nhận ISMS của tổ chức, không phải sản phẩm."}},{"id":"case_54","chapter":"6","question":"Theo slide Bài 6, nhóm cần bộ hướng dẫn quản lý an ninh CNTT tập trung vào quản lý rủi ro và lập kế hoạch bảo mật tổng thể, không phải kiểm định mô-đun mật mã. Chuẩn nào phù hợp?","options":{"A":"ISO/IEC 13335","B":"PCI DSS","C":"FIPS 140-2","D":"ISO/IEC 15408"},"answer":"A","family":"g37c2","style":"application","section":"6.4","source":"Đề cương mục 6.4; slide Bài 6","explanation":"Slide mô tả ISO/IEC 13335 là hướng dẫn quản lý an ninh CNTT, tập trung vào quản lý rủi ro và lập kế hoạch bảo mật tổng thể.","optionNotes":{"B":"PCI DSS dành cho dữ liệu thẻ.","C":"FIPS 140-2 kiểm định mô-đun mật mã, câu hỏi đã loại trừ.","D":"15408 đánh giá sản phẩm."}},{"id":"case_55","chapter":"6","question":"Đơn vị xử lý dữ liệu thẻ thanh toán cần đối chiếu yêu cầu an ninh chuyên cho môi trường thẻ. Bộ chuẩn nào phù hợp?","options":{"A":"FIPS 140-2","B":"PCI DSS","C":"ISO/IEC 13335","D":"ISO/IEC 15408"},"answer":"B","family":"g38c1","style":"application","section":"6.5","source":"Đề cương mục 6.5; slide Bài 6","explanation":"Môi trường xử lý dữ liệu thẻ thanh toán áp dụng PCI DSS.","optionNotes":{"A":"FIPS 140-2 chỉ cho mô-đun mật mã.","C":"13335 là hướng dẫn quản lý chung, không riêng cho thẻ.","D":"15408 đánh giá sản phẩm."}},{"id":"case_56","chapter":"6","question":"Cần đánh giá mô-đun mật mã thay vì toàn bộ tổ chức hoặc ứng dụng thanh toán. Chuẩn nào phù hợp?","options":{"A":"ISO/IEC 27001:2005","B":"FIPS 140-2","C":"PCI DSS","D":"ISO/IEC 27002:2005"},"answer":"B","family":"g38c2","style":"application","section":"6.6","source":"Đề cương mục 6.6; slide Bài 6","explanation":"Đánh giá mô-đun mật mã dùng FIPS 140-2.","optionNotes":{"A":"27001 chứng nhận ISMS của tổ chức.","C":"PCI DSS cho môi trường thẻ thanh toán.","D":"27002 hướng dẫn biện pháp cho tổ chức."}},{"id":"case_57","chapter":"6","question":"Theo slide Bài 6, điểm khác biệt quan trọng giữa ISO/IEC 27001 và 27002 là gì?","options":{"A":"27001 nêu yêu cầu có thể chứng nhận ISMS; 27002 hướng dẫn kiểm soát","B":"Hai tiêu chuẩn chỉ áp dụng cho mô-đun mật mã","C":"Cả hai đều là chuẩn riêng của thẻ thanh toán","D":"27002 chứng nhận ISMS; 27001 chỉ hướng dẫn tùy chọn"},"answer":"A","family":"case_57","style":"application","section":"6.1-6.2","source":"Đề cương mục 6.1-6.2; slide Bài 6","explanation":"27001 là yêu cầu để chứng nhận ISMS; 27002 là hướng dẫn chi tiết các biện pháp kiểm soát.","optionNotes":{"B":"Cả hai dành cho tổ chức, không chỉ mô-đun mật mã.","C":"Chuẩn riêng cho thẻ là PCI DSS.","D":"Đảo ngược vai trò: 27001 mới là chuẩn chứng nhận."}},{"id":"case_58","chapter":"6","question":"Tổ chức đã mua firewall nhưng chưa xác định phạm vi ISMS và chưa đánh giá rủi ro. Theo slide về ISO/IEC 27001, bước nào còn thiếu?","options":{"A":"Chỉ tăng băng thông firewall","B":"Bỏ ghi chép chính sách và quy trình","C":"Mặc định cấp quyền quản trị cho mọi nhân viên","D":"Xác định phạm vi và đánh giá rủi ro trước khi chọn kiểm soát"},"answer":"D","family":"case_58","style":"application","section":"6.2","source":"Đề cương mục 6.2; slide Bài 6","explanation":"27001 yêu cầu xác định phạm vi ISMS và đánh giá rủi ro trước, rồi mới chọn biện pháp kiểm soát như firewall.","optionNotes":{"A":"Băng thông không phải bước của ISMS.","B":"ISMS cần tài liệu hóa chính sách, không bỏ.","C":"Cấp quyền quản trị cho mọi người trái nguyên tắc bảo mật."}},{"id":"case_59","chapter":"6","question":"Theo Common Criteria trong slide, tài liệu mô tả mục tiêu bảo mật cụ thể của sản phẩm cần đánh giá là gì?","options":{"A":"Payment Card Industry Data Security Standard","B":"Intrusion Prevention System","C":"Security Target","D":"Service Set Identifier"},"answer":"C","family":"case_59","style":"application","section":"6.3","source":"Đề cương mục 6.3; slide Bài 6","explanation":"Security Target (ST) là tài liệu mô tả mục tiêu bảo mật cụ thể của sản phẩm được đánh giá.","optionNotes":{"A":"Đó là tên đầy đủ của PCI DSS.","B":"Đó là tên đầy đủ của IPS.","D":"Đó là tên đầy đủ của SSID."}},{"id":"case_60","chapter":"6","question":"Một đơn vị thu thập thông tin cá nhân nhưng chỉ chú ý chống virus, không xét việc sử dụng dữ liệu. Nội dung nào trong phần luật an toàn thông tin cần được lưu ý thêm?","options":{"A":"Chỉ thay đổi SSID của mạng","B":"Bảo vệ thông tin cá nhân trong quá trình xử lý","C":"Chỉ tắt log truy cập","D":"Chỉ tăng số cổng mở trên firewall"},"answer":"B","family":"case_60","style":"application","section":"6.7","source":"Đề cương mục 6.7; slide Bài 6","explanation":"Thu thập thông tin cá nhân thì phải bảo vệ nó trong cả quá trình xử lý, không chỉ chống virus.","optionNotes":{"A":"SSID không liên quan dữ liệu cá nhân.","C":"Tắt log làm khó chứng minh tuân thủ.","D":"Mở thêm cổng làm tăng rủi ro."}},{"id":"std_c6_090","chapter":"6","question":"ISO/IEC 27002:2005 gồm:","options":{"A":"11 lĩnh vực, 39 mục tiêu, 133 biện pháp","B":"4 nhóm, 93 biện pháp, 5 thuộc tính","C":"6 chức năng, 22 nhóm, 106 tiểu mục","D":"14 lĩnh vực, 35 mục tiêu, 114 biện pháp"},"answer":"A","family":"std_27002_ver","style":"standard","section":"6.1","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cũ","explanation":"ISO/IEC 27002:2005 có 11 lĩnh vực, 39 mục tiêu, 133 biện pháp.","optionNotes":{"B":"4 nhóm, 93 biện pháp, 5 thuộc tính là bản 2022.","C":"6 chức năng, 22 nhóm, 106 tiểu mục là NIST CSF 2.0.","D":"14 lĩnh vực, 35 mục tiêu, 114 biện pháp là bản 2013."}},{"id":"std_c6_091","chapter":"6","question":"ISO/IEC 27002:2013 gồm:","options":{"A":"4 nhóm, 93 biện pháp, 5 thuộc tính","B":"6 chức năng, 22 nhóm, 106 tiểu mục","C":"11 lĩnh vực, 39 mục tiêu, 133 biện pháp","D":"14 lĩnh vực, 35 mục tiêu, 114 biện pháp"},"answer":"D","family":"std_27002_ver","style":"standard","section":"6.1","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"ISO/IEC 27002:2013 có 14 lĩnh vực, 35 mục tiêu, 114 biện pháp.","optionNotes":{"A":"4 nhóm, 93 biện pháp là bản 2022.","B":"6 chức năng, 22 nhóm, 106 tiểu mục là NIST CSF 2.0.","C":"11 lĩnh vực, 133 biện pháp là bản 2005."}},{"id":"std_c6_092","chapter":"6","question":"ISO/IEC 27002:2022 gồm:","options":{"A":"11 lĩnh vực, 39 mục tiêu, 133 biện pháp","B":"6 chức năng, 22 nhóm, 106 tiểu mục","C":"4 nhóm, 93 biện pháp, 5 thuộc tính","D":"14 lĩnh vực, 35 mục tiêu, 114 biện pháp"},"answer":"C","family":"std_27002_ver","style":"standard","section":"6.1","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"ISO/IEC 27002:2022 có 4 nhóm, 93 biện pháp, 5 thuộc tính.","optionNotes":{"A":"11 lĩnh vực, 133 biện pháp là bản 2005.","B":"6 chức năng, 22 nhóm, 106 tiểu mục là NIST CSF 2.0.","D":"14 lĩnh vực, 114 biện pháp là bản 2013."}},{"id":"std_c6_093","chapter":"6","question":"Con số \"Phụ lục A gồm 114 biện pháp\" chỉ đúng với:","options":{"A":"ISO/IEC 27001:2022","B":"ISO/IEC 27001:2013","C":"ISO/IEC 27001:2005","D":"ISO/IEC 27002:2022"},"answer":"B","family":"std_annex_a","style":"standard","section":"6.2","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"114 biện pháp trong Phụ lục A là của ISO/IEC 27001:2013.","optionNotes":{"A":"Bản 2022 có 93 biện pháp.","C":"Bản 2005 có 133 biện pháp.","D":"27002:2022 cũng là 93 biện pháp, và 27002 không có \"Phụ lục A\"."}},{"id":"std_c6_094","chapter":"6","question":"Bốn nhóm biện pháp của ISO/IEC 27002:2022 là:","options":{"A":"Nhận diện, Bảo vệ, Phát hiện, Ứng phó","B":"Chính sách, Tài sản, Nhân sự, Tuân thủ","C":"Tổ chức, Con người, Vật lý, Công nghệ","D":"Kế hoạch, Thực hiện, Kiểm tra, Hành động"},"answer":"C","family":"std_c6_094","style":"standard","section":"6.1","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"Bốn nhóm của 27002:2022 là Tổ chức, Con người, Vật lý, Công nghệ.","optionNotes":{"A":"Nhận diện, Bảo vệ, Phát hiện, Ứng phó là các chức năng của NIST CSF.","B":"Không phải cách chia nhóm của bản 2022.","D":"Kế hoạch – Thực hiện – Kiểm tra – Hành động là chu trình PDCA."}},{"id":"abbr_c6_095","chapter":"6","question":"ISMS là viết tắt của:","options":{"A":"Information Security Management System","B":"Information Systems Management Service","C":"Internet Security Monitoring Service","D":"Integrated Security Module Standard"},"answer":"A","family":"abbr_c6_095","style":"acronym","section":"6.2","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cũ","explanation":"ISMS là Information Security Management System, hệ thống quản lý an toàn thông tin.","optionNotes":{"B":"Không phải Information Systems Management Service.","C":"Không phải Internet Security Monitoring Service.","D":"Không phải Integrated Security Module Standard."}},{"id":"std_c6_096","chapter":"6","question":"Tiêu chuẩn dùng để cấp chứng nhận ISMS cho tổ chức là:","options":{"A":"ISO/IEC 27005","B":"NIST CSF 2.0","C":"ISO/IEC 27002","D":"ISO/IEC 27001"},"answer":"D","family":"g36c1","style":"standard","section":"6.2","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"ISO/IEC 27001 là tiêu chuẩn dùng để cấp chứng nhận ISMS.","optionNotes":{"A":"27005 hướng dẫn quản lý rủi ro.","B":"NIST CSF là khung tự nguyện, không cấp chứng nhận.","C":"27002 hướng dẫn biện pháp, không chứng nhận."}},{"id":"std_c6_097","chapter":"6","question":"SoA trong ISO/IEC 27001 là:","options":{"A":"Hợp đồng với nhà cung cấp dịch vụ cloud","B":"Danh mục tài sản phần cứng của tổ chức","C":"Báo cáo kiểm thử xâm nhập hằng năm","D":"Tuyên bố áp dụng các biện pháp Phụ lục A"},"answer":"D","family":"std_c6_097","style":"standard","section":"6.2","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"SoA (Statement of Applicability) là tuyên bố áp dụng: biện pháp nào trong Phụ lục A được dùng và vì sao.","optionNotes":{"A":"SoA không phải hợp đồng cloud.","B":"Danh mục tài sản là một tài liệu khác.","C":"Báo cáo kiểm thử xâm nhập không phải SoA."}},{"id":"std_c6_098","chapter":"6","question":"PDCA trong ISO/IEC 27001 là chu trình:","options":{"A":"Prepare – Deploy – Correct – Assess","B":"Policy – Design – Control – Audit","C":"Plan – Do – Check – Act","D":"Protect – Detect – Contain – Analyze"},"answer":"C","family":"std_pdca","style":"standard","section":"6.2","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"PDCA là Plan – Do – Check – Act.","optionNotes":{"A":"Không phải Prepare – Deploy – Correct – Assess.","B":"Không phải Policy – Design – Control – Audit.","D":"Không phải Protect – Detect – Contain – Analyze."}},{"id":"std_c6_099","chapter":"6","question":"Trong ISO/IEC 27001:2022, Điều 9 \"Đánh giá kết quả\" thuộc pha:","options":{"A":"PLAN","B":"CHECK","C":"DO","D":"ACT"},"answer":"B","family":"std_pdca","style":"standard","section":"6.2","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"Điều 9 \"Đánh giá kết quả\" (giám sát, đánh giá nội bộ, xem xét lãnh đạo) thuộc pha CHECK.","optionNotes":{"A":"PLAN ứng với Điều 4–7 (bối cảnh, lãnh đạo, hoạch định, hỗ trợ).","C":"DO ứng với Điều 8 (vận hành).","D":"ACT ứng với Điều 10 (cải tiến)."}},{"id":"std_c6_100","chapter":"6","question":"Theo slide, chứng chỉ ISO/IEC 27001 có hiệu lực:","options":{"A":"3 năm, giám sát hằng năm","B":"Vĩnh viễn sau giai đoạn 2","C":"5 năm, giám sát 2 năm/lần","D":"1 năm, không cần giám sát"},"answer":"A","family":"std_c6_100","style":"standard","section":"6.2","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"Chứng chỉ 27001 có hiệu lực 3 năm, với đánh giá giám sát hằng năm.","optionNotes":{"B":"Chứng chỉ không vĩnh viễn; hết 3 năm phải tái chứng nhận.","C":"Không phải 5 năm.","D":"Không phải 1 năm, và vẫn cần giám sát."}},{"id":"std_c6_101","chapter":"6","question":"ISO/IEC 13335 theo slide cập nhật hiện nay:","options":{"A":"Đã thay ISO/IEC 27001 để cấp chứng nhận ISMS hiện nay","B":"Là chuẩn ngành thẻ thanh toán bắt buộc","C":"Đã bị thu hồi; phần rủi ro kế thừa trong 27005","D":"Là chuẩn đánh giá mô-đun mật mã của NIST"},"answer":"C","family":"std_27005","style":"standard","section":"6.4","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"Slide cập nhật ghi ISO/IEC 13335 đã bị thu hồi; phần quản lý rủi ro được kế thừa trong 27005.","optionNotes":{"A":"Chuẩn chứng nhận ISMS hiện nay vẫn là 27001.","B":"Chuẩn thẻ thanh toán là PCI DSS.","D":"Chuẩn mô-đun mật mã của NIST là FIPS 140."}},{"id":"std_c6_102","chapter":"6","question":"ISO/IEC 27005 hướng dẫn về:","options":{"A":"Đánh giá mô-đun mật mã","B":"Quản lý rủi ro an toàn thông tin","C":"Bảo vệ dữ liệu cá nhân trên cloud","D":"Yêu cầu chứng nhận ISMS"},"answer":"B","family":"std_27005","style":"standard","section":"6.4","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"ISO/IEC 27005 hướng dẫn quản lý rủi ro an toàn thông tin.","optionNotes":{"A":"Đánh giá mô-đun mật mã là FIPS 140.","C":"Bảo vệ dữ liệu cá nhân là 27701 (và 27018 cho cloud).","D":"Yêu cầu chứng nhận ISMS là 27001."}},{"id":"std_c6_103","chapter":"6","question":"Bốn phương án xử lý rủi ro theo ISO/IEC 27005 là:","options":{"A":"Mã hóa, sao lưu, ghi log, xác thực","B":"Phát hiện, ngăn chặn, khôi phục, báo cáo","C":"Lập kế hoạch, thực hiện, kiểm tra, cải tiến","D":"Giảm thiểu, tránh, chia sẻ, chấp nhận"},"answer":"D","family":"std_c6_103","style":"standard","section":"6.4","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"27005 có bốn cách xử lý rủi ro: giảm thiểu, tránh, chia sẻ (chuyển giao), chấp nhận.","optionNotes":{"A":"Đó là các biện pháp kỹ thuật, không phải phương án xử lý rủi ro.","B":"Đó là các giai đoạn xử lý sự cố.","C":"Đó là chu trình PDCA."}},{"id":"std_c6_104","chapter":"6","question":"ISO/IEC 15408 còn được gọi là:","options":{"A":"Common Criteria","B":"Cybersecurity Framework","C":"Code of Practice","D":"Data Security Standard"},"answer":"A","family":"std_cc","style":"standard","section":"6.3","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cũ","explanation":"ISO/IEC 15408 còn gọi là Common Criteria.","optionNotes":{"B":"Cybersecurity Framework là NIST CSF.","C":"Code of Practice là tên gọi của 27002.","D":"Data Security Standard là phần DSS trong PCI DSS."}},{"id":"abbr_c6_105","chapter":"6","question":"TOE trong Common Criteria là:","options":{"A":"Test of Encryption – kiểm thử mã hóa","B":"Trust of Entity – độ tin cậy thực thể","C":"Type of Exposure – loại phơi nhiễm","D":"Target of Evaluation – đối tượng được đánh giá"},"answer":"D","family":"std_cc","style":"acronym","section":"6.3","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"TOE là Target of Evaluation, đối tượng (sản phẩm/phiên bản) được đánh giá.","optionNotes":{"A":"Không phải Test of Encryption.","B":"Không phải Trust of Entity.","C":"Không phải Type of Exposure."}},{"id":"std_c6_106","chapter":"6","question":"PP và ST trong Common Criteria lần lượt là:","options":{"A":"Hồ sơ thanh toán – mục tiêu chiến lược của tổ chức","B":"Yêu cầu chung cho loại sản phẩm – tuyên bố của sản phẩm cụ thể","C":"Chính sách mật khẩu – kịch bản kiểm thử bảo mật","D":"Tuyên bố của sản phẩm cụ thể – yêu cầu chung cho loại sản phẩm"},"answer":"B","family":"std_c6_106","style":"standard","section":"6.3","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cũ","explanation":"PP (Protection Profile) là yêu cầu chung cho một loại sản phẩm; ST (Security Target) là tuyên bố của một sản phẩm cụ thể.","optionNotes":{"A":"PP không phải hồ sơ thanh toán.","C":"PP không phải chính sách mật khẩu.","D":"Đảo ngược vai trò của PP và ST."}},{"id":"abbr_c6_107","chapter":"6","question":"EAL trong Common Criteria là:","options":{"A":"Evaluation Assurance Level","B":"Encryption Algorithm Level","C":"Enterprise Access Layer","D":"Event Alert Log"},"answer":"A","family":"std_eal","style":"acronym","section":"6.3","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"EAL là Evaluation Assurance Level, cấp bảo đảm đánh giá (EAL1–EAL7).","optionNotes":{"B":"Không phải Encryption Algorithm Level.","C":"Không phải Enterprise Access Layer.","D":"Không phải Event Alert Log."}},{"id":"std_c6_108","chapter":"6","question":"Mức EAL \"xác minh thiết kế hình thức\" (cao nhất) là:","options":{"A":"EAL1","B":"EAL5","C":"EAL7","D":"EAL4"},"answer":"C","family":"std_eal","style":"standard","section":"6.3","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"EAL7 là cao nhất, ứng với xác minh thiết kế hình thức.","optionNotes":{"A":"EAL1 là thấp nhất (kiểm thử chức năng).","B":"EAL5 là thiết kế bán hình thức.","D":"EAL4 là thiết kế, kiểm thử và rà soát có phương pháp."}},{"id":"std_c6_109","chapter":"6","question":"Firewall đạt chứng nhận EAL4+ KHÔNG có nghĩa là:","options":{"A":"Có quy trình khắc phục lỗ hổng","B":"Sản phẩm không còn lỗ hổng nào","C":"Chức năng bảo mật đúng như ST","D":"Thiết kế và quy trình phát triển đã được rà soát"},"answer":"B","family":"std_c6_109","style":"standard","section":"6.3","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"EAL4+ chỉ bảo đảm đánh giá đã thực hiện ở mức đó; nó không có nghĩa sản phẩm hết lỗ hổng.","optionNotes":{"A":"Có quy trình khắc phục lỗ hổng là điều chứng nhận có thể bao gồm.","C":"Chức năng đúng như ST là điều chứng nhận khẳng định.","D":"Rà soát thiết kế và quy trình phát triển là một phần của EAL4."}},{"id":"abbr_c6_110","chapter":"6","question":"PCI DSS là viết tắt của:","options":{"A":"Payment Control Interface Digital Signature Standard","B":"Public Cloud Infrastructure Data Security Suite","C":"Personal Credit Information Data Safety System","D":"Payment Card Industry Data Security Standard"},"answer":"D","family":"std_pci","style":"acronym","section":"6.5","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cũ","explanation":"PCI DSS là Payment Card Industry Data Security Standard.","optionNotes":{"A":"Không phải Payment Control Interface Digital Signature Standard.","B":"Không phải Public Cloud Infrastructure Data Security Suite.","C":"Không phải Personal Credit Information Data Safety System."}},{"id":"std_c6_111","chapter":"6","question":"PCI DSS do tổ chức nào ban hành?","options":{"A":"PCI SSC, có Visa, MasterCard… tham gia","B":"Bộ Công an Việt Nam","C":"ISO/IEC, tổ chức tiêu chuẩn quốc tế","D":"NIST, Viện Tiêu chuẩn và Công nghệ Hoa Kỳ"},"answer":"A","family":"std_pci","style":"standard","section":"6.5","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cũ","explanation":"PCI DSS do PCI SSC ban hành, với các hãng thẻ như Visa, MasterCard tham gia.","optionNotes":{"B":"Bộ Công an không ban hành PCI DSS.","C":"ISO/IEC ban hành dòng 27000, không phải PCI DSS.","D":"NIST ban hành FIPS và CSF."}},{"id":"std_c6_112","chapter":"6","question":"Theo slide, PCI DSS v4.0.1 gồm:","options":{"A":"6 chức năng, 106 tiểu mục","B":"11 lĩnh vực, 133 biện pháp","C":"12 yêu cầu, 6 mục tiêu","D":"7 mức EAL"},"answer":"C","family":"std_c6_112","style":"standard","section":"6.5","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"Slide ghi PCI DSS v4.0.1 có 12 yêu cầu, nhóm thành 6 mục tiêu.","optionNotes":{"A":"6 chức năng, 106 tiểu mục là NIST CSF 2.0.","B":"11 lĩnh vực, 133 biện pháp là 27002:2005.","D":"Có 7 mức EAL là của Common Criteria."}},{"id":"std_c6_113","chapter":"6","question":"Cửa hàng chuyển việc nhập thẻ sang cổng thanh toán sẽ:","options":{"A":"Được phép lưu CVV2 sau ủy quyền","B":"Hết mọi nghĩa vụ an toàn thông tin","C":"Tự động đạt chứng nhận ISO 27001","D":"Thu hẹp phạm vi tuân thủ PCI DSS"},"answer":"D","family":"std_c6_113","style":"standard","section":"6.5","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"Cửa hàng không còn tự nhập/lưu dữ liệu thẻ thì ít hệ thống chạm vào dữ liệu thẻ hơn, nên phạm vi PCI DSS thu hẹp.","optionNotes":{"A":"CVV2 không bao giờ được lưu sau ủy quyền.","B":"Vẫn còn nghĩa vụ, chỉ là phạm vi nhỏ hơn.","C":"PCI DSS và ISO 27001 là hai chứng nhận độc lập."}},{"id":"abbr_c6_114","chapter":"6","question":"FIPS là viết tắt của:","options":{"A":"Federal Information Processing Standards","B":"Federal Internet Privacy System","C":"Formal Integrity Protection Specification","D":"Framework for Information Protection Security"},"answer":"A","family":"std_fips","style":"acronym","section":"6.6","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cũ","explanation":"FIPS là Federal Information Processing Standards, tiêu chuẩn xử lý thông tin liên bang Hoa Kỳ.","optionNotes":{"B":"Không phải Federal Internet Privacy System.","C":"Không phải Formal Integrity Protection Specification.","D":"Không phải Framework for Information Protection Security."}},{"id":"std_c6_115","chapter":"6","question":"FIPS 140-2 quy định yêu cầu cho:","options":{"A":"Ứng dụng web xử lý dữ liệu thẻ","B":"Hệ thống quản lý ATTT của tổ chức","C":"Mô-đun mật mã bảo vệ thông tin SBU","D":"Quy trình ứng cứu sự cố mạng"},"answer":"C","family":"std_fips","style":"standard","section":"6.6","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cũ","explanation":"FIPS 140-2 quy định yêu cầu cho mô-đun mật mã bảo vệ thông tin nhạy cảm chưa phân loại (SBU).","optionNotes":{"A":"Ứng dụng xử lý thẻ thuộc PCI.","B":"Hệ thống quản lý ATTT là ISO 27001.","D":"Ứng cứu sự cố không phải phạm vi của FIPS 140-2."}},{"id":"abbr_c6_116","chapter":"6","question":"SBU trong FIPS 140-2 là:","options":{"A":"Standard Baseline Usage","B":"Sensitive but Unclassified","C":"Secure Business Unit","D":"Signed Binary Update"},"answer":"B","family":"abbr_c6_116","style":"acronym","section":"6.6","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cũ","explanation":"SBU là Sensitive but Unclassified, thông tin nhạy cảm nhưng không thuộc diện mật.","optionNotes":{"A":"Không phải Standard Baseline Usage.","C":"Không phải Secure Business Unit.","D":"Không phải Signed Binary Update."}},{"id":"std_c6_117","chapter":"6","question":"Theo slide cập nhật, chuẩn thay thế FIPS 140-2 là:","options":{"A":"FIPS 140-1 (1994)","B":"FIPS 197 (AES)","C":"FIPS 140-3 (2019)","D":"FIPS 186 (chữ ký số)"},"answer":"C","family":"std_fips3","style":"standard","section":"6.6","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"Theo slide cập nhật, FIPS 140-3 (2019) thay thế FIPS 140-2.","optionNotes":{"A":"FIPS 140-1 là bản trước 140-2.","B":"FIPS 197 là chuẩn thuật toán AES.","D":"FIPS 186 là chuẩn chữ ký số."}},{"id":"std_c6_118","chapter":"6","question":"Mức FIPS 140-3 thấp nhất yêu cầu xóa khóa khi mở vỏ là:","options":{"A":"Mức 1","B":"Mức 2","C":"Mức 4","D":"Mức 3"},"answer":"D","family":"std_fips3","style":"standard","section":"6.6","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"Mức 3 của FIPS 140 là mức thấp nhất yêu cầu phát hiện can thiệp vật lý và xóa khóa khi mở vỏ.","optionNotes":{"A":"Mức 1 không yêu cầu bảo vệ vật lý.","B":"Mức 2 chỉ yêu cầu dấu hiệu niêm phong (tamper-evident).","C":"Mức 4 cũng có yêu cầu này nhưng không phải mức thấp nhất."}},{"id":"abbr_c6_119","chapter":"6","question":"HSM, thiết bị giữ khóa ký giao dịch ngân hàng, là:","options":{"A":"Host Security Monitor","B":"Hardware Security Module","C":"Hybrid Storage Manager","D":"Hash Signing Method"},"answer":"B","family":"abbr_c6_119","style":"acronym","section":"6.6","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"HSM là Hardware Security Module, mô-đun phần cứng giữ khóa và ký.","optionNotes":{"A":"Không phải Host Security Monitor.","C":"Không phải Hybrid Storage Manager.","D":"Không phải Hash Signing Method."}},{"id":"std_c6_120","chapter":"6","question":"ISO/IEC 27701 tập trung vào:","options":{"A":"Hệ thống quản lý quyền riêng tư (PIMS)","B":"Đánh giá sản phẩm CNTT (Common Criteria)","C":"Hệ thống quản lý AI (AIMS)","D":"Quản lý rủi ro ATTT tổng quát"},"answer":"A","family":"std_privacy","style":"standard","section":"6.2","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"ISO/IEC 27701 mở rộng 27001 cho quản lý quyền riêng tư (PIMS).","optionNotes":{"B":"Common Criteria là ISO/IEC 15408.","C":"Quản lý AI là ISO/IEC 42001.","D":"Quản lý rủi ro là ISO/IEC 27005."}},{"id":"std_c6_121","chapter":"6","question":"ISO/IEC 42001:2023 là:","options":{"A":"Hướng dẫn biện pháp kiểm soát 27002","B":"Chuẩn đánh giá mô-đun mật mã","C":"Chuẩn chứng nhận hệ thống quản lý AI","D":"Khung chức năng an ninh mạng của NIST"},"answer":"C","family":"std_privacy","style":"standard","section":"6.2","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"ISO/IEC 42001:2023 là chuẩn chứng nhận hệ thống quản lý AI (AIMS).","optionNotes":{"A":"Hướng dẫn biện pháp là 27002.","B":"Đánh giá mô-đun mật mã là FIPS 140.","D":"Khung của NIST là CSF."}},{"id":"abbr_c6_122","chapter":"6","question":"PII trong ISO/IEC 27701 là:","options":{"A":"Protected Integrity Index","B":"Public Information Interface","C":"Private Internet Infrastructure","D":"Personally Identifiable Information"},"answer":"D","family":"abbr_c6_122","style":"acronym","section":"6.2","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"PII là Personally Identifiable Information, thông tin định danh cá nhân.","optionNotes":{"A":"Không phải Protected Integrity Index.","B":"Không phải Public Information Interface.","C":"Không phải Private Internet Infrastructure."}},{"id":"abbr_c6_123","chapter":"6","question":"DLP (biện pháp 8.12 của 27002:2022) là:","options":{"A":"Distributed Log Platform – nền tảng log","B":"Data Leakage Prevention – ngăn rò rỉ dữ liệu","C":"Digital License Protection – bảo vệ bản quyền","D":"Data Link Protocol – giao thức liên kết"},"answer":"B","family":"abbr_c6_123","style":"acronym","section":"6.1","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"DLP là Data Leakage Prevention, ngăn rò rỉ dữ liệu.","optionNotes":{"A":"Không phải nền tảng log.","C":"Không phải bảo vệ bản quyền.","D":"Không phải giao thức liên kết dữ liệu."}},{"id":"abbr_c6_124","chapter":"6","question":"CSF trong NIST CSF là:","options":{"A":"Cybersecurity Framework","B":"Common Security Format","C":"Certified Security Function","D":"Cloud Security Foundation"},"answer":"A","family":"std_csf","style":"acronym","section":"6.1","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"CSF là Cybersecurity Framework, khung an ninh mạng của NIST.","optionNotes":{"B":"Không phải Common Security Format.","C":"Không phải Certified Security Function.","D":"Không phải Cloud Security Foundation."}},{"id":"std_c6_125","chapter":"6","question":"Chức năng mới có trong NIST CSF 2.0 là:","options":{"A":"IDENTIFY","B":"RECOVER","C":"DETECT","D":"GOVERN"},"answer":"D","family":"std_csf","style":"standard","section":"6.1","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"NIST CSF 2.0 thêm chức năng mới GOVERN (quản trị), thành 6 chức năng.","optionNotes":{"A":"IDENTIFY đã có từ bản 1.x.","B":"RECOVER đã có từ bản 1.x.","C":"DETECT đã có từ bản 1.x."}},{"id":"std_c6_126","chapter":"6","question":"So với ISO/IEC 27001, NIST CSF 2.0:","options":{"A":"Là khung tự nguyện, không cấp chứng nhận","B":"Là luật bắt buộc tại Việt Nam","C":"Cấp chứng chỉ sau khi bên thứ ba đánh giá độc lập","D":"Chỉ áp dụng cho dữ liệu chủ thẻ"},"answer":"A","family":"std_csf","style":"standard","section":"6.1","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"NIST CSF 2.0 là khung tự nguyện, không có chứng nhận như ISO 27001.","optionNotes":{"B":"CSF là khung của Hoa Kỳ, không phải luật Việt Nam.","C":"Cấp chứng chỉ sau đánh giá độc lập là đặc điểm của ISO 27001.","D":"Chỉ cho dữ liệu thẻ là PCI DSS."}},{"id":"std_c6_127","chapter":"6","question":"Luật An toàn thông tin mạng có số hiệu:","options":{"A":"91/2025/QH15","B":"24/2018/QH14","C":"86/2015/QH13","D":"116/2025/QH15"},"answer":"C","family":"std_law_no","style":"standard","section":"6.7","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cũ","explanation":"Luật An toàn thông tin mạng là Luật số 86/2015/QH13.","optionNotes":{"A":"91/2025/QH15 là Luật Bảo vệ dữ liệu cá nhân.","B":"24/2018/QH14 là Luật An ninh mạng 2018.","D":"116/2025/QH15 là Luật An ninh mạng 2025."}},{"id":"std_c6_128","chapter":"6","question":"Luật An toàn thông tin mạng 86/2015/QH13 có hiệu lực từ:","options":{"A":"19/11/2015","B":"01/7/2016","C":"01/7/2026","D":"01/01/2019"},"answer":"B","family":"std_law_no","style":"standard","section":"6.7","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cũ","explanation":"Luật 86/2015/QH13 có hiệu lực từ 01/7/2016.","optionNotes":{"A":"19/11/2015 là ngày Quốc hội thông qua luật, không phải ngày hiệu lực.","C":"01/7/2026 là ngày hiệu lực của Luật An ninh mạng 2025.","D":"01/01/2019 là ngày hiệu lực của Luật An ninh mạng 2018."}},{"id":"std_c6_129","chapter":"6","question":"Theo slide cập nhật, Luật Bảo vệ dữ liệu cá nhân có số hiệu:","options":{"A":"116/2025/QH15","B":"24/2018/QH14","C":"91/2025/QH15","D":"86/2015/QH13"},"answer":"C","family":"std_law_no","style":"standard","section":"6.7","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"Theo slide cập nhật, Luật Bảo vệ dữ liệu cá nhân là 91/2025/QH15.","optionNotes":{"A":"116/2025/QH15 là Luật An ninh mạng 2025.","B":"24/2018/QH14 là Luật An ninh mạng 2018.","D":"86/2015/QH13 là Luật An toàn thông tin mạng."}},{"id":"std_c6_130","chapter":"6","question":"Luật ATTT mạng 2015 phân loại hệ thống thông tin theo:","options":{"A":"4 cấp độ","B":"5 cấp độ","C":"3 cấp độ","D":"7 cấp độ"},"answer":"B","family":"std_c6_130","style":"standard","section":"6.7","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cũ","explanation":"Luật ATTT mạng 2015 phân loại hệ thống thông tin theo 5 cấp độ.","optionNotes":{"A":"Không phải 4 cấp.","C":"Không phải 3 cấp.","D":"7 cấp là số mức EAL của Common Criteria."}},{"id":"std_c6_131","chapter":"6","question":"Theo Luật BVDLCN 2025 trong slide, thời hạn thông báo vi phạm là:","options":{"A":"72 giờ","B":"48 giờ","C":"24 giờ","D":"7 ngày"},"answer":"A","family":"std_c6_131","style":"standard","section":"6.7","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"Slide ghi thời hạn thông báo vi phạm dữ liệu cá nhân là 72 giờ.","optionNotes":{"B":"Không phải 48 giờ.","C":"Không phải 24 giờ.","D":"Không phải 7 ngày."}},{"id":"std_c6_132","chapter":"6","question":"Theo slide, Luật An ninh mạng 2025 (116/2025/QH15) thay thế:","options":{"A":"Chỉ Nghị định 13/2023 về dữ liệu cá nhân","B":"Luật Giao dịch điện tử 2005","C":"Bộ luật Hình sự 2015","D":"Luật ATTT mạng 2015 và Luật ANM 2018"},"answer":"D","family":"std_c6_132","style":"standard","section":"6.7","source":"Đề cương mục 6.1-6.7; slide Bài 6 bản cập nhật","explanation":"Slide nêu Luật An ninh mạng 2025 hợp nhất và thay thế Luật ATTT mạng 2015 và Luật ANM 2018.","optionNotes":{"A":"Theo slide, Nghị định 13/2023 được thay bằng NĐ 356 đi kèm Luật BVDLCN, không phải bởi Luật ANM 2025.","B":"Luật này không thay Luật Giao dịch điện tử.","C":"Luật này không thay Bộ luật Hình sự."}}]};
